/* ---------- clima ---------- */
/* El clima de cada partido se fija al construir el calendario y después el
   motor de partido lo lee: cambia el desgaste (cansancio) y la precisión
   (cuántas ocasiones terminan en gol). */
var CLIMAS={
 despejado:{n:"despejado",ic:"☀️",desgaste:0,  precision:1.00, d:"Tarde despejada, cancha en buen estado."},
 calor:    {n:"calor",    ic:"🌡️",desgaste:1.3,precision:0.97, d:"Calor pesado: se va a sentir en las piernas."},
 lluvia:   {n:"lluvia",   ic:"🌧️",desgaste:0.8,precision:0.89, d:"Llueve fuerte y la pelota queda pesada."},
 viento:   {n:"viento",   ic:"🌬️",desgaste:0.3,precision:0.92, d:"Viento cruzado que complica cada pelota alta."},
 frio:     {n:"frío",     ic:"❄️",desgaste:0.6,precision:0.96, d:"Frío de invierno y cancha dura."}
};
function climaDeFecha(mes,seed){
  const rr=azarFijo(semilla("clima-"+seed+"-"+mes));
  let tabla;
  if(mes>=6&&mes<=8) tabla=[["lluvia",3],["frio",3],["viento",2],["despejado",2]];        // invierno
  else if(mes===12||mes<=2) tabla=[["calor",3],["despejado",4],["viento",1]];              // verano
  else tabla=[["despejado",5],["viento",2],["lluvia",2],["calor",1]];                      // media estación
  const tot=tabla.reduce((s,x)=>s+x[1],0); let r=rr()*tot;
  for(const par of tabla){ r-=par[1]; if(r<=0) return par[0]; }
  return "despejado";
}
/* ---------- generación de calendario ---------- */
/* Round robin. n par → n-1 fechas por rueda. n impar (Segunda zonal de 7) → bye:
   se agrega un dummy, cada club juega n-1 partidos por rueda y tiene 1 fecha libre.
   7 clubes → 7 fechas de ida + 7 de vuelta, 12 PJ + 2 byes. Misma física en todas. */
function fixturesLiga(equipos){
  const ids0=equipos.map(e=>e.id), impar=ids0.length%2===1;
  const ids=impar?ids0.concat(["__BYE__"]):ids0.slice();
  const n=ids.length;
  const rot=ids.slice(1), fijo=ids[0], ruedas=[];
  for(let r=0;r<n-1;r++){
    const fecha=[]; const orden=[fijo].concat(rot);
    for(let i=0;i<n/2;i++){
      const a=orden[i], b=orden[n-1-i];
      if(a==="__BYE__"||b==="__BYE__") continue;
      fecha.push(r%2===0?[a,b]:[b,a]);
    }
    ruedas.push(fecha);
    rot.unshift(rot.pop());
  }
  const vuelta=ruedas.map(f=>f.map(p=>[p[1],p[0]]));
  return ruedas.concat(vuelta);
}
/* Fechas del calendario 1991: del 27 de abril al 22 de diciembre, una por semana */
function fechasTemporada(){
  const out=[]; let m=4,d=27;
  for(let i=0;i<30;i++){
    out.push({m:m,d:d});
    d+=7;
    while(d>[31,28,31,30,31,30,31,31,30,31,30,31][m-1]){ d-=[31,28,31,30,31,30,31,31,30,31,30,31][m-1]; m++; }
  }
  return out;
}
/* Construye el calendario completo del año para el club del jugador */
function ordenFecha(f){ return (f.m||1)*100+(f.d||1); }
function shuffleSeed(arr,seed){
  const a=arr.slice(); let s=seed||1;
  for(let i=a.length-1;i>0;i--){
    s=(s*9301+49297)%233280;
    const j=Math.floor((s/233280)*(i+1));
    const t=a[i]; a[i]=a[j]; a[j]=t;
  }
  return a;
}
/* Arma los 8 partidos de una fecha: usa fixtures oficiales si hay, el resto se empareja con semilla fija.
   7.9007 · un club NO puede aparecer en dos pares (antes algunos quedaban con 0 PJ). */
function aplicarFixtureHostil(cal){
  if(!cal||!cal.length) return cal;
  if(!(typeof E!=="undefined" && E && E.flags && E.flags.fixtureHostil)) return cal;
  cal.forEach(p=>{
    if(p.tipo!=="liga"||!p.local) return;
    const n=p.fecha||0;
    if(n && n<=10 && n%2===1){
      p.local=false;
      const riv=(typeof CLUB_POR_ID!=="undefined")?CLUB_POR_ID[p.rivalId]:null;
      if(riv) p.sede=riv.est||p.sede;
    }
  });
  return cal;
}
function emparejarFecha(anio,nFecha,clubId,rivalId){
  const pares=[]; const used={}; const seen={};
  const add=(a,b)=>{
    if(!a||!b||a===b) return;
    if(seen[a]||seen[b]) return;
    const k=a<b?a+"-"+b:b+"-"+a;
    if(used[k]) return;
    used[k]=1; seen[a]=1; seen[b]=1; pares.push([a,b]);
  };
  const pool=(typeof clubesLigaActual==="function"?clubesLigaActual()
    :(typeof LIGA_ACT!=="undefined"?LIGA_ACT:[])).map(c=>c.id);
  /* 7.9110 · un cruce oficial vale solo si los dos siguen en la liga: si la simulación bajó a Limache y subió a
     Cobreloa, el fixture real 2026 metía a Limache igual y dejaba a un club sin partido (o con dos) esa fecha */
  const enLiga=id=>!pool.length||pool.indexOf(id)>=0;
  if(clubId&&rivalId) add(clubId,rivalId);
  if(typeof FIXTURES_OFICIALES==="object"){
    Object.keys(FIXTURES_OFICIALES).forEach(cid=>{
      const fx=(FIXTURES_OFICIALES[cid]||{})[anio];
      if(!fx) return;
      const m=fx.find(x=>x.fecha===nFecha);
      if(!m) return;
      if(!enLiga(cid)||!enLiga(m.rival)) return;
      add(m.local?cid:m.rival, m.local?m.rival:cid);
    });
  }
  const ids=pool.filter(id=>!seen[id]);
  const hostil=(typeof E!=="undefined"&&E&&E.flags&&E.flags.fixtureHostil)?7919:0;
  const rest=shuffleSeed(ids,(anio||0)*100+(nFecha||1)*17+3+hostil);
  for(let i=0;i+1<rest.length;i+=2) add(rest[i],rest[i+1]);
  return pares;
}
/* 7.9110 · partidas guardadas con versiones viejas (7.9003 medido) traen fechas con un club jugando dos veces:
   la jornada quedó grabada en el save. Al cargar se reparan las fechas que faltan jugar: tu partido primero, se
   quitan los cruces repetidos y los que quedaron sueltos se emparejan entre ellos (misma fecha, misma zona). */
function sanearJornadas(){
  if(typeof E==="undefined"||!E||!Array.isArray(E.calendario)) return 0;
  let n=0;
  E.calendario.forEach(p=>{
    if(!p||p.tipo!=="liga"||p.jugado||!Array.isArray(p.jornada)) return;
    const usado={}, nueva=[], sueltos=[];
    const mio=p.rivalId?p.jornada.find(q=>q&&((q[0]===E.club&&q[1]===p.rivalId)||(q[1]===E.club&&q[0]===p.rivalId))):null;
    const orden=mio?[mio].concat(p.jornada.filter(q=>q!==mio)):p.jornada.slice();
    let roto=false;
    orden.forEach(q=>{
      if(!q||q[0]==="__BYE__"||q[1]==="__BYE__"||q[0]===q[1]){ nueva.push(q); return; }
      if(usado[q[0]]||usado[q[1]]){ roto=true; [q[0],q[1]].forEach(id=>{ if(!usado[id]&&sueltos.indexOf(id)<0) sueltos.push(id); }); return; }
      usado[q[0]]=usado[q[1]]=1; nueva.push(q);
    });
    if(!roto) return;
    const libres=sueltos.filter(id=>!usado[id]);
    for(let i=0;i+1<libres.length;i+=2) nueva.push([libres[i],libres[i+1]]);
    p.jornada=nueva; n++;
  });
  return n;
}
function construirCalendario(clubId, anio, conCopa){
  const cal=[];
  if(conCopa && anio===1991 && clubId==="CC"){
    COPA91.forEach((p,i)=>cal.push({
      tipo:"copa", torneo:"Copa Libertadores", ronda:p.ronda, rivalNombre:p.rival, rivalId:null,
      fuerzaRival:p.fuerza, local:p.local, sede:p.sede, f:p.f, jugado:false, clima:climaDeFecha(p.f.m,"copa"+anio+i),
      real:p.real, apodo:p.apodo||null, notaId:p.ronda+"-"+(cal.filter(x=>x.ronda===p.ronda).length)
    }));
    cal.push({
      tipo:"copa", torneo:"Copa Intercontinental", ronda:INTERC91.ronda, rivalNombre:INTERC91.rival, rivalId:null,
      fuerzaRival:INTERC91.fuerza, local:false, sede:INTERC91.sede, f:INTERC91.f, jugado:false,
      clima:"frio", real:INTERC91.real, apodo:"Tokio 1991", notaId:"INTERC-0"
    });
  }
  let fxOf=(typeof FIXTURES_OFICIALES!=="undefined"&&FIXTURES_OFICIALES[clubId])?FIXTURES_OFICIALES[clubId][anio]:null;
  /* 7.9110 · el fixture real de tu club sirve solo si todos sus rivales siguen en tu liga (si la simulación cambió
     ascensos y descensos, se arma uno nuevo en vez de saltarse las fechas contra el que ya no está) */
  if(fxOf){
    const ligaIds=((typeof clubesLigaActual==="function")?clubesLigaActual():[]).map(c=>c.id);
    if(ligaIds.length&&fxOf.some(p=>ligaIds.indexOf(p.rival)<0)) fxOf=null;
  }
  if(fxOf){
    fxOf.forEach((p,i)=>{
      const riv=CLUB_POR_ID[p.rival]; if(!riv) return;
      cal.push({tipo:"liga", torneo:anio>=2010?"Liga de Primera":"Campeonato Nacional", fecha:p.fecha, rivalId:p.rival,
        rivalNombre:riv.n, fuerzaRival:riv.fuerza, local:p.local,
        sede:p.local?((CLUB_POR_ID[clubId]&&CLUB_POR_ID[clubId].est)||"local"):riv.est,
        f:p.f, jugado:false, clima:climaDeFecha(p.f.m,"liga"+clubId+anio+i), real:p.real,
        jornada:emparejarFecha(anio,p.fecha,clubId,p.rival)});
    });
    cal.sort((a,b)=>ordenFecha(a.f)-ordenFecha(b.f));
    return aplicarFixtureHostil(cal);
  }
  if(anio===2026 && typeof LIGA_CC_2026!=="undefined" && esEraPrimeraChile() && !((typeof eraCustomDeClub==="function")&&eraCustomDeClub(clubId))){
    LIGA_CC_2026.forEach(p=>{
      const pares=emparejarFecha(anio,p.fecha,clubId,null);
      const mio=pares.find(x=>x[0]===clubId||x[1]===clubId);
      if(!mio) return;
      const local=mio[0]===clubId, rival=local?mio[1]:mio[0];
      const riv=CLUB_POR_ID[rival]; if(!riv) return;
      cal.push({tipo:"liga", torneo:"Liga de Primera", fecha:p.fecha, rivalId:rival,
        rivalNombre:riv.n, fuerzaRival:riv.fuerza, local:local,
        sede:local?CLUB_POR_ID[clubId].est:riv.est,
        f:p.f, jugado:false, clima:climaDeFecha(p.f.m,"liga"+clubId+anio+p.fecha),
        jornada:pares});
    });
    cal.sort((a,b)=>ordenFecha(a.f)-ordenFecha(b.f));
    return aplicarFixtureHostil(cal);
  }
  /* 7.65 · Segunda División: se juega SOLO contra la propia zona (Norte/Sur, 7 clubes → 12 fechas
     ida y vuelta). El resto de la fecha que se simula (part.jornada) queda acotado a la zona. */
  if(typeof E!=="undefined" && E && E.eraBase==="2026c"){
    const zonaDe=(typeof zonaSegDe==="function")?zonaSegDe:(typeof clubZona==="function"?clubZona:(()=>null));
    const zMia=zonaDe(clubId);
    const zonaClubs=LIGA_ACT.filter(c=>zonaDe(c.id)===zMia);
    if(zMia && zonaClubs.length>=2){
      const fxZ=fixturesLiga(zonaClubs), fechasZ=fechasTemporada();
      const zTxt="Segunda División · Zona "+(zMia==="norte"?"Norte":"Sur");
      fxZ.forEach((jornada,i)=>{
        const limpia=jornada.filter(p=>p[0]!==p[1]);   /* fuera los byes (zona impar) */
        const mio=limpia.find(p=>p[0]===clubId||p[1]===clubId);
        if(!mio) return;   /* fecha libre (bye): el jugador descansa */
        const local=mio[0]===clubId, rival=local?mio[1]:mio[0];
        if(!CLUB_POR_ID[rival]) return;
        cal.push({tipo:"liga", torneo:zTxt, fecha:i+1, rivalId:rival,
          rivalNombre:CLUB_POR_ID[rival].n, fuerzaRival:CLUB_POR_ID[rival].fuerza,
          local:local, sede:local?CLUB_POR_ID[clubId].est:CLUB_POR_ID[rival].est,
          f:fechasZ[i], jugado:false, clima:climaDeFecha(fechasZ[i].m,"liga"+clubId+anio+i), jornada:limpia});
      });
      cal.sort((a,b)=>(a.f.m*100+(a.f.d||15))-(b.f.m*100+(b.f.d||15)));
      return aplicarFixtureHostil(cal);
    }
  }
  /* liga registrada / clonada: no es Primera Chile ni B/C/AFA/2006/1925 */
  const eraClon=(typeof eraCustomDeClub==="function")?eraCustomDeClub(clubId):null;
  const eraCal=(typeof E!=="undefined" && E && E.eraBase && typeof LIGAS==="object" && LIGAS[E.eraBase] && !esEraHardcode(E.eraBase))?E.eraBase:eraClon;
  if(eraCal && typeof LIGAS==="object" && LIGAS[eraCal]){
    const clubs=LIGAS[eraCal];
    const nom=(typeof ERA==="object" && ERA[eraCal] && ERA[eraCal].n) || String(eraCal);
    const nFechas=Math.max(6, (clubs.length||2)*2);
    const fechasZ=(typeof fechasSemanales==="function")?fechasSemanales(2,1,nFechas,12):fechasTemporada();
    if(typeof calendarioZonal==="function"){
      const zonal=calendarioZonal(clubId, clubs, {torneo:nom, fechas:fechasZ, fase:"liga"});
      if(zonal&&zonal.length) return aplicarFixtureHostil(zonal);
    }
  }
  const fx=fixturesLiga(LIGA_ACT), fechas=fechasTemporada();
  fx.forEach((jornada,i)=>{
    const mio=jornada.find(p=>p[0]===clubId||p[1]===clubId);
    if(!mio) return;
    const local=mio[0]===clubId, rival=local?mio[1]:mio[0];
    cal.push({tipo:"liga", torneo:(typeof E!=="undefined"&&E&&E.eraBase==="2026b")?"Liga de Ascenso":((typeof E!=="undefined"&&E&&E.eraBase==="2026c")?"Segunda División":"Campeonato Nacional"), fecha:i+1, rivalId:rival,
      rivalNombre:CLUB_POR_ID[rival].n, fuerzaRival:CLUB_POR_ID[rival].fuerza,
      local:local, sede:local?CLUB_POR_ID[clubId].est:CLUB_POR_ID[rival].est,
      f:fechas[i], jugado:false, clima:climaDeFecha(fechas[i].m,"liga"+clubId+anio+i), jornada:jornada});
  });
  cal.sort((a,b)=>(a.f.m*100+(a.f.d||15))-(b.f.m*100+(b.f.d||15)));
  return aplicarFixtureHostil(cal);
}

