/* Devuelve el set de datos de club según la época (1991 o 2026). */
function datosEra(base){
  if(base===2006 && typeof CLUB_INFO_2006==="object")
    return {info:CLUB_INFO_2006, ind:IND_BASE_2006, caja:CAJA_BASE_2006};
  if(base===1925 && typeof CLUB_INFO_1925==="object")
    return {info:CLUB_INFO_1925, ind:IND_BASE_1925, caja:CAJA_BASE_1925};
  if(base===2026 || base==="2026b" || base==="2026c" || base==="arg2026")
    return {info:CLUB_INFO_2026, ind:IND_BASE_2026, caja:CAJA_BASE_2026};
  if(typeof LIGAS==="object" && LIGAS[base] && typeof CLUB_INFO_2026==="object")
    return {info:CLUB_INFO_2026, ind:IND_BASE_2026, caja:CAJA_BASE_2026};
  return {info:CLUB_INFO, ind:IND_BASE, caja:CAJA_BASE};
}
function infoClub(clubId){ return datosEra(E?E.eraBase:1991).info[clubId] || CLUB_INFO[clubId]; }

/* ---------------- arranque ---------------- */
function parseMarcadorReal(real,local){
  if(!real) return null;
  const p=String(real).split(/[-–]/).map(n=>parseInt(n,10));
  if(p.length<2||isNaN(p[0])||isNaN(p[1])) return null;
  return local?{gf:p[0],gc:p[1]}:{gf:p[1],gc:p[0]};
}
/* Carga resultados ya jugados hasta el corte (1/10/2026) y la tabla de referencia.
   No inventa partidos: usa `real` del fixture. El resto de la tabla es semilla. */
function aplicarCorte2026(){
  if(!E||E.anio!==2026) return;
  const corte=(typeof CORTE_2026!=="undefined")?CORTE_2026:{m:10,d:1};
  if(typeof TABLA_2026_CORTE==="object"){
    Object.keys(TABLA_2026_CORTE).forEach(id=>{
      if(E.tabla[id]) Object.assign(E.tabla[id], TABLA_2026_CORTE[id]);
    });
  }
  (E.calendario||[]).forEach(p=>{
    if((p.f.m*100+(p.f.d||1))>(corte.m*100+(corte.d||1))) return;
    if(!p.real) return;
    const sc=parseMarcadorReal(p.real,p.local);
    if(!sc) return;
    p.jugado=true; p.gf=sc.gf; p.gc=sc.gc;
  });
  const i=(E.calendario||[]).findIndex(p=>!p.jugado);
  E.idx=i<0?(E.calendario||[]).length:i;
  const yo=E.tabla[E.club];
  if(yo) E.temporada=Object.assign({sinGanar:0},yo);
  E.flags=E.flags||{}; E.flags.corte2026=true;
  if(typeof pushNotif==="function") pushNotif("Cortas en octubre","El campeonato ya se jugó hasta el 1/10. Los partidos anteriores están cargados. El próximo es el que sigue.","neutro");
}
function nuevaPartida(clubId,anio,modo,extra){
  /* 7.54 · no arrastrar la liga custom (ascenso/descenso) del save anterior:
     activarLiga corre ANTES de rehacer E, y si el E viejo traía ligaMod con el
     club anterior descendido, armaba un CLUB_POR_ID sin el club nuevo → crash. */
  if(typeof E!=="undefined" && E) E.ligaMod=null;
  let base=baseEra(anio);
  if(extra&&extra.epoca&&extra.epoca.liga) base=extra.epoca.liga;
  if(extra&&extra.categoria==="B") base="2026b";
  if(extra&&extra.categoria==="C") base="2026c";
  if(extra&&extra.categoria==="ARG") base="arg2026";
  if(extra&&extra.categoria==="2006") base=2006;
  if(extra&&extra.categoria==="1925") base=1925;
  if(typeof esClubB==="function" && esClubB(clubId) && (anio>=2010 || base===2026 || base==="2026b")) base="2026b";
  /* 7.49 · Segunda División Profesional (3er nivel) */
  if(typeof esClubC==="function" && esClubC(clubId) && (anio>=2010 || base===2026 || base==="2026c")) base="2026c";
  if(typeof esClubArg==="function" && esClubArg(clubId) && anio>=2010) base="arg2026";
  /* liga clonada / registrada: el club no está en Primera Chile */
  if(!(extra&&extra.categoria) && !(extra&&extra.epoca&&extra.epoca.liga)){
    const er=(typeof eraCustomDeClub==="function")?eraCustomDeClub(clubId):null;
    if(er){ base=er; if(anio<2010) anio=2026; }
  }
  /* 7.98 · un club que no jugó el Nacional 1991 no arranca en esa liga
     (Limache 2010, Segunda 2026, etc. no heredan Colo-Colo 1991). */
  if(base===1991 && typeof clubJugoNacional91==="function" && !clubJugoNacional91(clubId)){
    if(typeof esClubC==="function" && esClubC(clubId)) base="2026c";
    else if(typeof esClubB==="function" && esClubB(clubId)) base="2026b";
    else if(typeof esClubArg==="function" && esClubArg(clubId)) base="arg2026";
    else base=2026;
    anio=2026;
  }
  activarLiga(base);
  const D=datosEra(base);
  const info=D.info[clubId];
  /* 7.12 · red de seguridad: ese club no existe en esa época (ej: Coquimbo en 1991).
     La UI ya lo evita, pero no queremos un crash feo si llega una combinación inválida. */
  if(!info){
    if(typeof aviso==="function") aviso((typeof CLUB_INFO!=="undefined"&&CLUB_INFO[clubId]?CLUB_INFO[clubId].n:"Ese club")+" no está disponible en "+anio+".");
    console.warn("nuevaPartida: no hay datos de "+clubId+" para la época "+base);
    return false;
  }
  E={
    v:4, saveVer:SAVE_VER, club:clubId, eraBase:base, clubNombre:info.n, dt:info.dt, anio:anio, modo:modo||"historico",
    ind:Object.assign({},D.ind[clubId]),
    plata:D.caja[clubId].plata, deuda:D.caja[clubId].deuda,
    capital:45,
    rep:{publica:52,credibilidad:50,prensa:50,dureza:40},
    grupos:{}, estatutos:Object.assign({},ESTATUTO_INICIAL[clubId]),
    mods:[], flags:{}, plantel:[], calendario:[], idx:0,
    tabla:{}, decPend:[], decHechas:{}, bandeja:[], cronica:[], titulos:[],
    pendientesEncadenadas:[], notifs:[], ofertasPend:[], mercadoLog:{rechazadas:{},vendidos:[]},
    redes:[], promesas:[], historialAnual:[], ultimaFecha:[], prensaAuto:false,
    timeline:[], seguidores:Math.round((D.ind[clubId].hinchada+D.ind[clubId].prestigio)*280),
    tactica:{form:"4-4-2",estilo:"Equilibrado",presion:"Media",mentalidad:"Equilibrado",bloque:"Medio",ritmo:"Normal",bancaManual:null},
    precioEntrada:1, presupuesto:null, temporada:{pj:0,pg:0,pe:0,pp:0,gf:0,gc:0,pts:0,sinGanar:0},
    carrera:{club:clubId,desde:anio,despidos:0,clubes:[],evaluacion:null,fin:false},
    divergencias:[], coincidencias:[], staff:{deportivo:62,tesorero:60,prensa:58,cm:false}
  };
  GRUPOS.forEach(g=>{
    const poder=(PODER_CLUB[clubId]||{})[g.id]||45;
    const ap=((APROB_INICIAL[clubId]||{})[g.id])||0;
    E.grupos[g.id]={poder:poder,aprob:ap};
  });
  E.plantel=armarPlantel(clubId,anio,D.ind[clubId].plantel);
  /* 7.00 · época histórica de gloria (leyendas): sobrescribe identidad/indicadores/caja */
  if(extra&&extra.epoca){
    const ep=extra.epoca;
    if(ep.ind) E.ind=Object.assign(E.ind,ep.ind);
    if(ep.caja){ E.plata=ep.caja.plata; E.deuda=ep.caja.deuda; }
    if(ep.dt) E.dt=ep.dt;
    if(ep.etq) E.epocaEtq=ep.etq;
    E.epocaHist=ep.anio;
    E.seguidores=Math.round((E.ind.hinchada+E.ind.prestigio)*280);
  }
  E.calendario=construirCalendario(clubId,anio,true);
  E.precios=preciosDefault();
  reiniciarTabla();
  repartirDecisiones();
  normalizarEstado();
  if(extra&&extra.corte&&anio===2026) aplicarCorte2026();
  if(typeof rellenarPlantelLista==="function") rellenarPlantelLista();
  if(typeof sembrarRedes==="function") sembrarRedes();
  E._fuerzaV=2;
  calibrarPlantelALaTabla();
  ajustarSueldosAlMercado();
  /* 7.9111 · ahorros de arranque: unas cinco semanas del sueldo de este club (no 50 M para todos) */
  if(typeof sueldoContratoDT==="function"&&E.personal){ delete E.contratoDT; E.personal.bolsillo=Math.round(sueldoContratoDT()*5*10)/10; }
  guardar();
}
/* 7.9029 · tu once rinde lo que la liga dice que es tu club. Los planteles
   (reales con stats estimadas, o generados) no calzaban con la fuerza que usa
   el resto del torneo: Wanderers 1991 jugaba 19 puntos arriba de lo que era.
   Se corre el nivel de todos por igual (tope ±15), así la jerarquía interna
   del plantel no cambia: sigue siendo "aproximado", pero coherente. */
function fuerzaTablaPropia(){
  const c=(typeof LIGA_ACT!=="undefined"&&LIGA_ACT)?LIGA_ACT.find(x=>x.id===E.club):null;
  return c&&typeof c.fuerza==="number"?c.fuerza:null;
}
function calibrarPlantelALaTabla(){
  if(!E||!E.plantel||!E.plantel.length||typeof onceIdeal!=="function"||typeof fuerzaEquipo!=="function") return 0;
  const obj=fuerzaTablaPropia(); if(obj==null) return 0;
  /* se calibra la fuerza EFECTIVA con la táctica de arranque: el punto neutro.
     Desde acá, decidir bien la táctica suma y decidir mal resta. */
  const fz=fuerzaEquipo(onceIdeal());
  const d=Math.round(clamp(obj-(fz.ataque+fz.orden)/2,-15,15));
  if(!d) return 0;
  E.plantel.forEach(j=>{
    const n0=j.nivel||60, n1=clamp(n0+d,30,95);
    j.nivel=n1; j.proy=clamp((j.proy||n0)+d,30,97);
    if(j.sueldo) j.sueldo=Math.max(1,Math.round(j.sueldo*(n1*n1)/(n0*n0)));
    if(j.valor) j.valor=Math.max(1,Math.round(j.valor*(n1*n1)/(n0*n0)));
  });
  if(typeof mediaPlantel==="function") E.ind.plantel=clamp(Math.round(mediaPlantel()),0,100);
  E.calibracion={delta:d, objetivo:obj};
  return d;
}
/* 7.9029 · los sueldos los pone el mercado del club, no solo el nivel.
   Un jugador nivel 70 cobra más en Colo-Colo que en Limache, y los clubes
   gastan en planilla más o menos dos tercios de lo que les entra. Sin esto
   la taquilla de un grande (300× la de un chico) lo hacía rico sin gestionar. */
var SUELDO_CUOTA=0.64;
function factorMercado(){ return (typeof E!=="undefined"&&E&&E.factorMercado)||1; }
function potencialIngresos(){
  const ing=ingresosAnuales();
  const locales=(E.calendario||[]).filter(p=>p.local&&!p.amistoso).length;
  const taq=taquilla({tipo:"liga",local:true}).ingreso*locales;
  return ing.tv+ing.sponsors+ing.socios+(ing.digital||0)+taq;
}
function ajustarSueldosAlMercado(){
  if(!E||!E.plantel||!E.plantel.length) return 1;
  const base=planillaAnual();
  if(!base) return 1;
  const f=clamp(SUELDO_CUOTA*potencialIngresos()/base, 0.7, 2.3);
  E.plantel.forEach(j=>{ j.sueldo=Math.max(1,Math.round(j.sueldo*f)); });
  E.factorMercado=Math.round(f*100)/100;
  return E.factorMercado;
}
function reiniciarTabla(){
  E.tabla={};
  LIGA_ACT.forEach(c=>E.tabla[c.id]={pj:0,pg:0,pe:0,pp:0,gf:0,gc:0,pts:0});
}
/* puntos por victoria según la época (2 en 1991, 3 en 2026) */
function puntosVictoria(){
  if(E&&E.eraMod&&typeof E.eraMod.puntosVictoria==="number") return E.eraMod.puntosVictoria;
  return (E&&eraDe(E.eraBase)?eraDe(E.eraBase).puntosVictoria:2);
}
function reformaFed(id){
  return !!(E&&E.fed&&E.fed.reformas&&E.fed.reformas.indexOf(id)>=0);
}
function aplicarReformasAlTorneo(){
  if(!E) return;
  E.eraMod=E.eraMod||{};
  const era=(typeof eraDe==="function")?eraDe(E.eraBase):null;
  if(reformaFed("puntos")) E.eraMod.puntosVictoria=2;
  else delete E.eraMod.puntosVictoria;
  if(reformaFed("menos_desc")) E.eraMod.nDescensos=1;
  else delete E.eraMod.nDescensos;
  if(reformaFed("pro_grandes")){
    const base=(era&&era.cuposInternacional)||4;
    E.eraMod.cuposInternacional=base+2;
  } else if(!E.flags||!E.flags.fed_cupo_robado) delete E.eraMod.cuposInternacional;
  if(E.fed&&E.fed.presidente){
    E.fed.torneoAplicado=E.anio;
  }
}
function fedNivelContinental(){
  const n=(E&&E.flags&&E.flags.fed_conmebol)||0;
  if(n>=6) return "fifa";
  if(n>=3) return "conmebol";
  return null;
}
function aplicarSaltoFed(){
  if(!E) return null;
  E.fed=E.fed||{presidente:false,mandato:0,sospecha:0,reformas:[],electo:0};
  const n=(E.flags&&E.flags.fed_conmebol)||0;
  let subio=null;
  if(n>=3 && !E.fed.conmebolOk){
    E.fed.conmebolOk=true; subio="conmebol";
    if(typeof notificar==="function") notificar({t:"🌎 Peso en la CONMEBOL",tipo:"bueno",bandeja:true,
      d:"La confederación te reconoce. El siguiente escalón es la FIFA (sigue presionando)."});
  }
  if(n>=6 && !E.fed.fifaOk){
    E.fed.fifaOk=true; subio="fifa";
    if(typeof notificar==="function") notificar({t:"🌍 Llegaste a la FIFA",tipo:"bueno",bandeja:true,
      d:"Ya no solo mandas tu asociación: tienes silla en el mapa mundial. La cara de este nivel la arma el otro carril."});
  }
  return subio;
}
function aplicarGuerraFed(){
  if(!E||!E.flags||!(E.flags.fed_guerra>0)) return;
  E.eraMod=E.eraMod||{};
  const era=(typeof eraDe==="function")?eraDe(E.eraBase):null;
  const base=(E.eraMod.cuposInternacional!=null)?E.eraMod.cuposInternacional:((era&&era.cuposInternacional)||4);
  E.eraMod.cuposInternacional=base+Math.min(2, E.flags.fed_guerra);
  E.flags.fed_cupo_robado=E.flags.fed_guerra;
  if(typeof aplicarGrupos==="function") aplicarGrupos({sponsors:3,prensa:2,anfp:1});
  if(typeof postProc==="function" && (E.anio||2026)>=2008){
    const sig=(typeof fedSigla==="function")?fedSigla():"la asociación";
    postProc("@DeporteTotal","prensa",sig+" le disputa cupos y sponsors a la asociación vecina. Guerra fría continental.","neutro");
  }
}
/* Rellena campos nuevos en partidas guardadas de antes del roadmap 3.0.
   No sube la versión: solo agrega lo que falte sin tocar lo existente. */
/* 7.10 · versión del formato de save. Subir SOLO cuando cambie la estructura de E;
   migrarSave() debe traer los saves viejos al día antes de que el juego los use. */
var SAVE_VER=1;
function migrarSave(s){
  if(!s || typeof s!=="object") return s;
  let v=s.saveVer||0;
  /* futuras migraciones van acá, por versión:
     if(v<2){ ... transformar ...; v=2; } */
  s.saveVer=SAVE_VER;
  return s;
}
function normalizarEstado(){
  if(!E) return;
  migrarSave(E);
  if(!E.eraBase) E.eraBase=baseEra(E.anio);
  if(typeof initLigaMod==="function") initLigaMod();   /* ascenso/descenso: rosters por-save */
  if(typeof activarLiga==="function") activarLiga(E.eraBase);
  if(typeof aplicarReformasAlTorneo==="function") aplicarReformasAlTorneo();
  if(!E.flags) E.flags={};
  if(!Array.isArray(E.pendientesEncadenadas)) E.pendientesEncadenadas=[];
  if(!E.decProc||typeof E.decProc!=="object") E.decProc={};
  if(!E.temporada) E.temporada={pj:0,pg:0,pe:0,pp:0,gf:0,gc:0,pts:0,sinGanar:0};
  if(E.temporada.sinGanar===undefined) E.temporada.sinGanar=0;
  if(!Array.isArray(E.notifs)) E.notifs=[];
  if(!Array.isArray(E.ofertasPend)) E.ofertasPend=[];
  if(!E.mercadoLog) E.mercadoLog={rechazadas:{},vendidos:[]};
  if(!Array.isArray(E.redes)) E.redes=[];
  if(!Array.isArray(E.promesas)) E.promesas=[];
  if(!E.precios) E.precios=preciosDefault();
  else { const inf=(typeof inflacionEra==="function")?inflacionEra():1; sectoresActuales().forEach(s=>{ if(E.precios[s.id]==null) E.precios[s.id]=Math.round(s.ref*inf); }); }
  if(E.aforoExtra===undefined) E.aforoExtra=0;
  if(E.obras===undefined) E.obras=null;
  if(!E.staff) E.staff={deportivo:62,tesorero:60,prensa:58,cm:false};
  if(E.staff.cm===undefined) E.staff.cm=false;
  if(!Array.isArray(E.historialAnual)) E.historialAnual=[];
  if(!Array.isArray(E.ultimaFecha)) E.ultimaFecha=[];
  if(E.prensaAuto===undefined) E.prensaAuto=false;
  if(!Array.isArray(E.timeline)) E.timeline=[];
  if(E.seguidores===undefined) E.seguidores=Math.round((E.ind.hinchada+E.ind.prestigio)*280);
  /* 5.0 · Bloque 1 — perfil, vida social, dinastía y patrimonio personal */
  if(!E.perfil) E.perfil={nombre:"DT",nacimiento:((E.anio||2026)-38)+"-05-12",avatar:"retrato",orientacion:"Libre",vidaSocial:{publica:true,agenda:[]}};
  if(!E.perfil.vidaSocial) E.perfil.vidaSocial={publica:true,agenda:[]};
  if(!Array.isArray(E.perfil.vidaSocial.agenda)) E.perfil.vidaSocial.agenda=[];
  if(!E.dinastia) E.dinastia={generacion:1,linaje:"Tu linaje",limiteAnio:2100,historial:[],sucesionPendiente:false};
  if(!Array.isArray(E.dinastia.historial)) E.dinastia.historial=[];
  if(!E.dinastia.raiz) E.dinastia.raiz=E.perfil.nombre||"DT";
  if(!E.personal) E.personal={bolsillo:50,propiedades:[],autos:[]};
  if(E.personal.sueldo===undefined) E.personal.sueldo=8;
  if(typeof E.personal.bolsillo!=="number" || isNaN(E.personal.bolsillo)) E.personal.bolsillo=50;
  if(E.flags.desfalco===undefined) E.flags.desfalco=0;
  if(!E.config) E.config={autoPausa:true};
  if(E.config.spoiler===undefined) E.config.spoiler=(E.modo!=="libre");
  /* Vida 2.0: tinder/parejas y migración de avatar a orbes MSN (solo se mantiene 😎) */
  if(!E.perfil.tinder) E.perfil.tinder={matches:[]};
  if(!Array.isArray(E.perfil.tinder.matches)) E.perfil.tinder.matches=[];
  if(E.perfil.pareja===undefined) E.perfil.pareja=null;
  /* Vida 3.0: bienestar, familia y evolución de la relación */
  if(E.perfil.bienestar===undefined) E.perfil.bienestar=70;
  if(E.perfil.genero===undefined) E.perfil.genero="M";
  /* 7.9033 · el orbe azul era el avatar por defecto: pasa al retrato que envejece (se vuelve al orbe tocándolo) */
  if(E.perfil.avatar==="orb-azul" && !E.perfil._ret9033){ E.perfil.avatar="retrato"; E.perfil._ret9033=1; }
  if(["Hetero","Gay","Bi","Libre"].indexOf(E.perfil.orientacion)<0) E.perfil.orientacion="Libre";
  if(!Array.isArray(E.perfil.hijos)) E.perfil.hijos=[];
  if(E.perfil.pareja && E.perfil.pareja.nivel===undefined){ E.perfil.pareja.nivel=65; E.perfil.pareja.casades=!!E.perfil.pareja.casades; }
  if(E.perfil.avatar && E.perfil.avatar!=="😎" && E.perfil.avatar!=="retrato" && String(E.perfil.avatar).indexOf("orb-")!==0) E.perfil.avatar="retrato";   /* 7.9033: lo desconocido cae al retrato, no al orbe */
  if(typeof clausulaDe==="function" && Array.isArray(E.plantel)) E.plantel.forEach(function(j){ if(j&&!j.vendido) clausulaDe(j); });
  /* 5.0 · bolsa de valores del club + finanzas avanzadas */
  if(typeof normalizarBolsa==="function") normalizarBolsa();
  /* v4: planteles viejos con nombres inventados tipo "Luis Aránguiz" */
  if((E.v||0)<4){
    const hayFantasma=(E.plantel||[]).some(j=>!j.real && j.n && j.n.indexOf("Canterano")!==0);
    if(hayFantasma && typeof armarPlantel==="function"){
      E.plantel=armarPlantel(E.club,E.anio,(E.ind&&E.ind.plantel)||60);
    }
    E.v=4;
  }
  /* 5.0 · objetivos de temporada */
  if(!Array.isArray(E.objetivos)||!E.objetivos.length){
    E.objetivos=(typeof generarObjetivos==="function")?generarObjetivos():[];
  }
  /* 6.0 · motor de memoria */
  if(typeof normalizarMemoria==="function") normalizarMemoria();
  /* 6.21 · mesa de la barra */
  if(typeof normalizarBarra==="function") normalizarBarra();
  if(typeof normalizarLogros==="function") normalizarLogros();
  if(typeof normalizarStorylines==="function") normalizarStorylines();
  /* 6.24 · estado del jugador: minutos, estado y pie (pie determinístico por nombre) */
  (E.plantel||[]).forEach(j=>{
    if(j.minutosTemporada===undefined) j.minutosTemporada=0;
    if(!j.estado) j.estado=j.vendido?"vendido":(j.cedido?"cedido":(j.lesion>0?"lesion":"banca"));
    if(!j.pie && typeof semilla==="function") j.pie=(semilla(j.n)%4===0)?"izquierdo":"derecho";
  });
  /* 6.3 · PLOP: usuario, verificados y likes */
  if(!E.plopVerif) E.plopVerif={};
  if(!Array.isArray(E.plopLikes)) E.plopLikes=[];
  /* 6.7 · táctica: mentalidad estilo FM y designados de balón parado */
  if(E.tactica){ if(!E.tactica.mentalidad) E.tactica.mentalidad="Equilibrado";
    if(!E.tactica.bloque) E.tactica.bloque="Medio";
    if(!E.tactica.ritmo) E.tactica.ritmo="Normal";
    if(E.tactica.penalista===undefined) E.tactica.penalista=null;
    if(E.tactica.tiroLibre===undefined) E.tactica.tiroLibre=null;
    if(E.tactica.corner===undefined) E.tactica.corner=null;
    if(E.tactica.xiManual===undefined) E.tactica.xiManual=null;
    if(E.tactica.bancaManual===undefined) E.tactica.bancaManual=null;
    if(!E.tactica.roles) E.tactica.roles={}; }
  if(typeof rellenarPlantelLista==="function") rellenarPlantelLista();
  /* seguridad: sanear texto de usuario en la CARGA (frontera de confianza). saneaEstado
     (de Grok, en util.js) es idempotente y también corre en guardar(); acá lo llamo para
     que un slot que se dibuja antes de re-guardar (continuarPartida) tampoco inyecte HTML.
     saneaEstado cubre clubNombre/dt/plantel/timeline/plopUser; le sumo acá — sin tocar su
     archivo — los campos que quedaban sueltos: nombre del DT, linaje, pareja e hijos. */
  if(typeof saneaEstado==="function") saneaEstado(E);
  if(typeof saneaProfundo==="function") saneaProfundo(E);
  if(E._slot!=null&&!(typeof E._slot==="string"&&/^[A-Za-z0-9_-]{1,40}$/.test(E._slot))) E._slot=nuevoSlotId();   /* 7.9118 · ranura con forma rara → una nueva */   /* 7.9117 · todo texto de la partida, no solo los campos conocidos */
  if(typeof textoLimpio==="function"){
    if(E.perfil){
      if(E.perfil.nombre) E.perfil.nombre=textoLimpio(E.perfil.nombre,40)||"DT";
      if(E.perfil.pareja&&E.perfil.pareja.nombre) E.perfil.pareja.nombre=textoLimpio(E.perfil.pareja.nombre,40);
      /* 7.9116 · el nombre de la pareja vive en .n (no en .nombre): un archivo de partida manipulado ejecutaba código al abrir Vida */
      if(E.perfil.pareja&&E.perfil.pareja.n) E.perfil.pareja.n=textoLimpio(E.perfil.pareja.n,40);
      if(E.perfil.tinder&&Array.isArray(E.perfil.tinder.matches)) E.perfil.tinder.matches.forEach(function(m){ if(m){ if(m.n) m.n=textoLimpio(m.n,40); if(m.bio) m.bio=textoLimpio(m.bio,200); } });
      (E.perfil.hijos||[]).forEach(function(h){ if(h&&h.nombre) h.nombre=textoLimpio(h.nombre,40); });
    }
    if(E.dinastia){
      if(E.dinastia.linaje) E.dinastia.linaje=textoLimpio(E.dinastia.linaje,50);
      if(E.dinastia.raiz)   E.dinastia.raiz=textoLimpio(E.dinastia.raiz,40);
    }
  }
  if(typeof sanearJornadas==="function") sanearJornadas();   /* 7.9110 · saves viejos con un club dos veces en la fecha */
}
/* 7.9991 · bolsillo personal a prueba de saves viejos o a medias */
function bolsilloDT(delta){
  if(!E) return 0;
  if(!E.personal) E.personal={bolsillo:50,propiedades:[],autos:[]};
  if(typeof E.personal.bolsillo!=="number" || isNaN(E.personal.bolsillo)) E.personal.bolsillo=0;
  if(typeof delta==="number") E.personal.bolsillo=Math.max(0, E.personal.bolsillo+delta);
  return E.personal.bolsillo;
}
/* ---------- historial de temporadas (memoria a largo plazo) ---------- */
function tablaOrdenada(){
  const arr=clubesLigaActual().map(c=>Object.assign({id:c.id,n:c.n},E.tabla[c.id]));
  arr.sort((a,b)=>b.pts-a.pts||(b.gf-b.gc)-(a.gf-a.gc)||b.gf-a.gf);
  return arr;
}
function guardarHistorial(pos,campeon,copaGanada){
  if(!E.historialAnual) E.historialAnual=[];
  const arr=tablaOrdenada();
  const gol=E.plantel.filter(j=>!j.vendido).slice().sort((a,b)=>b.goles-a.goles)[0];
  E.historialAnual.unshift({
    anio:E.anio, era:E.eraBase, club:E.club, clubNombre:E.clubNombre,
    pos:pos, campeon:campeon, copa:!!copaGanada,
    tabla:arr.map(c=>({id:c.id,n:c.n,pj:c.pj,pg:c.pg,pe:c.pe,pp:c.pp,gf:c.gf,gc:c.gc,pts:c.pts})),
    goleador:(gol&&gol.goles>0)?{n:gol.n,goles:gol.goles}:null
  });
  if(E.historialAnual.length>40) E.historialAnual.length=40;
}
/* ============================================================
   Centro de notificaciones: TODO lo importante deja un aviso
   persistente y explicado, que se puede revisar cuando quieras.
   `acc` marca los avisos accionables (ej: una oferta por un jugador).
   ============================================================ */
function notificar(n){
  if(!E) return null;
  if(E._bulkSim){
    const t=(n&&n.t)||"";
    if(!/CAMPEÓN|Destitu|sin club|descens|ascens|Balance /i.test(t)) return null;
  }
  if(!E.notifs) E.notifs=[];
  const part=proximoPartido();
  const item={
    id:"n"+(E._nid=(E._nid||0)+1),
    t:n.t, d:n.d||"", extra:n.extra||"", tipo:n.tipo||"neutro",
    anio:E.anio, fecha:(part&&part.f?fechaTxt(part.f):"cierre de temporada"),
    leido:false, acc:n.acc||null
  };
  E.notifs.unshift(item);
  if(E.notifs.length>200) E.notifs.length=200;   /* 7.9066 · Avisos es un registro: guarda más */
  /* también entra a la bandeja semanal del escritorio, salvo que se pida lo contrario */
  if(n.bandeja!==false){
    E.bandeja.unshift({t:item.t,d:item.d,extra:item.extra,tipo:item.tipo,anio:E.anio});
    if(E.bandeja.length>20) E.bandeja.length=20;
  }
  return item;
}
/* ---------- 5.0 · Bloque 4 — interacción institucional ---------- */
function aplicarInteraccion(op){
  /* 7.9050 · el informante no vive en tu oficina: una vez cada 4 fechas (se revisa ANTES de cobrar) */
  E.flags=E.flags||{};
  if(op.soplo && E.flags.soploIdx!=null && (E.idx||0)-E.flags.soploIdx<4) return {ok:false,msg:"El informante vuelve en unas fechas."};
  if(op.capital && E.capital+op.capital<0) return {ok:false,msg:"No te alcanza el capital institucional."};
  if(op.plata && E.plata+op.plata<0) return {ok:false,msg:"No te alcanza la caja."};
  if(op.capital) aplicarEfectos({capital:op.capital});
  if(op.plata) aplicarEfectos({plata:op.plata});
  if(op.ef) aplicarEfectos(op.ef);
  if(op.grupos) aplicarGrupos(op.grupos);
  if(op.rep) aplicarRep(op.rep);
  if(op.flags) for(const k in op.flags) E.flags[k]=op.flags[k];
  if(op.soplo){
    /* 7.9050 · el informante no vive en tu oficina: una vez cada 4 fechas */
    E.flags.soploIdx=E.idx||0;
    const s=soploAnonimo(); guardar(); return {ok:true,soplo:s};
  }
  notificar({t:"Interacción: "+op.t,tipo:"neutro",d:op.d||"",bandeja:false});
  guardar(); return {ok:true};
}
function soploAnonimo(){
  const r=Math.random();
  if(r<0.4){
    agregarMod({id:"soplo_ventaja",n:"Data del rival",anios:1,ef:{liga:2}});
    notificar({t:"Soplo útil",tipo:"bueno",d:"El informante te pasó debilidades de los próximos rivales. Pequeña ventaja este año.",bandeja:false});
    return "útil";
  } else if(r<0.7){
    notificar({t:"Soplo sin valor",tipo:"neutro",d:"Puro humo. El tipo hablaba de memoria.",bandeja:false});
    return "humo";
  }
  E.ind.riesgo=clamp(E.ind.riesgo+6,0,100);
  notificar({t:"Soplo envenenado",tipo:"malo",d:"El «informante» quería sacarte plata y quedó dando vueltas con lo que le contaste. Sube el riesgo.",bandeja:false});
  return "trampa";
}
function notifsNoLeidas(){ return (E.notifs||[]).filter(n=>!n.leido).length; }
function notifsAccionables(){ return (E.notifs||[]).filter(n=>n.acc&&!n.acc.resuelta); }
function marcarLeidas(){ (E.notifs||[]).forEach(n=>{ n.leido=true; }); }
/* ---------------- helpers de estado ---------------- */
function modSuma(k){ let s=0; E.mods.forEach(m=>{ if(m.ef&&m.ef[k]) s+=m.ef[k]; }); return s; }
function agregarMod(m){
  const ex=E.mods.find(x=>x.id===m.id);
  if(ex){ ex.hasta=Math.max(ex.hasta,E.anio+(m.anios||1)); return; }
  E.mods.push({id:m.id,n:m.n,hasta:E.anio+(m.anios||1),ef:m.ef||{}});
}
function limpiarMods(){ E.mods=E.mods.filter(m=>m.hasta>=E.anio); }
function aplicarEfectos(ef){
  if(!ef||!E) return;
  /* 7.9101 · una caja que no es número (partida tocada) se comía la economía para siempre */
  if(typeof E.plata!=="number"||!isFinite(E.plata)) E.plata=0;
  if(typeof E.deuda!=="number"||!isFinite(E.deuda)) E.deuda=0;
  for(const k in ef){
    const v=ef[k];
    const n=typeof v==="number"?v:Number(v);
    if(!isFinite(n)) continue;
    if(k==="plata") E.plata+=n;
    else if(k==="deuda") E.deuda=Math.max(0,E.deuda+n);
    else if(k==="capital") E.capital=Math.max(0,(Number(E.capital)||0)+n);
    else if(E.ind&&E.ind[k]!==undefined) E.ind[k]=clamp((Number(E.ind[k])||0)+n,0,100);
  }
  /* 7.9106 · quedar en rojo sube el riesgo UNA vez por semana (antes +3 en cada gasto: un club chico quebrado sumaba
     +15 a la semana y en un mes caía en la crisis de escándalo sin haber hecho nada turbio) */
  if(E.plata<0){ E.deuda+=Math.abs(E.plata)*1.2; E.plata=0;
    const sem=(E.anio||0)+"-"+(E.idx||0);
    if(E.ind&&E._riesgoCajaSem!==sem){ E._riesgoCajaSem=sem; E.ind.riesgo=clamp((E.ind.riesgo||0)+3,0,100); } }
  if(!isFinite(E.plata)) E.plata=0;
  if(!isFinite(E.deuda)) E.deuda=0;
}
function aplicarGrupos(g){ if(!g) return; for(const k in g){ if(E.grupos[k]) E.grupos[k].aprob=clamp(E.grupos[k].aprob+g[k],-100,100); } }
function aplicarRep(r){ if(!r) return; for(const k in r){ if(E.rep[k]!==undefined) E.rep[k]=clamp(E.rep[k]+r[k],0,100); } }
/* ---------- banderas y efecto mariposa ----------
   Una opción o un desenlace puede dejar una bandera (`flag`/`flags`) que otros
   eventos leen fechas después, y puede `encadena`r una decisión más adelante. */
function aplicarBanderas(o){
  if(!o) return;
  if(typeof o.flag==="string") E.flags[o.flag]=true;
  if(o.flags) for(const k in o.flags) E.flags[k]=o.flags[k];
}
/* encadena:"idDecision"  ó  encadena:{id:"idDecision",en:3,peso:"alto"} */
function agendarEncadena(enc){
  if(!enc) return;
  const cfg=(typeof enc==="string")?{id:enc}:enc;
  if(!cfg.id) return;
  const fecha=E.idx+(cfg.en||3);
  const ya=E.pendientesEncadenadas.some(p=>p.id===cfg.id)
        || E.decPend.some(x=>x.id===cfg.id)
        || E.decHechas[cfg.id+"_"+E.anio];
  if(ya) return;
  E.pendientesEncadenadas.push({id:cfg.id,fecha:fecha,peso:cfg.peso||"medio"});
}
/* Se llama al avanzar: madura la cola de encadenados. Los que tienen `op` van a
   la bandeja de decisiones; los simples (solo efectos) se aplican al toque. */
function procesarEncadenadas(){
  if(!E.pendientesEncadenadas||!E.pendientesEncadenadas.length) return [];
  const listos=[], quedan=[];
  E.pendientesEncadenadas.forEach(p=>{ (p.fecha<=E.idx?listos:quedan).push(p); });
  E.pendientesEncadenadas=quedan;
  const disparadas=[];
  listos.forEach(p=>{
    const d=decisionPorId(p.id); if(!d) return;
    const clave=d.id+"_"+E.anio;
    if(E.decHechas[clave]||E.decPend.some(x=>x.id===d.id)) return;
    if(d.op){
      E.decPend.push({id:d.id,clave:clave,peso:p.peso||d.peso||"medio"});
      disparadas.push(d);
    } else {
      if(d.ef) aplicarEfectos(d.ef);
      if(d.grupos) aplicarGrupos(d.grupos);
      if(d.rep) aplicarRep(d.rep);
      aplicarBanderas(d);
      const extra=d.accion?ejecutarAccion(d.accion,d):"";
      const item=notificar({t:d.t,d:resolverTokens(d.d||"",E),extra:extra,tipo:d.tipo||"neutro"});
      disparadas.push(item);
    }
  });
  return disparadas;
}
/* Contexto que se evalúa cada semana: mala racha y oferta de medianoche.
   Devuelve una lista de novedades para avisar al jugador. */
function eventosDeContexto(){
  const avisos=[];
  procesarEncadenadas();
  /* mala racha: 4 partidos sin ganar → la prensa pide tu cabeza */
  if((E.temporada.sinGanar||0)>=4 && !E.flags.rachaLiquida
     && typeof ENCADENADAS!=="undefined" && decisionPorId("enc_racha")){
    E.flags.rachaLiquida=true;
    if(!E.decPend.some(x=>x.id==="enc_racha") && !E.decHechas["enc_racha_"+E.anio]){
      E.decPend.push({id:"enc_racha",clave:"enc_racha_"+E.anio,peso:"alto"});
      avisos.push("La prensa se te tiró encima por la racha");
    }
  }
  /* oferta de medianoche: la noche previa a una semifinal o final */
  const part=proximoPartido();
  if(part && (part.ronda==="FINAL"||part.ronda==="Semifinal")
     && !E.flags["medianoche_"+E.idx] && Math.random()<0.5
     && typeof ENCADENADAS!=="undefined" && decisionPorId("enc_medianoche")){
    E.flags["medianoche_"+E.idx]=true;
    if(!E.decPend.some(x=>x.id==="enc_medianoche") && !E.decHechas["enc_medianoche_"+E.anio]){
      E.decPend.push({id:"enc_medianoche",clave:"enc_medianoche_"+E.anio,peso:"alto"});
      avisos.push("Alguien te busca la noche antes del partido grande");
    }
  }
  return avisos;
}
function apoyoPonderado(posturas){
  if(!posturas) return 0;
  let num=0,den=0;
  for(const k in posturas){
    const g=E.grupos[k]; if(!g) continue;
    num+=posturas[k]*(g.poder/100)*(1+g.aprob/200); den+=g.poder/100;
  }
  return den?num/den:0;
}
function aprobacionMedia(){
  let s=0,p=0;
  GRUPOS.forEach(g=>{ const x=E.grupos[g.id]; s+=x.aprob*x.poder; p+=x.poder; });
  return p?s/p:0;
}
/* ---------------- decisiones ---------------- */
function decisionesDisponibles(){
  const propias=DECISIONES.filter(d=>d.club===E.club&&d.anio===E.anio)
    .filter(d=>typeof decisionCabeEnClub!=="function"||decisionCabeEnClub(d));
  const bolsa=BOLSA.filter(d=>{
    if(d.cuando&&!d.cuando(E)) return false;
    if(typeof decisionCabeEnClub==="function"&&!decisionCabeEnClub(d)) return false;
    return true;
  });
  return propias.concat(bolsa);
}
function repartirDecisiones(){
  const ya=new Set(E.decPend.map(x=>x.id));
  decisionesDisponibles().forEach(d=>{
    const clave=d.id+"_"+E.anio;
    if(E.decHechas[clave]||ya.has(d.id)) return;   /* FIX: dedup por id (antes comparaba id-set vs clave, no coincidía nunca → duplicaba) */
    const mesActual=E.calendario[E.idx]?E.calendario[E.idx].f.m:2;
    if(d.mes && d.mes>mesActual) return;
    E.decPend.push({id:d.id,clave:clave,peso:d.peso||"medio"});
  });
}
function requisitoCumplido(op){
  const r=op.req; if(!r) return {ok:true,txt:""};
  const faltan=[];
  if(r.plata&&E.plata<r.plata) faltan.push("faltan "+plata(r.plata-E.plata));
  if(r.capital&&E.capital<r.capital) faltan.push("falta capital institucional");
  if(r.grupo){ const g=E.grupos[r.grupo[0]]; if(!g||g.aprob<r.grupo[1]) faltan.push("necesitas apoyo de "+GRUPO_POR_ID[r.grupo[0]].n); }
  if(r.estatuto&&E.estatutos[r.estatuto[0]]!==r.estatuto[1]) faltan.push("requiere otro estatuto");
  return {ok:faltan.length===0,txt:faltan.join(" · ")};
}
function textoRequisitos(op){
  const r=op.req; if(!r) return "";
  const p=[];
  if(r.plata) p.push(plata(r.plata));
  if(r.capital) p.push(r.capital+" de capital institucional");
  if(r.grupo) p.push("apoyo de "+GRUPO_POR_ID[r.grupo[0]].n);
  return p.length?("Requiere: "+p.join(" · ")):"";
}
/* Resolución oculta: pesa el estado, no el dado */
function resolverDecision(dec,idx){
  const op=dec.op[idx];
  const chk=requisitoCumplido(op); if(!chk.ok) return null;
  let score=58;
  score-=(op.dif||40)*0.55;
  const capEf=Math.min(120,E.capital);   /* el capital ya no tiene tope, pero su efecto sí */
  const rel={institucional:capEf,refuerzos:E.ind.prestigio,finanzas:100-clamp(E.deuda/40,0,70),
    camarin:E.ind.moral,preparacion:E.ind.plantel,hinchada:E.ind.hinchada,cantera:E.ind.cantera,
    prensa:E.rep.prensa,gris:E.rep.dureza};
  const base=rel[dec.buzon]!=null?rel[dec.buzon]:55;
  score+=(base-50)*0.30;
  score+=(capEf-45)*0.12;
  score+=apoyoPonderado(dec.posturas)*0.10;
  score+=(E.rep.credibilidad-50)*0.10;
  score-=Math.max(0,E.ind.riesgo-45)*0.20;
  score+=rnd(-11,11);
  const tier=score>=58?"bien":(score>=40?"mitad":"mal");
  const res=op[tier]||op.mitad||op.bien;

  if(op.ef) aplicarEfectos(op.ef);
  if(op.grupos) aplicarGrupos(op.grupos);
  if(op.rep) aplicarRep(op.rep);
  if(res.ef) aplicarEfectos(res.ef);
  if(res.grupos) aplicarGrupos(res.grupos);
  if(res.rep) aplicarRep(res.rep);
  (res.mods||[]).forEach(agregarMod);
  aplicarBanderas(op); aplicarBanderas(res);
  agendarEncadena(op.encadena); agendarEncadena(res.encadena);
  const accion=res.accion||op.accion;
  let extra=accion?ejecutarAccion(accion,dec):"";

  if(dec.op.some(o=>o.hist)){
    if(op.hist) E.coincidencias.push({anio:E.anio,t:dec.t});
    else E.divergencias.push({anio:E.anio,t:dec.t,elegido:op.t});
  }
  E.decHechas[dec.id+"_"+E.anio]={op:idx,tier:tier,txt:res.txt,t:op.t,hist:!!op.hist,extra:extra};
  E.decPend=E.decPend.filter(x=>x.id!==dec.id);
  if(E.decProc&&E.decProc[dec.id]) delete E.decProc[dec.id];
  guardar();
  return {tier:tier,txt:res.txt,extra:extra,hist:!!op.hist};
}
/* ---------------- acciones especiales ---------------- */
/* 6.17 · ata el nombre del jugador a la carta para que la consecuencia toque a ESE jugador */
function atarFicha(dec,j){ if(dec&&j) dec.ficha={n:j.n}; return dec; }
function ejecutarAccion(a,dec){
  const [nombre,arg]=a.split(":");
  switch(nombre){
    case "venderFicha":{  /* vende al jugador que NOMBRA la carta (ficha snapshoteada), no al más caro */
      const nom=(dec&&dec.ficha&&dec.ficha.n)||arg;
      const j=(E.plantel||[]).find(x=>x.n===nom&&!x.vendido);
      if(!j) return "";
      return venderJugador(j);
    }
    case "venderNombre":{  /* nombre baked en la acción (venderNombre:Iván Román) */
      const j=(E.plantel||[]).find(x=>x.n===arg&&!x.vendido);
      if(!j) return "";
      return venderJugador(j);
    }
    case "lesionFicha":{  /* lesiona al jugador que nombra la carta (ficha) */
      const nom=dec&&dec.ficha&&dec.ficha.n;
      const j=(E.plantel||[]).find(x=>x.n===nom&&!x.vendido);
      if(!j) return ""; j.lesion=ri(2,4);
      return j.n+" volvió tocado y queda unas semanas afuera.";
    }
    case "cansarFicha":{  /* el jugador de la ficha vuelve con la forma baja */
      const nom=dec&&dec.ficha&&dec.ficha.n;
      const j=(E.plantel||[]).find(x=>x.n===nom&&!x.vendido);
      if(!j) return ""; j.forma=clamp((j.forma||70)-12,20,99);
      return j.n+" volvió cansado de la gira, con la forma justa.";
    }
    case "lesionAlAzar":{
      const sanos=E.plantel.filter(j=>!j.lesion&&!j.vendido);
      if(!sanos.length) return "";
      const j=elige(sanos); j.lesion=ri(2,6);
      return j.n+" queda fuera unas semanas por lesión.";
    }
    case "lesionAToken":{  /* lesiona al MISMO jugador que nombra el texto (continuidad) */
      let j=jugadorPorToken(arg,E);
      if(!j||j.vendido){ const sanos=E.plantel.filter(x=>!x.lesion&&!x.vendido); if(!sanos.length) return ""; j=elige(sanos); }
      j.lesion=ri(3,7);
      return j.n+" recayó y queda fuera unas semanas. Te lo habían advertido.";
    }
    case "venderTitular":{
      const l=E.plantel.filter(j=>!j.vendido).sort((a,b)=>b.valor-a.valor);
      if(!l.length) return "";
      const j=l[ri(0,Math.min(2,l.length-1))];
      return venderJugador(j);
    }
    case "venderToken":{
      const j=jugadorPorToken(arg,E); if(!j) return "";
      return venderJugador(j);
    }
    case "marcarVentaFutura":{
      const j=jugadorPorToken(arg,E); if(!j) return "";
      j.ventaFin=true; return j.n+" seguirá hasta fin de temporada y después se va.";
    }
    case "mejorarToken":{
      const j=jugadorPorToken(arg,E); if(!j) return "";
      j.sueldo=Math.round(j.sueldo*1.4); j.moral=clamp(j.moral+15,0,100);
      return j.n+" renovó con mejor contrato.";
    }
    case "ficharTres":{
      return "Refuerzos incorporados al plantel.";
    }
    case "ficharLibre":{
      const rr=azarFijo(semilla("libre"+E.anio+E.idx));
      const j=generarJugador(rr,E.ind.plantel+4,elige(["DEF","VOL","DEL"]),ri(26,32));
      j.contrato.hasta=E.anio+2; E.plantel.push(j);
      return "Se incorpora "+j.n+" ("+j.pos+", nivel "+j.nivel+").";
    }
    case "subirJuvenil":{
      const rr=azarFijo(semilla("juv"+E.anio+E.idx));
      const j=generarJugador(rr,E.ind.cantera*0.8+10,elige(["DEF","VOL","DEL"]),ri(17,20));
      j.proy=clamp(j.proy+12,40,96); j.contrato.hasta=E.anio+4; j.rasgos=["de la cantera"];
      E.plantel.push(j);
      return "Sube al primer equipo "+j.n+" ("+j.edad+" años, proyección "+j.proy+").";
    }
    case "perderPuntos":{ E.temporada.pts=Math.max(0,E.temporada.pts-2); return "Se pierde una fecha por no presentarse."; }
    case "cisma":{
      E.flags.cisma=true;
      aplicarEfectos({socios:-25,hinchada:-20,prestigio:-10});
      return "Un grupo de socios funda un club nuevo con el nombre y los colores originales. Desde ahora son tus enemigos.";
    }
    case "limpiaBandera":{
      if(arg) delete E.flags[arg];
      return "";
    }
    case "limpiaDesfalco":{
      E.flags.desfalco=0; E.flags.investigacionAbierta=false;
      return "Se regularizaron los fondos y se cierra la causa.";
    }
    case "cierraInvestigacion":{
      E.flags.investigacionAbierta=false;
      return "La investigación se archiva por ahora.";
    }
    case "camadaBorghi":{
      E.flags.camadaBorghi=true;
      E.ind.cantera=clamp(E.ind.cantera+8,0,100);
      if(typeof PLANTEL_CC_2006==="undefined") return "Aparece una generación dorada en las inferiores.";
      const joyas=["Matías Fernández","Arturo Vidal","Alexis Sánchez","Jorge Valdivia","Humberto Suazo"];
      const sumados=[];
      PLANTEL_CC_2006.filter(a=>joyas.indexOf(a[0])>=0).forEach(a=>{
        if(E.plantel.some(j=>j.n===a[0]&&!j.vendido)) return;
        const j=jugadorDesde(a); j.contrato.hasta=E.anio+4; j.real=true; E.plantel.push(j); sumados.push(j.n);
      });
      return sumados.length?("Irrumpen desde las inferiores: "+sumados.join(", ")+". Proyección de venta al extranjero.") :"Aparece una generación dorada en las inferiores.";
    }
  }
  return "";
}
/* 6.10 · caras largas: reconquistar jugadores descontentos con plata */
function jugadoresDescontentos(){
  return E.plantel.filter(j=>!j.vendido&&!j.cedido&&(j.moral||70)<55).sort((a,b)=>(a.moral||70)-(b.moral||70));
}
function costoReconquista(j){ return Math.round(30+(j.valor||100)*0.05+(j.nivel||60)*0.6); }
function reconquistarJugador(j){
  const costo=costoReconquista(j);
  if(E.plata<costo) return {ok:false,msg:"No te alcanza la caja ("+plata(costo)+")"};
  aplicarEfectos({plata:-costo});
  j.moral=clamp((j.moral||70)+ri(22,32),0,100);
  aplicarGrupos({camarin:4});
  if(typeof recordar==="function") recordar("camarin","le pusiste un plus para reconquistar a "+j.n,{quien:j.n,peso:"bajo",tono:"bueno"});
  E.flags.reconquistas=(E.flags.reconquistas||0)+1;
  if(E.flags.reconquistas>=3 && typeof desbloquear==="function") desbloquear("reconquista");
  return {ok:true,costo:costo};
}
function venderJugador(j,monto){
  monto=monto||Math.round(j.valor*rnd(.75,1.2));
  j.vendido=true; j.estado="vendido";
  E.plata+=monto;
  E.ind.plantel=clamp(E.ind.plantel-Math.round(j.nivel/14),0,100);
  E.mercadoLog=E.mercadoLog||{}; E.mercadoLog.vendidos=E.mercadoLog.vendidos||[];
  E.mercadoLog.vendidos.push({n:j.n,monto:monto,anio:E.anio});
  const simbolo=j.rasgos&&(j.rasgos.indexOf("ídolo")>=0||j.rasgos.indexOf("de la casa")>=0);
  if(simbolo){
    aplicarGrupos({hinchada:-12});
    if(typeof postProc==="function"&&typeof HANDLES_HINCHA!=="undefined")
      postProc(elige(HANDLES_HINCHA),"hincha","Venden a "+j.n+", un símbolo del club. A la gente esto no le entra.","malo");
    /* 6.21 · si le habías jurado a la barra que no lo vendías, rompes el pacto */
    if(typeof romperPacto==="function") romperPacto("Vendiste a "+j.n+", que habías jurado no tocar.",j.n);
  }
  if(typeof recordar==="function") recordar("venta","vendiste a "+j.n+" por "+plata(monto),
    {quien:j.n,peso:(simbolo||j.nivel>=80)?"alto":"medio",tono:"riesgo"});
  if(typeof notificar==="function") notificar({t:"Se fue "+j.n,tipo:"malo",bandeja:true,
    d:"Se vendió a "+j.n+" ("+j.pos+") por "+plata(monto)+". "+(simbolo?"Un símbolo del club: la hinchada lo va a sentir.":"El plantel pierde una pieza.")});
  return "Se fue "+j.n+" por "+plata(monto)+".";
}
/* ---------------- economía ---------------- */
function planillaAnual(){ return E.plantel.filter(j=>!j.vendido&&!j.cedido).reduce((s,j)=>s+j.sueldo,0); }

/* Sectores del estadio: cada uno con su cuota de aforo, precio de referencia y
   elasticidad (la galería es la más sensible al precio; la marquesina, la que
   menos). El jugador fija el precio de cada sector con sliders en Finanzas. */
var SECTORES=[
 {id:"galeria",   n:"Galería popular", ic:"🎉", cuota:0.55, ref:1200, elast:1.5, min:300,  max:5000},
 {id:"tribuna",   n:"Tribuna",         ic:"🪑", cuota:0.33, ref:2500, elast:1.0, min:800,  max:9000},
 {id:"marquesina",n:"Marquesina",      ic:"🥂", cuota:0.12, ref:6000, elast:0.6, min:2000, max:22000}
];
/* sectores y aforo REALES del club (si tiene ficha en data-estadios), con fallback genérico */
function sectoresActuales(){
  if(typeof sectoresDe==="function" && E && E.club){ const s=sectoresDe(E.club); if(s&&s.length) return s; }
  return SECTORES;
}
function aforoActual(){
  let base=null;
  if(typeof aforoDe==="function" && E && E.club) base=aforoDe(E.club);
  if(!base) base=((typeof CLUB_POR_ID!=="undefined"&&E&&CLUB_POR_ID[E.club])||{aforo:30000}).aforo;
  return base+((E&&E.aforoExtra)||0);
}
function preciosDefault(){
  const f=(typeof inflacionEra==="function"&&E)?inflacionEra():1;
  const o={}; sectoresActuales().forEach(s=>o[s.id]=Math.round(s.ref*f)); return o;
}
function ocupBase(part){
  let o=0.30+E.ind.hinchada/220+E.ind.estadio/500;
  if(part){ if(part.tipo==="copa") o+=0.20; if(part.ronda==="FINAL"||part.ronda==="Semifinal") o+=0.18; }
  if(E.temporada&&E.temporada.pts>E.temporada.pj*1.6) o+=0.08;
  o+=modSuma("local")/100;
  o*=(1+(modSuma("taquilla")||0));
  return o;
}
/* deuda alta o hinchada en crisis → se clausuran sectores y cae el aforo */
function clausuraFactor(){
  let f=1;
  if(E.deuda>4000) f=Math.min(f,0.75);
  else if(E.deuda>3000) f=Math.min(f,0.90);
  if(E.flags&&E.flags.tribunaCerrada) f=Math.min(f,0.72);
  if(E.deuda>4000 && E.flags&&E.flags.tribunaCerrada) f=Math.min(f,0.60);
  return f;
}
function tribunaCerrada(){ return !!(E&&E.flags&&E.flags.tribunaCerrada); }
/* 7.9026 · CALIBRACIÓN DE TAQUILLA. Medido en una temporada simulada: un partido de local
   de Colo-Colo dejaba 818 (2,2× su contrato de TV de TODO el año) y la taquilla de la
   temporada cubría 7× sus costos totales. Resultado: la caja subía sola (20k → 91k en 5
   años sin hacer nada) y la plata dejaba de importar. El resto de la economía (TV,
   sponsors, socios, planilla) está en otra escala; la taquilla era la que se salía.
   Con 0.22: un grande con resultados normales cierra el año algo arriba (+500 a +1.500),
   uno chico estructuralmente abajo (−400 a −800) y tiene que vender o endeudarse. O sea:
   manejar la institución vuelve a doler. Un solo número para recalibrar si hace falta. */
var FACTOR_TAQUILLA=0.22;
function taquilla(part){
  const aforo=aforoActual();
  const base=ocupBase(part);
  const infl=(typeof inflacionEra==="function")?inflacionEra():1;
  const precios=E.precios||preciosDefault();
  const clau=clausuraFactor();
  let gente=0, ingreso=0;
  sectoresActuales().forEach(s=>{
    const cap=Math.round(aforo*s.cuota*clau*(E.ind.estadio/100*0.4+0.6));
    const precio=precios[s.id]||Math.round(s.ref*infl);
    const factorPrecio=Math.pow((s.ref*infl)/Math.max(1,precio), s.elast);
    const ocup=clamp(base*factorPrecio, 0.04, 0.99);
    const g=Math.round(cap*ocup);
    gente+=g; ingreso+=g*precio;
  });
  return {gente:gente, ingreso:Math.round(ingreso*FACTOR_TAQUILLA/1000000)};
}
/* 6.3 · desglose por butaca (para documentar aforo, precio y ganancia estimada de cada sector) */
function taquillaPorSector(part){
  const aforo=aforoActual();
  const base=ocupBase(part);
  const infl=(typeof inflacionEra==="function")?inflacionEra():1;
  const precios=E.precios||preciosDefault();
  const clau=clausuraFactor();
  return sectoresActuales().map(s=>{
    const cap=Math.round(aforo*s.cuota*clau*(E.ind.estadio/100*0.4+0.6));
    const precio=precios[s.id]||Math.round(s.ref*infl);
    const factorPrecio=Math.pow((s.ref*infl)/Math.max(1,precio), s.elast);
    const ocup=clamp(base*factorPrecio, 0.04, 0.99);
    const g=Math.round(cap*ocup);
    return {id:s.id, n:s.n, ic:s.ic, cap:cap, precio:precio, gente:g, ocup:Math.round(ocup*100),
      ingreso:Math.round(g*precio*FACTOR_TAQUILLA/1000000)};
  });
}
function ingresoPartidoLocal(part){ return taquilla(part); }
/* proyección para la UI: taquilla de un partido de local "tipo" con precios dados */
function proyeccionTaquilla(precios){
  const guard=E.precios; if(precios) E.precios=precios;
  const r=taquilla({tipo:"liga"});
  E.precios=guard; return r;
}
function precioPromedioRatio(){
  const infl=(typeof inflacionEra==="function")?inflacionEra():1;
  const precios=E.precios||preciosDefault();
  let num=0,den=0; sectoresActuales().forEach(s=>{ const p=precios[s.id]||s.ref*infl; num+=(p/(s.ref*infl))*s.cuota; den+=s.cuota; });
  return den?num/den:1;
}
/* 7.9144 · ¿conviene bajar las entradas? No es un temporizador ni «hinchada bajo 45».
   Compara el precio con el justo de la época (la inflación del país ya está en el ref),
   la gente que entraría a ese precio y la que entra hoy. Si el recinto se vacía por el
   precio, se ofrece. Si la hinchada está baja pero el precio ya es el justo, no. */
function entradasMedicion(){
  if(typeof E==="undefined"||!E||!E.ind) return {ofrecer:false,ratio:1,porque:""};
  const ratio=(typeof precioPromedioRatio==="function")?precioPromedioRatio():1;
  const justo=(typeof preciosDefault==="function")?preciosDefault():null;
  const ahora=(typeof proyeccionTaquilla==="function")?proyeccionTaquilla():{gente:0,ingreso:0};
  const enJusto=(justo&&typeof proyeccionTaquilla==="function")?proyeccionTaquilla(justo):ahora;
  const aforo=Math.max(1,(typeof aforoActual==="function")?aforoActual():1);
  const gA=ahora.gente||0, gJ=Math.max(1,enJusto.gente||0);
  const rel=gA/gJ;
  const ocup=gA/aforo;
  const caro=ratio>=1.12;
  const vacio=rel<=0.78 && gA+80<gJ;
  const ofrecer=!!(caro&&vacio&&E.precios);
  let porque="";
  if(ofrecer){
    const infl=(typeof inflacionEra==="function")?inflacionEra():1;
    const caja=Math.round(E.plata||0);
    const costo=Math.max(1,(typeof costoSemanal==="function")?costoSemanal():40);
    const sem=Math.max(0,Math.round(caja/costo));
    const sobre=Math.round((ratio-1)*100);
    const menos=Math.round((1-rel)*100);
    const pais=infl>=1.2?(" El precio justo ya trae lo cara que está la época ("+String(Math.round(infl*100)/100).replace(".",",")+"×)."):(infl<=0.8?" En este año el precio justo ya está ajustado a lo que vale la plata.":"");
    const eco=((typeof clausuraFactor==="function")&&clausuraFactor()<0.95)?" La deuda ya tiene sectores cerrados.":(sem<6?(" La caja da para unas "+sem+" semanas de gastos."):" La caja aguanta, pero la gente no entra.");
    porque="Las entradas están un "+sobre+"% sobre el precio de la época y el estadio se vacía: con el precio justo entrarían unos "+gJ.toLocaleString("es-CL")+" y hoy proyectas "+gA.toLocaleString("es-CL")+" (−"+menos+"%)."+pais+eco+" El recorte es lo que falta para llegar al justo, no un 10% fijo. Si después el estadio sigue vacío, no se bajan otra vez: el precio ya no es el problema.";
  }
  return {ofrecer:ofrecer,ratio:ratio,gente:gA,genteJusta:enJusto.gente||0,ocup:ocup,porque:porque,caro:caro,vacio:vacio,sobre:Math.round((ratio-1)*100)};
}
/* 7.9145 · deja cada sector en el precio de la época. Una sola vez: si el estadio
   sigue vacío, el problema ya no es la entrada. */
function entradasAlJusto(){
  if(!E) return null;
  const antes=(typeof proyeccionTaquilla==="function")?proyeccionTaquilla():null;
  const ratio=(typeof precioPromedioRatio==="function")?precioPromedioRatio():1;
  E.precios=(typeof preciosDefault==="function")?preciosDefault():(E.precios||{});
  const desp=(typeof proyeccionTaquilla==="function")?proyeccionTaquilla():null;
  return {antes:antes,desp:desp,sobre:Math.max(0,Math.round((ratio-1)*100))};
}
function ingresosAnuales(){
  /* 7.9029 · la TV se reparte parejo dentro de la división (como el CDF):
     el prestigio suma, pero no decide quién vive y quién muere */
  const tvBase=E.eraBase==="2026b"?150:(E.eraBase==="2026c"?60:260);
  const tv=(tvBase+E.ind.prestigio*1.5)*(1+(modSuma("tv")||0));
  const spo=(90+E.ind.prestigio*3.5)*(1+(modSuma("sponsor")||0));
  const soc=(E.ind.socios*10)*(1+(modSuma("ingresoSocios")||0));
  const dig=(typeof ingresoDigital==="function")?ingresoDigital():0;
  return {tv:Math.round(tv),sponsors:Math.round(spo),socios:Math.round(soc),digital:dig};
}
/* 7.9050 · sueldo real del CM: ~1,2 M al mes (en pesos de la época), no 180 M de una vez */
var CM_SUELDO_MES=1.2, CM_CONTRATO=1.5;
function sueldoCMAnual(){
  if(!E||!E.staff||!E.staff.cm) return 0;
  const infl=(typeof inflacionEra==="function")?inflacionEra():1;
  return Math.round(CM_SUELDO_MES*12*infl*10)/10;
}
function egresosAnuales(){
  const planilla=planillaAnual();
  const oper=Math.round(100+E.ind.prestigio*2+E.ind.estadio*5+E.ind.hinchada*2);
  const inter=Math.round(E.deuda*(0.16+modSuma("interes")));
  return {planilla:planilla,operacion:oper,intereses:inter,cm:sueldoCMAnual()};
}
/* 7.58 · refinanciar la deuda: bajás el interés semanal a cambio de estirar el
   total (te sale más caro en total, pero respirás ahora). */
function tasaInteresAnual(){ return 0.16+((typeof modSuma==="function")?modSuma("interes"):0); }
function interesSemanal(){ return Math.round((E.deuda||0)*tasaInteresAnual()/40); }
function estaRefinanciado(){ return (E.mods||[]).some(function(m){ return m.id==="refinanciado"; }); }
/* preview: qué pasaría si refinanciás ahora (sin aplicar nada) */
function previewRefinanciar(){
  const costo=Math.round((E.deuda||0)*0.18);
  const tasaDesp=Math.max(0.06, tasaInteresAnual()-0.06);
  const deudaDesp=(E.deuda||0)+costo;
  return {
    puede: (E.deuda||0)>=300 && !estaRefinanciado(),
    costo:costo,
    interesAntes: interesSemanal(),
    interesDesp: Math.round(deudaDesp*tasaDesp/40),
    deudaAntes: Math.round(E.deuda||0),
    deudaDesp: deudaDesp
  };
}
function refinanciarDeuda(){
  if((E.deuda||0) < 300) return {ok:false, msg:"Tu deuda es muy baja para que valga la pena refinanciar."};
  if(estaRefinanciado()) return {ok:false, msg:"Ya tienes la deuda refinanciada; el efecto sigue activo."};
  const costo=Math.round(E.deuda*0.18);
  aplicarEfectos({deuda:costo});
  agregarMod({id:"refinanciado", n:"Deuda refinanciada", anios:6, ef:{interes:-0.06}});
  if(typeof aplicarGrupos==="function") aplicarGrupos({directorio:-3});   /* al directorio no le gusta estirar deuda */
  return {ok:true, costo:costo};
}
/* 7.18 · deuda en cuotas (se reinyecta sobre el motor 7.30 de GitHub) */
function recotarDeuda(){
  if(!E) return;
  const d=Math.max(0,Math.round(E.deuda||0));
  if(d<=0){ E.deudaPlan=null; return; }
  const prev=E.deudaPlan||{};
  E.deudaPlan={cuota:Math.max(15,Math.round(d/16)),semanas:16,pagadas:prev.pagadas||0,atrasos:prev.atrasos||0};
}
function cuotaDeuda(){
  if(!E||!(E.deuda>0)) return 0;
  if(!E.deudaPlan) recotarDeuda();
  return (E.deudaPlan&&E.deudaPlan.cuota)||0;
}
function tickCuotaDeuda(){
  if(!E) return;
  if(!(E.deuda>0)){ E.deudaPlan=null; return; }
  if(!E.deudaPlan) recotarDeuda();
  /* 7.9094 · deuda de centavos (0 < deuda < 0,5): recotarDeuda la redondea a 0 y no arma plan → se da por pagada */
  if(!E.deudaPlan){ E.deuda=0; return; }
  const c=Math.min(E.deudaPlan.cuota,E.deuda);
  if(c<=0){ E.deudaPlan=null; return; }
  if(E.plata>=c){
    aplicarEfectos({plata:-c,deuda:-c});
    if(E.deudaPlan){ E.deudaPlan.pagadas=(E.deudaPlan.pagadas||0)+1; E.deudaPlan.atrasos=0; }
  } else {
    E.deudaPlan.atrasos=(E.deudaPlan.atrasos||0)+1;
    if(E.deudaPlan.atrasos===1){
      notificar({t:"Cuota de deuda atrasada",tipo:"malo",bandeja:true,
        d:"Esta semana no alcanzó la caja para la cuota de "+plata(c)+". El banco anota el atraso. Si se acumulan tres, el directorio se calienta."});
    } else if(E.deudaPlan.atrasos>=3){
      aplicarGrupos({directorio:-8});
      notificar({t:"El banco llama al directorio",tipo:"malo",bandeja:true,
        d:"Tres cuotas atrasadas de "+plata(c)+". El directorio pierde la paciencia (−8). La deuda no espera."});
      if(E.deudaPlan) E.deudaPlan.atrasos=0;
    }
  }
}
function prensaFiltra(){
  if(!E||!E.grupos) return;
  const malos=[];
  for(const k in E.grupos){ if(E.grupos[k]&&E.grupos[k].aprob<-45) malos.push(k); }
  if(!malos.length){ if(E.flags) E.flags.prensaFiltra=null; return; }
  const key=malos.slice().sort().join(",");
  if(E.flags&&E.flags.prensaFiltra===key) return;
  if(!E.flags) E.flags={};
  E.flags.prensaFiltra=key;
  const nom=k=>(typeof GRUPO_POR_ID!=="undefined"&&GRUPO_POR_ID[k])?GRUPO_POR_ID[k].n.toLowerCase():k;
  const lista=malos.map(nom);
  const quien=lista.length===1?lista[0]:lista.slice(0,-1).join(", ")+" y "+lista[lista.length-1];
  const d=lista.length===1
    ?"Se filtra que "+quien+" está en contra. Si no das vuelta el clima, la asamblea se empieza a hablar."
    :"Se filtra malestar: "+quien+" están en contra. La prensa ya huele sangre.";
  notificar({t:"La prensa filtra el malestar",tipo:"malo",d:d,bandeja:true});
  if((E.anio||2026)>=2008 && typeof postProc==="function"){
    const club=E.clubNombre||"el club";
    const handles=(typeof HANDLES_PRENSA!=="undefined"&&HANDLES_PRENSA.length)?HANDLES_PRENSA:["@DeporteTotal"];
    const h=(typeof elige==="function")?elige(handles):handles[0];
    const frases=[
      "Fuentes del "+club+" confirman malestar interno. "+quien+" no aguanta más.",
      "Se filtra: en "+club+" el clima con "+quien+" está por el piso. Asamblea en el aire.",
      "Columna: el "+club+" no aguanta otro tropiezo. El entorno pide respuestas."
    ];
    postProc(h,"prensa",(typeof elige==="function")?elige(frases):frases[0],"malo");
  }
}
function costoSemanal(){
  const e=egresosAnuales();
  return Math.round((e.planilla+e.operacion+e.intereses+(e.cm||0))/40*10)/10;
}
function ingresoSemanal(){
  const i=ingresosAnuales();
  return Math.round((i.tv+i.sponsors+i.socios+(i.digital||0))/40);
}
function aplicarEstatutosMod(){
  ESTATUTOS.forEach(cat=>{
    const opId=E.estatutos[cat.id]; if(!opId) return;
    const op=cat.op.find(o=>o.id===opId); if(!op||!op.mod) return;
    for(const k in op.mod){
      const id="est_"+cat.id;
      let m=E.mods.find(x=>x.id===id);
      if(!m){ m={id:id,n:"Estatuto: "+op.n,hasta:9999,ef:{}}; E.mods.push(m); }
      m.n="Estatuto: "+op.n; m.ef=Object.assign({},op.mod);
    }
  });
}
/* ---------------- obras del estadio (arreglar/mejorar por etapas) ---------------- */
var OBRAS_PLAN={
  mantencion:  { n:"Mantención general", ic:"🧹", semanas:2, gEstadio:3,  gAforo:0,    desc:"Pintura, baños, césped. Sube un poco el estado y no molesta a nadie." },
  remodelacion:{ n:"Remodelar un sector", ic:"🔧", semanas:4, gEstadio:7,  gAforo:0,    desc:"Butacas nuevas y accesos. Mejora el estado y la imagen del recinto." },
  ampliacion:  { n:"Ampliar el aforo",    ic:"🏗️", semanas:8, gEstadio:10, gAforo:2500, desc:"Obra grande: más capacidad y menos sanciones. Cara y lenta, pero cambia el club." }
};
function costoObra(tipo){
  const base={mantencion:120, remodelacion:360, ampliacion:820}[tipo]||200;
  return Math.round(base*(1+E.ind.estadio/140));   /* más caro cuanto mejor ya está */
}
function iniciarObra(tipo){
  if(E.obras) return {ok:false,msg:"Ya hay una obra en marcha."};
  const plan=OBRAS_PLAN[tipo]; if(!plan) return {ok:false,msg:"Obra desconocida."};
  if(E.ind.estadio>=98) return {ok:false,msg:"El estadio ya está impecable."};
  const costo=costoObra(tipo);
  if(E.plata<costo) return {ok:false,msg:"No te alcanza la caja para esta obra."};
  aplicarEfectos({plata:-costo});
  E.obras={tipo:tipo, semanas:plan.semanas, resta:plan.semanas, costo:costo};
  guardar();
  return {ok:true, costo:costo};
}
function avanzarObras(){
  if(!E.obras) return;
  E.obras.resta--;
  if(E.obras.resta<=0){
    const plan=OBRAS_PLAN[E.obras.tipo];
    if(plan){
      aplicarEfectos({estadio:plan.gEstadio});
      if(plan.gAforo) E.aforoExtra=(E.aforoExtra||0)+plan.gAforo;
      notificar({t:"Obra terminada",tipo:"bueno",bandeja:true,
        d:"Se terminó la obra: "+plan.n+". El estadio quedó mejor"+(plan.gAforo?(" y suma ~"+plan.gAforo+" de aforo"):"")+"."});
      if(typeof recordar==="function") recordar("estadio","terminaste una obra en el estadio ("+plan.n+")",{peso:"medio",tono:"bueno"});
      /* 7.9054 · el estadio dibujado avanza obra por obra */
      E.obrasHechas=(E.obrasHechas||[]).concat([{tipo:E.obras.tipo,anio:E.anio}]);
    }
    E.obras=null;
  }
}
/* ---------------- paso del tiempo ---------------- */
function decisionesBloqueantes(){
  return E.decPend.filter(x=>x.peso==="alto");
}
function proximoPartido(){ return E.calendario[E.idx]||null; }
function tickSemana(){
  /* plata que entra y sale entre partido y partido */
  const neto=ingresoSemanal()-costoSemanal();
  aplicarEfectos({plata:neto});
  if(typeof tickCuotaDeuda==="function") tickCuotaDeuda();
  if(typeof prensaFiltra==="function") prensaFiltra();
  avanzarObras();
  if(typeof actualizarBolsa==="function") actualizarBolsa();
  if(typeof gestionTesorero==="function") gestionTesorero();
  /* plata personal del DT: entra su sueldo del cargo (menos si renunció por redención) */
  /* 7.9111 · a dos decimales: redondear a entero cada semana se comía los sueldos chicos (2,2 → 2) */
  if(E.personal && typeof ingresoPersonalSemanal==="function"){ E.personal.bolsillo=Math.max(0,Math.round((E.personal.bolsillo+ingresoPersonalSemanal())*100)/100); }
  /* Vida 3.0: la relación se enfría si no la cuidas; el bienestar deriva y sufre con la mala racha */
  if(E.perfil){
    if(E.perfil.pareja) E.perfil.pareja.nivel=clamp((E.perfil.pareja.nivel||65)-(E.perfil.pareja.casades?0.4:0.9),0,100);
  if(typeof tickFamilia==="function") tickFamilia();
    if(E.perfil.bienestar===undefined) E.perfil.bienestar=70;
    E.perfil.bienestar=clamp(E.perfil.bienestar+(58-E.perfil.bienestar)*0.05-((E.temporada&&E.temporada.sinGanar>=3)?1.5:0),0,100);
  }
  E.plantel.forEach(j=>{ if(j.lesion>0) j.lesion--; });
  /* deriva natural */
  if(E.ind.riesgo>0&&Math.random()<0.3) E.ind.riesgo=clamp(E.ind.riesgo-1,0,100);
  /* impacto tangible de las finanzas: sueldos atrasados y estadio clausurado */
  if(E.plata<50 && E.deuda>1500){
    aplicarEfectos({moral:-2});
    if(!E.flags.sueldosAtrasados){ E.flags.sueldosAtrasados=true;
      notificar({t:"Sueldos atrasados",tipo:"malo",d:"La caja no cubre la planilla. El plantel lo siente: la moral baja semana a semana hasta que se regularice.",bandeja:false}); }
  } else if(E.flags.sueldosAtrasados && E.plata>200){ E.flags.sueldosAtrasados=false;
    notificar({t:"Sueldos al día",tipo:"bueno",d:"Se regularizaron los pagos. El camarín respira.",bandeja:false}); }
  if(E.deuda>4000 && !E.flags.clausura){ E.flags.clausura=true;
    notificar({t:"Clausura parcial del estadio",tipo:"malo",d:"Con la deuda por las nubes, se clausuraron sectores por garantías impagas: baja el aforo disponible y la taquilla.",bandeja:false}); }
  else if(E.deuda<=3500 && E.flags.clausura){ E.flags.clausura=false; }
  /* 7.36 · crisis de hinchada cierra la popular, no solo baja un número */
  const hin=(E.ind&&E.ind.hinchada)||50;
  if(hin<22 && !E.flags.tribunaCerrada){
    E.flags.tribunaCerrada=true;
    notificar({t:"Popular clausurada",tipo:"malo",d:"La hinchada está tan caliente que se cerró la tribuna popular por seguridad. Baja el aforo y la taquilla hasta que el clima se calme.",bandeja:false});
  } else if(hin>=32 && E.flags.tribunaCerrada){
    E.flags.tribunaCerrada=false;
    notificar({t:"Se reabre la popular",tipo:"bueno",d:"El clima se calmó. La tribuna popular vuelve a abrir.",bandeja:false});
  }
  /* precios: caros molestan a la hinchada, baratos la enamoran (de a poco) */
  const ratio=precioPromedioRatio();
  if(ratio>1.35 && Math.random()<0.5) E.ind.hinchada=clamp(E.ind.hinchada-1,0,100);
  else if(ratio<0.8 && Math.random()<0.5) E.ind.hinchada=clamp(E.ind.hinchada+1,0,100);
  const gh=E.grupos&&E.grupos.hinchada, gs=E.grupos&&E.grupos.socios;
  if(gh&&gs&&gh.aprob<-45&&gs.aprob<-45){
    E.flags.semanasCensura=(E.flags.semanasCensura||0)+1;
    if(E.flags.semanasCensura===1){
      notificar({t:"Asamblea extraordinaria",tipo:"malo",
        d:"Hinchada y socios están juntos en contra. Si no reviertes el clima en dos semanas, hay moción de censura.",bandeja:true});
    } else if(E.flags.semanasCensura>=3 && typeof destituir==="function"){
      destituir("moción de censura de socios e hinchada");
    }
  } else E.flags.semanasCensura=0;
  return neto;
}
function umbralEvento(){
  /* histórico: mundo más estable · libre: ruido medio · caos: casi no hay semana muerta */
  const m=(E&&E.modo)||"historico";
  if(m==="caos") return 0.18;
  if(m==="libre") return 0.32;
  return 0.48;
}
function tirarEvento(){
  const posibles=EVENTOS.filter(ev=>ev.peso(E)>0);
  if(!posibles.length||Math.random()>umbralEvento()) return null;
  const ev=eligePeso(posibles,x=>x.peso(E));
  if(!ev) return null;
  if(ev.op) return {tipo:"decision",ev:ev};
  if(ev.ef) aplicarEfectos(ev.ef);
  if(ev.grupos) aplicarGrupos(ev.grupos);
  if(ev.rep) aplicarRep(ev.rep);
  let extra=ev.accion?ejecutarAccion(ev.accion,ev):"";
  const txt=resolverTokens(ev.d,E).replace("{JUGADOR}",(elige(E.plantel.filter(j=>!j.vendido))||{n:"un jugador"}).n);
  const item=notificar({t:ev.t,d:txt,extra:extra,tipo:ev.tipo});
  return {tipo:"aviso",item:item};
}
function crisisActiva(){
  for(const c of CRISIS){ if(!E.flags["crisis_"+c.id]&&c.dispara(E)) return c; }
  return null;
}
/* ---------------- fin de temporada ---------------- */
/* ---------- ascenso / descenso (Primera 2026 ↔ Primera B 2026b) ----------
   La división del jugador se juega de verdad; la otra se simula por fuerza.
   Cada temporada bajan/suben los cupos reales entre niveles (ver _cuposDiv: Primera↔B = 2,
   B↔Segunda = 1). Si el que cambia es el club del jugador, cambia su eraBase → juega la otra el año que viene. */
function initLigaMod(){
  if(!E || E.ligaMod) return;
  if(!(E.eraBase===2026 || E.eraBase==="2026b" || E.eraBase==="2026c")) return;
  if(typeof LIGA_2026==="undefined" || typeof LIGA_B_2026==="undefined") return;
  E.ligaMod={ 2026:LIGA_2026.map(c=>c.id), "2026b":LIGA_B_2026.map(c=>c.id) };
  if(typeof LIGA_C_2026!=="undefined") E.ligaMod["2026c"]=LIGA_C_2026.map(c=>c.id);
  const div=E.eraBase;
  if(E.ligaMod[div] && E.ligaMod[div].indexOf(E.club)<0) E.ligaMod[div].push(E.club);
}
/* 8.00 · división VIGENTE (tras ascenso/descenso), no la lista original de 2026.
   El club del jugador mira eraBase; el resto, ligaMod. Copas y zonas cuelgan de esto. */
function divisionVigenteDe(id){
  if(typeof E!=="undefined" && E){
    if(id===E.club){
      if(E.eraBase==="2026c") return "C";
      if(E.eraBase==="2026b") return "B";
      if(E.eraBase===2026 || E.eraBase==="2026") return "P";
      if(E.eraBase==="arg2026") return "ARG";
      if(typeof esEraHardcode==="function" && !esEraHardcode(E.eraBase)) return "X";
    }
    if(E.ligaMod){
      if((E.ligaMod[2026]||[]).indexOf(id)>=0) return "P";
      if((E.ligaMod["2026b"]||[]).indexOf(id)>=0) return "B";
      if((E.ligaMod["2026c"]||[]).indexOf(id)>=0) return "C";
    }
  }
  if(typeof esClubC==="function" && esClubC(id)) return "C";
  if(typeof esClubB==="function" && esClubB(id)) return "B";
  if(typeof esClubArg==="function" && esClubArg(id)) return "ARG";
  return "P";
}
function juegaCopaChile(clubId, anio){
  if((anio||0)<2026) return false;
  if(typeof E!=="undefined" && E){
    if(E.eraBase==="arg2026" || E.eraBase===1991 || E.eraBase===2006 || E.eraBase===1925) return false;
    if(typeof esEraHardcode==="function" && !esEraHardcode(E.eraBase)) return false;
  }
  const d=divisionVigenteDe(clubId);
  return d==="P" || d==="B";
}
function juegaCopaDeLaLiga(clubId, anio){
  if((anio||0)<2026) return false;
  if(typeof E!=="undefined" && E && (E.eraBase==="arg2026" || E.eraBase===1991 || E.eraBase===2006 || E.eraBase===1925)) return false;
  if(typeof E!=="undefined" && E && typeof esEraHardcode==="function" && !esEraHardcode(E.eraBase)) return false;
  return divisionVigenteDe(clubId)==="P";
}
function _fuerzaClubId(id){ const m=(typeof clubMapaTodos==="function")?clubMapaTodos():{}; const c=m[id]||CLUB_POR_ID[id]; return (c&&c.fuerza)||55; }
function _ordenRealDiv(ids){ return ids.slice().sort((a,b)=>{ const A=E.tabla[a]||{pts:-1,gf:0,gc:0}, B=E.tabla[b]||{pts:-1,gf:0,gc:0}; return (B.pts-A.pts)||((B.gf-B.gc)-(A.gf-A.gc))||(B.gf-A.gf); }); }
function _ordenSimDiv(ids){ return ids.slice().map(id=>({id:id,p:_fuerzaClubId(id)+ri(-14,14)})).sort((a,b)=>b.p-a.p).map(x=>x.id); }
function nombreDeClub(id){ const m=(typeof clubMapaTodos==="function")?clubMapaTodos():{}; const c=m[id]||CLUB_POR_ID[id]; return (c&&(c.n||c.c))||id; }
function _nombreDiv(t){ return t===2026?"Primera División":(t==="2026b"?"Primera B":(t==="2026c"?"Segunda División":"la liga")); }
/* ---- Segunda División: zonas Norte/Sur (7.65) ----
   La Segunda se juega en dos zonas de 7. La zona de cada club vive en E.zonaSeg
   (sembrada de LIGA_C_2026.z) para que sobreviva a ascensos/descensos: cuando un
   club sube a la B, su cupo de zona lo hereda el que baja de la B → las zonas quedan
   siempre 7 y 7. */
function _zonaSegInit(){
  if(typeof E==="undefined"||!E) return {};
  if(!E.zonaSeg){ E.zonaSeg={}; if(typeof LIGA_C_2026!=="undefined") LIGA_C_2026.forEach(c=>{ E.zonaSeg[c.id]=c.z; }); }
  return E.zonaSeg;
}
function zonaSegDe(id){ const zs=_zonaSegInit(); if(zs[id]) return zs[id]; return (typeof clubZona==="function")?clubZona(id):null; }
function nombreZona(z){ return z==="norte"?"Norte":(z==="sur"?"Sur":""); }
/* Los clubes que compiten con el jugador esta temporada: en Segunda es su ZONA (7),
   en el resto es toda la liga. */
function clubesLigaActual(){
  if(typeof E!=="undefined" && E && E.eraBase==="2026c"){
    const z=zonaSegDe(E.club);
    if(z){ const zn=LIGA_ACT.filter(c=>zonaSegDe(c.id)===z); if(zn.length) return zn; }
  }
  if(typeof E!=="undefined" && E && E.eraBase==="arg2026" && typeof zonaArgDe==="function"){
    const z=zonaArgDe(E.club);
    if(z){ const zn=LIGA_ACT.filter(c=>zonaArgDe(c.id)===z); if(zn.length) return zn; }
  }
  return LIGA_ACT.slice();
}
/* Campeón de una zona de Segunda: la del jugador por tabla real, la otra simulada por fuerza. */
function _campeonZonaSeg(z){
  const ids=(E.ligaMod&&E.ligaMod["2026c"]?E.ligaMod["2026c"]:LIGA_ACT.map(c=>c.id)).filter(id=>zonaSegDe(id)===z);
  if(!ids.length) return null;
  return (E.eraBase==="2026c" && zonaSegDe(E.club)===z)?_ordenRealDiv(ids)[0]:_ordenSimDiv(ids)[0];
}
/* Ascenso de Segunda: los campeones de Norte y Sur juegan una liguilla; el ganador sube a la B. */
function _ascensoSegunda(){
  const cn=_campeonZonaSeg("norte"), cs=_campeonZonaSeg("sur");
  if(!cn) return cs; if(!cs) return cn;
  const pn=_fuerzaClubId(cn)+ri(-10,10), ps=_fuerzaClubId(cs)+ri(-10,10);
  return pn>=ps?cn:cs;
}
/* 7.63 · cupos reales de ascenso/descenso por par de divisiones.
   Primera 2026 baja 2 (los reales) y la B sube 2 (campeón + liguilla) → tamaños 16/16 intactos.
   B↔Segunda: 1 (campeón de Segunda sube; el último de la B baja). Balanceado = no cambia el nº de clubes. */
function _cuposDiv(up,lo){
  var n=(up===2026 && lo==="2026b")?2:1;
  if(up===2026 && lo==="2026b" && typeof reformaFed==="function" && reformaFed("menos_desc")) n=1;
  return n;
}
/* nombres de una lista de ids como texto ("A", "A y B", "A, B y C") */
function _nombresLista(ids){
  const ns=(ids||[]).map(id=>(typeof nombreDeClub==="function")?nombreDeClub(id):id);
  if(!ns.length) return "";
  if(ns.length===1) return ns[0];
  return ns.slice(0,-1).join(", ")+" y "+ns[ns.length-1];
}
/* 7.999 · el plantel tiene que alcanzar para cortar gente de la lista (nomina 16/18/23). */
function rellenarPlantelLista(){
  if(!E || !Array.isArray(E.plantel) || typeof generarJugador!=="function") return;
  const minN=(typeof listaMaxEra==="function"?listaMaxEra(E.anio):18)+5;
  const posCiclo=["ARQ","DEF","DEF","VOL","VOL","DEL","DEF","VOL"];
  let guard=0;
  while(E.plantel.filter(j=>j&&!j.vendido&&!j.cedido).length<minN && guard++<16){
    const rr=(typeof azarFijo==="function"&&typeof semilla==="function")
      ?azarFijo(semilla("lista"+E.anio+E.plantel.length+(E.club||"")))
      :Math.random;
    const pos=posCiclo[E.plantel.length%posCiclo.length];
    const j=generarJugador(rr,(E.ind&&E.ind.plantel||60)-8, pos, 17+(E.plantel.length%6));
    j.rasgos=j.rasgos||[];
    if(j.rasgos.indexOf("cantera")<0) j.rasgos.push("cantera");
    j.contrato=j.contrato||{};
    if(!j.contrato.hasta) j.contrato.hasta=(E.anio||2026)+3;
    E.plantel.push(j);
  }
}
function procesarAscensoDescenso(){
  if(!E || !(E.eraBase===2026 || E.eraBase==="2026b" || E.eraBase==="2026c")) return null;
  initLigaMod(); if(!E.ligaMod) return null;
  /* 7.50/7.63 · cadena de divisiones (2 o 3 niveles). Para cada par adyacente bajan/suben
     los N cupos reales. Solo la división del jugador se ordena por su tabla real; las otras
     se simulan por fuerza. */
  const tiers=[2026,"2026b"]; if(E.ligaMod["2026c"]) tiers.push("2026c");
  const orden={};
  tiers.forEach(t=>{ const ids=(E.ligaMod[t]||[]).slice(); orden[t]=(E.eraBase===t)?_ordenRealDiv(ids):_ordenSimDiv(ids); });
  E.liguillaPend=null;
  const cambios=[];
  for(let i=0;i<tiers.length-1;i++){
    const up=tiers[i], lo=tiers[i+1];
    const n=_cuposDiv(up,lo);
    const bajan=orden[up].slice(-n).filter(Boolean);
    if(lo==="2026c"){
      /* 7.993 · Segunda sube por la liguilla de 7 (1 cupo). El 1° de esa tabla
         (ligaCCampeon) sube; ya no hay final de 3 botones vs el otro campeón de zona. */
      var subeC=null;
      if(E.eraBase==="2026c" && E.flags && E.flags.ligaCCampeon) subeC=E.club;
      else {
        const pool=(E.ligaMod["2026c"]||[]).filter(id=>id!==E.club);
        subeC=_ordenSimDiv(pool)[0]||_ascensoSegunda();
      }
      const suben=[subeC].filter(Boolean);
      if(bajan.length && suben.length) cambios.push({up:up,lo:lo,bajan:bajan,suben:suben});
    } else {
      const suben=orden[lo].slice(0,n).filter(Boolean);
      if(bajan.length && suben.length) cambios.push({up:up,lo:lo,bajan:bajan,suben:suben});
    }
  }
  if(!cambios.length){ return E.liguillaPend?{tipo:"liguilla",pend:E.liguillaPend}:null; }
  cambios.forEach(c=>{
    E.ligaMod[c.up]=E.ligaMod[c.up].filter(id=>c.bajan.indexOf(id)<0).concat(c.suben);
    E.ligaMod[c.lo]=E.ligaMod[c.lo].filter(id=>c.suben.indexOf(id)<0).concat(c.bajan);
    /* zonas de Segunda: el que baja de la B hereda el cupo de zona del que ascendió → 7 y 7 */
    if(c.lo==="2026c"){ const zs=_zonaSegInit(); const zLibre=zs[c.suben[0]]||"norte"; delete zs[c.suben[0]]; if(c.bajan[0]) zs[c.bajan[0]]=zLibre; }
  });
  let msg=null;
  cambios.forEach(c=>{
    if(c.suben.indexOf(E.club)>=0){ E.eraBase=c.up; msg={tipo:"ascenso",baja:c.bajan[0],sube:E.club,up:c.up,lo:c.lo,bajan:c.bajan,suben:c.suben}; }
    else if(c.bajan.indexOf(E.club)>=0){ E.eraBase=c.lo; msg={tipo:"descenso",baja:E.club,sube:c.suben[0],up:c.up,lo:c.lo,bajan:c.bajan,suben:c.suben}; }
  });
  if(!msg){ const c=cambios[0]; msg={tipo:"otros",baja:c.bajan[0],sube:c.suben[0],up:c.up,lo:c.lo,bajan:c.bajan,suben:c.suben}; }
  E.ascensoMsg=msg;
  if(typeof activarLiga==="function") activarLiga(E.eraBase);
  if(typeof notificar==="function"){
    /* "los que bajaron contigo" / "los que subieron contigo": el resto de los cupos aparte del jugador */
    const otrosBajan=(msg.bajan||[]).filter(id=>id!==E.club), otrosSuben=(msg.suben||[]).filter(id=>id!==E.club);
    if(msg.tipo==="ascenso") notificar({t:"🎉 ¡ASCENSO a "+_nombreDiv(msg.up)+"!",tipo:"bueno",bandeja:true,d:E.clubNombre+" sube"+(otrosSuben.length?" junto a "+_nombresLista(otrosSuben):"")+". Bajó "+_nombresLista(msg.bajan)+". El año que viene se juega en "+_nombreDiv(msg.up)+"."});
    else if(msg.tipo==="descenso") notificar({t:"📉 Descenso a "+_nombreDiv(msg.lo),tipo:"malo",bandeja:true,d:E.clubNombre+" perdió la categoría"+(otrosBajan.length?" junto a "+_nombresLista(otrosBajan):"")+". Subió "+_nombresLista(msg.suben)+". El año que viene se pelea el ascenso en "+_nombreDiv(msg.lo)+"."});
    else notificar({t:"Ascensos y descensos",tipo:"neutro",bandeja:false,d:"En "+_nombreDiv(msg.lo)+" subió "+_nombresLista(msg.suben)+" y bajó "+_nombresLista(msg.bajan)+"."});
  }
  if(typeof recordar==="function" && msg.tipo!=="otros") recordar("categoria",(msg.tipo==="ascenso"?"ascendiste a "+_nombreDiv(msg.up)+" con ":"descendiste a "+_nombreDiv(msg.lo)+" con ")+E.clubNombre,{peso:"alto",tono:msg.tipo==="ascenso"?"bueno":"malo"});
  /* si quedó una liguilla pendiente para el jugador, ese es el mensaje que manda: la juega él */
  if(E.liguillaPend){ const lm={tipo:"liguilla",pend:E.liguillaPend}; E.ascensoMsg=lm; return lm; }
  return msg;
}
/* 7.66 · resolver el ascenso de Segunda por la liguilla que YA jugó el jugador.
   sube = el ganador (el club del jugador si ganó, si no el rival). Aplica el recambio
   con la B (el que baja hereda la zona) y, si subió el jugador, cambia su eraBase. */
function liguillaResolverAscenso(gano){
  const pend=E.liguillaPend; if(!pend) return null;
  const sube=gano?E.club:pend.rival, baja=pend.baja;
  if(sube && E.ligaMod && E.ligaMod["2026b"] && E.ligaMod["2026c"]){
    E.ligaMod["2026b"]=E.ligaMod["2026b"].filter(id=>id!==baja && id!==sube).concat([sube]);
    E.ligaMod["2026c"]=E.ligaMod["2026c"].filter(id=>id!==sube && id!==baja).concat(baja?[baja]:[]);
    const zs=_zonaSegInit(); const zLibre=zs[sube]||"norte"; delete zs[sube]; if(baja) zs[baja]=zLibre;
  }
  const msg={tipo:gano?"ascenso":"descenso_liguilla",sube:sube,baja:baja,rival:pend.rival};
  if(gano){ E.eraBase="2026b"; if(typeof activarLiga==="function") activarLiga(E.eraBase);
    if(typeof notificar==="function") notificar({t:"🎉 ¡ASCENSO por la liguilla!",tipo:"bueno",bandeja:true,d:E.clubNombre+" ganó la final del ascenso a "+nombreDeClub(pend.rival)+" y sube a Primera B. Bajó "+nombreDeClub(baja)+"."});
    if(typeof recordar==="function") recordar("categoria","ganaste la liguilla y ascendiste a Primera B con "+E.clubNombre,{peso:"alto",tono:"bueno"});
    E.titulos.push(E.anio+" · Campeón de la Liguilla (ascenso a Primera B)");
  } else {
    if(typeof activarLiga==="function") activarLiga(E.eraBase);
    if(typeof notificar==="function") notificar({t:"Se escapó el ascenso",tipo:"malo",bandeja:true,d:"Perdiste la final de la liguilla con "+nombreDeClub(pend.rival)+". Subió el rival; "+E.clubNombre+" se queda un año más en Segunda."});
    if(typeof recordar==="function") recordar("categoria","perdiste la liguilla del ascenso con "+E.clubNombre,{peso:"medio",tono:"malo"});
  }
  E.ascensoMsg=msg; E.liguillaPend=null;
  return msg;
}
/* Simula un cruce a dos partidos (ida y vuelta) entre el club del jugador y el rival.
   La postura del jugador (-1 defensivo, 0 equilibrado, 1 ofensivo) inclina el resultado.
   Devuelve marcadores y si el jugador pasó (por global; el rival define penales si hay empate). */
function simularLiguilla(rivalId, postura){
  let fMi=_fuerzaClubId(E.club);
  try{ if(typeof fuerzaEquipo==="function" && typeof onceIdeal==="function"){ const fe=fuerzaEquipo(onceIdeal()); if(fe && typeof fe.base==="number") fMi=fe.base; } }catch(e){}
  fMi+=(postura||0)*3;
  const fRi=_fuerzaClubId(rivalId);
  const leg=(local)=>{
    const emp=(local?4:0)+(postura||0)*1.2;
    const d=(fMi+emp - fRi)/12;
    const gm=Math.max(0,Math.round(1.15+d*0.6+rnd(-1,1.2)));
    const gr=Math.max(0,Math.round(1.05-d*0.55+rnd(-1,1.2)));
    return [gm,gr];
  };
  const ida=leg(true), vuelta=leg(false);
  const gm=ida[0]+vuelta[0], gr=ida[1]+vuelta[1];
  let gano=gm>gr, penales=null;
  if(gm===gr){ const pm=_fuerzaClubId(E.club)+(postura||0)*2+ri(-8,8), pr=_fuerzaClubId(rivalId)+ri(-8,8); gano=pm>=pr; penales=gano?"Ganó en penales":"Perdió en penales"; }
  return {ida:ida, vuelta:vuelta, gm:gm, gr:gr, gano:gano, penales:penales, rival:rivalId};
}
function finDeTemporada(){
  const t=E.temporada;
  const pos=posicionEnTabla();
  const campeon=pos===1;
  if(typeof dividendoBolsa==="function") dividendoBolsa(pos);
  if(typeof desbloquear==="function"){
    if(campeon && E.ind.prestigio<55) desbloquear("campeon_chico");
    if(E.plata>0 && (E.flags.desfalco||0)<=0) desbloquear("caja_sana");
  }
  /* premios */
  let premio=[0,420,260,180,120][Math.min(4,pos)]||70;
  aplicarEfectos({plata:premio});
  const _divNom=(typeof _nombreDiv==="function")?_nombreDiv(E.eraBase):"Campeonato Nacional";
  /* en Segunda el pos===1 es el 1º de tu ZONA: el título dice la zona, no "campeón nacional" */
  const _tituloCampeon=(E.eraBase==="2026c")
    ? ("Campeón Zona "+nombreZona(zonaSegDe(E.club))+" (Segunda División)")
    : ("Campeón de "+(_divNom==="Primera División"?"la Primera División":_divNom));
  if(campeon){ E.titulos.push(E.anio+" · "+_tituloCampeon); aplicarEfectos({prestigio:7,hinchada:7,moral:6}); aplicarRep({publica:8,credibilidad:6});
    if(typeof recordar==="function") recordar("titulo","saliste campeón nacional en "+E.anio,{peso:"alto",tono:"bueno"}); }
  /* copa */
  const copa=E.calendario.filter(p=>p.tipo==="copa");
  const copaGanada=E.flags.copaCampeon;
  const copaNom=E.flags.copaCampeonTorneo||"la Copa";   /* 7.71 · qué copa fue (Chile/Libertadores/Sudamericana) */
  const copaEsAmerica=/Libertadores|Sudamericana/i.test(copaNom);
  if(copaGanada){ E.titulos.push(E.anio+" · "+copaNom); aplicarEfectos({prestigio:14,plata:600,hinchada:10}); aplicarRep({publica:14,credibilidad:10});
    if(typeof recordar==="function") recordar("titulo","levantaste "+copaNom+" con "+E.clubNombre,{peso:"alto",tono:"bueno"}); }
  /* evaluación del mandato */
  const ev=evaluarMandato(pos,campeon,copaGanada);
  /* balance y crónica */
  guardarHistorial(pos,campeon,copaGanada);
  E.cronica.unshift({anio:E.anio,pos:pos,pts:t.pts,campeon:campeon,copa:copaGanada?copaNom:null,
    plata:Math.round(E.plata),deuda:Math.round(E.deuda),ev:ev});
  notificar({t:"Balance "+E.anio+": "+(copaGanada?("Campeón — "+copaNom):campeon?"Campeón nacional":ordinal(pos)+" en el Nacional"),
    tipo:(campeon||copaGanada)?"bueno":(pos<=5?"neutro":"malo"),
    d:"Terminó la temporada "+E.anio+" en el "+ordinal(pos)+" lugar con "+t.pts+" puntos ("+t.pg+"G "+t.pe+"E "+t.pp+"P). "+
      "Premios de competencia: "+plata(premio)+". "+ev.txt,bandeja:false});
  /* ascenso / descenso entre Primera y Primera B (con la tabla ya final) */
  const asc=(typeof procesarAscensoDescenso==="function")?procesarAscensoDescenso():null;
  return {pos:pos,campeon:campeon,copa:copaGanada,copaNom:copaGanada?copaNom:null,premio:premio,ev:ev,asc:asc};
}
function posicionEnTabla(){
  const arr=clubesLigaActual().map(c=>({id:c.id,...E.tabla[c.id]}));
  arr.sort((a,b)=>b.pts-a.pts||(b.gf-b.gc)-(a.gf-a.gc)||b.gf-a.gf);
  return arr.findIndex(x=>x.id===E.club)+1;
}
function nuevoAnio(){
  E.anio++;
  limpiarMods();
  if(typeof aplicarReformasAlTorneo==="function") aplicarReformasAlTorneo();
  if(typeof aplicarSaltoFed==="function") aplicarSaltoFed();
  if(typeof aplicarGuerraFed==="function") aplicarGuerraFed();
  /* envejecer plantel y aplicar salidas
     6.32 · el desarrollo SIGUE LO QUE HICISTE: un joven que jugó mucho y bien crece
     hacia su proyección; uno al que no le diste minutos (banca, lesiones, mal rendimiento)
     se estanca o baja. Nada queda congelado: la decisión de hacerlo jugar tiene consecuencia. */
  E.plantel=E.plantel.filter(j=>!j.vendido&&!j.ventaFin);
  const evol=[];
  E.plantel.forEach(j=>{
    j.edad++;
    const min=j.minutosTemporada||0, formaFin=j.forma||60, proy=j.proy||j.nivel;
    const margen=proy-j.nivel;                    /* cuánto le queda por crecer */
    const jugoMucho=min>=1200, jugoAlgo=min>=400;  /* ~13+ / ~4+ partidos completos */
    let delta=0;
    if(j.edad<=23){
      if(jugoMucho) delta=ri(2,5)+(formaFin>=72?2:0)+(margen>4?1:0);
      else if(jugoAlgo) delta=ri(0,3);
      else delta=ri(-3,1);                         /* casi no jugó → se estanca o retrocede */
      if(formaFin<55) delta-=2;                    /* le fue mal → crece mucho menos */
      delta=Math.min(delta,Math.max(0,margen)+2);  /* no se dispara sobre su techo */
    } else if(j.edad<=28){
      delta=jugoMucho?ri(-1,2):ri(-3,0);
    } else if(j.edad>=30){
      delta=-ri(1,4)-(jugoMucho?0:1);              /* veterano que no sumó minutos, cae más */
    } else {
      delta=jugoMucho?ri(-1,1):ri(-2,0);
    }
    const antes=j.nivel;
    j.nivel=clamp(j.nivel+delta,20,97);
    if(j.edad<=24 && Math.abs(j.nivel-antes)>=3) evol.push({n:j.n,d:j.nivel-antes,niv:j.nivel,min:min});
    j.goles=0;j.partidos=0;j.tarjetas=0;j.lesion=0;j.forma=68;j.minutosTemporada=0;
  });
  /* contale al jugador que el desarrollo tuvo que ver con lo que hizo */
  const sube=evol.filter(x=>x.d>0).sort((a,b)=>b.d-a.d)[0];
  const baja=evol.filter(x=>x.d<0).sort((a,b)=>a.d-b.d)[0];
  if(sube||baja){
    let d="";
    if(sube) d+="📈 "+sube.n+" dio el salto (+"+sube.d+" → "+sube.niv+"): los minutos que le diste rindieron. ";
    if(baja) d+="📉 "+baja.n+" retrocedió ("+baja.d+" → "+baja.niv+"): "+(baja.min<400?"casi no jugó y se estancó.":"le costó el año.");
    notificar({t:"Cómo maduraron los jóvenes",tipo:"neutro",bandeja:false,d:d.trim()});
  }
  /* vuelven los cedidos, mejorados por el rodaje */
  const vueltos=[];
  E.plantel.forEach(j=>{
    if(j.cedido && j.cedido.hasta<=E.anio){
      const boost=ri(3,8); j.nivel=clamp(j.nivel+boost,20,97); j.proy=clamp(Math.max(j.proy,j.nivel+2),28,97);
      vueltos.push(j.n+" (+"+boost+" → "+j.nivel+")"); j.cedido=null;
    }
  });
  if(vueltos.length) notificar({t:"Vuelven los cedidos",tipo:"bueno",d:"Regresan del préstamo con más rodaje: "+vueltos.join(", ")+".",bandeja:false});
  /* retiros: los muy veteranos cuelgan los botines y suben regens de la cantera */
  const retirados=E.plantel.filter(j=>j.edad>=37);
  if(retirados.length){
    E.plantel=E.plantel.filter(j=>j.edad<37);
    retirados.forEach(j=>{
      const rr=azarFijo(semilla("regen"+E.anio+j.n));
      const joven=generarJugador(rr, E.ind.cantera*0.8+12, j.pos, ri(17,20));
      joven.proy=clamp(joven.proy+10,40,95); joven.rasgos=["de la cantera"]; joven.contrato.hasta=E.anio+4;
      E.plantel.push(joven);
    });
    notificar({t:"Retiros y relevo generacional",tipo:"neutro",
      d:"Colgaron los botines: "+retirados.map(j=>j.n+" ("+j.edad+" años)").join(", ")+
        ". Suben juveniles de la cantera para ocupar su lugar.",bandeja:false});
  }
  while(E.plantel.length<20){
    const rr=azarFijo(semilla("relleno"+E.anio+E.plantel.length));
    E.plantel.push(generarJugador(rr,E.ind.plantel-6,elige(["DEF","VOL","DEL","ARQ"])));
  }
  if(typeof rellenarPlantelLista==="function") rellenarPlantelLista();
  E.ind.plantel=clamp(Math.round(mediaPlantel()),0,100);
  E.ind.moral=clamp(Math.round(E.ind.moral+(55-E.ind.moral)*0.25),0,100);
  E.capital=Math.max(0,Math.round(E.capital+capitalAnual()));
  /* 7.9010 · el resto de los clubes también envejece, se retira y se ficha */
  if(typeof cpuTickAnio==="function"){
    const mov=cpuTickAnio();
    if(mov>0 && !E._bulkSim) notificar({t:"El mercado de la liga se movió",tipo:"neutro",bandeja:false,
      d:mov+" pases entre clubes que no diriges. En "+E.anio+" ya no están los mismos de 2026."});
  }
  /* el fútbol olvida: nadie te quiere ni te odia para siempre */
  for(const k in E.rep) E.rep[k]=Math.round(E.rep[k]+(50-E.rep[k])*0.12);
  GRUPOS.forEach(g=>{ const x=E.grupos[g.id]; x.aprob=Math.round(x.aprob*0.72); });
  E.temporada={pj:0,pg:0,pe:0,pp:0,gf:0,gc:0,pts:0,sinGanar:0};
  E.idx=0; E.decPend=[]; E.bandeja=[]; E.pendientesEncadenadas=[]; E.decProc={}; E.mercado=null; E.flags.copaCampeon=false;
  E.flags.copaCampeonTorneo=null; E.flags.copaAcum={};   /* 7.71 · limpiar la copa del año anterior */
  E.ofertasPend=[]; E.mercadoLog={rechazadas:{},vendidos:[]}; E.promesas=[];
  /* 5.0 · nuevas metas de la dirigencia para el año que arranca */
  E.flags.clasicoGanado=false;
  if(typeof generarObjetivos==="function") E.objetivos=generarObjetivos();
  notificar({t:"Arranca la temporada "+E.anio,tipo:"neutro",
    d:"Nuevo año, nuevo campeonato. El plantel se renovó, los objetivos se reajustan y la caja arranca de cero en lo semanal.",bandeja:false});
  /* banderas que solo valen dentro de una temporada */
  E.flags.rachaLiquida=false;
  /* 6.25 · limpiar TODOS los flags por-semana/idx (evita bugs de botones "ya usado" al reiniciar idx en el nuevo año) */
  ["medianoche_","conf_","entreno_","changa_","pasillo_","prometido_","tinderMentira","puertaBarra","feeTesoreroUlt"].forEach(pref=>{
    Object.keys(E.flags).forEach(k=>{ if(k.indexOf(pref)===0) delete E.flags[k]; });
  });
  /* 8.00 · calendario de la DIVISIÓN VIGENTE: si subiste, Copa Chile; si llegaste a Primera, también Copa de la Liga. */
  if(typeof initLigaMod==="function") initLigaMod();
  if(typeof activarLiga==="function") activarLiga(E.eraBase);
  /* 7.9110 · Apertura/Clausura (Argentina, 2006): cada año parte en Apertura. La fase y la tabla del Apertura
     viejo sobrevivían al cambio de año, y desde el 2º año el Clausura no se sembraba nunca (14 de 28 fechas en
     Argentina, 18 de 36 en 2006) y el archivo quedaba descuadrado. Lo cazó el banco por equipo con TEMPS=3. */
  if(E.flags){ if(E.flags.argFase) E.flags.argFase="apertura"; if(E.flags.fase2006) E.flags.fase2006="apertura"; }
  delete E.tablaApertura; delete E.temporadaApertura;
  E.calendario=construirCalendario(E.club,E.anio,E.anio===1992);
  reiniciarTabla();
  repartirDecisiones();
  if(typeof chequearSucesion==="function") chequearSucesion();
  guardar();
}
function mediaPlantel(){
  const l=E.plantel.filter(j=>!j.vendido&&!j.cedido).sort((a,b)=>b.nivel-a.nivel).slice(0,14);
  return l.reduce((s,j)=>s+j.nivel,0)/Math.max(1,l.length);
}
function capitalAnual(){
  let c=6;
  c+=aprobacionMedia()/12;
  c+=(E.ind.prestigio-55)/12;
  c+=(E.rep.credibilidad-50)/14;
  c+=modSuma("capitalAnual");
  return Math.round(clamp(c,-14,22));
}
/* ---------------- guardado ---------------- */
/* 7.9125 · el guardado de verdad vive en js/partidas.js (partidaGuardarYa: copia rápida + IndexedDB, y dice la
   verdad si no pudo). Esta es la versión sin agrupar; js/rendimiento.js la envuelve. */
async function guardar(){
  if(!E) return null;
  if(E._bulkSim) return null;
  return partidaGuardarYa();
}
async function cargar(){ return await Store.get(LLAVE); }

/* ---------- partidas múltiples (slots) ----------
   Cada partida vive bajo su propia clave (slotKey). Un índice explícito
   (SLOTS_LLAVE) lista las partidas con metadatos, porque Store abstrae
   window.storage y no se puede enumerar. La partida activa se recuerda en
   ACTIVO_LLAVE. El save legacy (LLAVE) se mantiene en sync = partida activa. */
var SLOTS_LLAVE="futbolini3_slots";
var ACTIVO_LLAVE="futbolini3_activo";
function slotKey(id){ return "futbolini3_partida_"+id; }
function nuevoSlotId(){ return "p"+Date.now().toString(36)+Math.floor(Math.random()*1000).toString(36); }
async function slotsLista(){ const a=await Store.get(SLOTS_LLAVE); return Array.isArray(a)?a:[]; }
async function slotsGuardarLista(a){ await Store.set(SLOTS_LLAVE,a); }
function slotMetaDe(est){
  return { id:est._slot, club:est.club, clubNombre:est.clubNombre||est.club, anio:est.anio,
           epoca:est.epocaEtq||"", modo:est.modo||"", gen:(est.dinastia&&est.dinastia.generacion)||1, guardado:Date.now(),
           t:+est._guardadoEn||0 };   /* 7.9125 · sello del último guardado: la copia que tenga uno menor es vieja */
}
async function slotActivoId(){ return await Store.get(ACTIVO_LLAVE); }
async function slotFijarActivo(id){ await Store.set(ACTIVO_LLAVE,id); }
async function slotActualizarIndice(est){
  const lista=await slotsLista();
  const meta=slotMetaDe(est);
  const i=lista.findIndex(s=>s.id===est._slot);
  if(i>=0) lista[i]=meta; else lista.push(meta);
  await slotsGuardarLista(lista);
}
async function borrarPartida(id){
  await partidaBorrarDatos(id);   /* 7.9125 · IndexedDB + ranura vieja de localStorage */
  const lista=(await slotsLista()).filter(s=>s.id!==id);
  await slotsGuardarLista(lista);
  const era=await slotActivoId()===id;
  const leg=await Store.get(LLAVE);
  if(era){
    const sig=slotMasNuevo(lista);
    if(sig){
      await slotFijarActivo(sig.id);
      const est=await partidaLeer(sig.id);
      if(est&&est.club) await partidaCopiaRapida(est); else await Store.del(LLAVE);
    } else {
      await slotFijarActivo(null);
      await Store.del(LLAVE);
    }
  } else if(leg&&leg._slot===id){
    await Store.del(LLAVE);
  }
  if(PARTIDAS.estado&&PARTIDAS.estado.sinDatos) PARTIDAS.estado.sinDatos=PARTIDAS.estado.sinDatos.filter(x=>x!==id);
}
/* borra el índice, cada ranura (también las que no están en la lista) y el save viejo: si no, al entrar volvía la partida */
async function borrarTodasLasPartidas(){
  const lista=await slotsLista();
  for(let i=0;i<lista.length;i++){ try{ await Store.del(slotKey(lista[i].id)); }catch(e){} }
  _lsLlavesPartida().forEach(_lsQuitar);
  if(_bdSoporta()) await bdVaciar();
  await slotsGuardarLista([]);
  await slotFijarActivo(null);
  await Store.del(LLAVE);
  if(PARTIDAS.estado) PARTIDAS.estado.sinDatos=[];
}
/* 7.9125 · abre la copia MÁS NUEVA que exista (IndexedDB, copia rápida o ranura vieja). Si la partida hace explotar
   normalizarEstado, E vuelve a como estaba y el error sube: el botón lo muestra (antes moría callado). */
async function cargarPartida(id){
  id=String(id);
  const est=await partidaLeer(id);
  if(!est||!est.club) return false;
  const prev=E;
  E=est; E._slot=id;
  try{ normalizarEstado(); if(typeof aplicarEstatutosMod==="function") aplicarEstatutosMod(); }
  catch(e){ E=prev; throw e; }
  await slotFijarActivo(id);
  await partidaCopiaRapida(E);
  return true;
}
/* migra el save único viejo a un slot la primera vez (sin perder nada) */
async function migrarSlots(){
  let lista=await slotsLista();
  if(lista.length) return lista;
  const legacy=await Store.get(LLAVE);
  if(legacy&&legacy.club){
    if(!legacy._slot) legacy._slot=nuevoSlotId();
    await Store.set(slotKey(legacy._slot),legacy);
    lista=[slotMetaDe(legacy)];
    await slotsGuardarLista(lista);
    await slotFijarActivo(legacy._slot);
  }
  return lista;
}

;
/* ==== js/partidas.js ==== */
"use strict";
/* ============================================================
   FUTBOLINI · partidas.js — 7.9125 · dónde viven tus partidas (y que "guardado" nunca mienta)

   Bug del autor (URGENTE): "aprieto Continuar en el inicio y no carga la partida anterior".
   Causa, reproducida en Chromium: una partida pesa ~0,5 MB después de una temporada (el 70 % son los planteles de
   los clubes CPU) y el navegador da ~5 MB de localStorage por sitio, con la partida abierta escrita DOS veces (su
   ranura + la clave vieja). Con ~9 partidas se llenaba: localStorage.setItem tiraba QuotaExceededError, el error
   se tragaba callado, el juego decía "guardado 14:14" y la ranura quedaba vacía (o con la versión vieja). Al volver,
   el botón de esa partida decía "No se pudo cargar esa partida".

   Ahora:
   · Las partidas viven en IndexedDB (cientos de MB, en el mismo equipo, sin internet ni cuenta). localStorage guarda
     solo la partida ABIERTA (la "copia rápida": se escribe sin esperar, y es lo que alcanza a quedar si cierras la
     pestaña de golpe), la lista de partidas y los ajustes.
   · Al abrir, las partidas que estaban en localStorage se mudan solas a IndexedDB (se verifica antes de borrar).
   · Se carga siempre la copia MÁS NUEVA que exista (IndexedDB, copia rápida o ranura vieja): cada guardado lleva su
     sello de tiempo (E._guardadoEn).
   · Si no se puede guardar, se dice fuerte (cartel con "Descargar partida") y el reloj de guardado no miente.
   · Una partida de la lista sin datos se muestra como tal (no como un botón muerto) y se puede quitar. Datos sin
     ficha en la lista (la lista se perdió o se pisó) vuelven solos a la lista.
   Sin IndexedDB (navegador viejo, algún modo privado): todo sigue en localStorage como antes, pero avisando.
   Doctor: guardado_honesto, partidas_inventario, continuar_carga (js/dev-banco.js). Prueba de punta a punta con el
   navegador de verdad: test/partidas.sh (va dentro de correr_dev.sh).
   ============================================================ */
var PARTIDAS={ bd:null, abriendo:null, sinBD:false, apagada:false, estado:null, ultimo:null, errLS:null,
  PREFIJO:"futbolini3_partida_", ESPERA_BD:4000, ESPERA_TX:8000 };

/* ---------- IndexedDB, sin librerías ---------- */
function _bdSoporta(){
  if(PARTIDAS.sinBD||PARTIDAS.apagada) return false;
  try{ return typeof indexedDB!=="undefined"&&!!indexedDB; }catch(e){ return false; }
}
function _esperarMs(ms){ return new Promise(r=>setTimeout(r,ms)); }
/* abre la base una vez. Si tarda más de 4 s (Safari a veces no contesta) esta llamada sigue sin BD, pero la apertura
   queda andando: si contesta después, los guardados siguientes ya la usan. Después de la primera espera larga, las
   siguientes esperan poco (si la base está colgada, cada guardado no puede pagar 4 s). */
function bdAbrir(){
  if(!_bdSoporta()) return Promise.resolve(null);
  if(PARTIDAS.bd) return Promise.resolve(PARTIDAS.bd);
  const espera=PARTIDAS.tardia?300:PARTIDAS.ESPERA_BD;
  if(!PARTIDAS.abriendo){
    PARTIDAS.abriendo=new Promise(res=>{
      try{
        const rq=indexedDB.open("futbolini",1);
        rq.onupgradeneeded=()=>{ try{ rq.result.createObjectStore("partidas"); }catch(e){} };
        rq.onsuccess=()=>{
          const db=rq.result;
          db.onversionchange=()=>{ try{ db.close(); }catch(e){} PARTIDAS.bd=null; PARTIDAS.abriendo=null; };
          PARTIDAS.bd=db; res(db);
        };
        rq.onerror=()=>{ PARTIDAS.sinBD=true; PARTIDAS.abriendo=null; res(null); };
      }catch(e){ PARTIDAS.sinBD=true; PARTIDAS.abriendo=null; res(null); }
    });
  }
  return Promise.race([PARTIDAS.abriendo, _esperarMs(espera).then(()=>{ if(!PARTIDAS.bd) PARTIDAS.tardia=true; return PARTIDAS.bd||null; })]);
}
/* una transacción con tope de tiempo: nunca deja colgado al que espera (guardar, cambiar de partida) */
function _bdTx(modo,hacer){
  return bdAbrir().then(db=>{
    if(!db) return {ok:false, err:"sin IndexedDB"};
    return new Promise(res=>{
      let listo=false, rq=null;
      const fin=r=>{ if(listo) return; listo=true; clearTimeout(reloj); res(r); };
      const reloj=setTimeout(()=>fin({ok:false, err:"IndexedDB no contestó"}),PARTIDAS.ESPERA_TX);
      try{
        const tx=db.transaction("partidas",modo);
        rq=hacer(tx.objectStore("partidas"));
        tx.oncomplete=()=>fin({ok:true, val:rq?rq.result:undefined});
        tx.onerror=()=>fin({ok:false, err:tx.error});
        tx.onabort=()=>fin({ok:false, err:tx.error});
      }catch(e){
        if(e&&e.name==="InvalidStateError"){ PARTIDAS.bd=null; PARTIDAS.abriendo=null; }   /* conexión cerrada: se reabre la próxima */
        fin({ok:false, err:e});
      }
    });
  });
}
function bdLeer(id){ return _bdTx("readonly",st=>st.get(String(id))).then(r=>r.ok?(r.val||null):null); }
function bdEscribir(id,reg){ return _bdTx("readwrite",st=>st.put(reg,String(id))).then(r=>r.ok); }
/* escribe solo si lo que hay es más viejo (la mudanza no puede pisar un guardado que llegó entre medio) */
function bdEscribirSiMasNueva(id,reg){
  return _bdTx("readwrite",st=>{
    const g=st.get(String(id));
    g.onsuccess=()=>{ const cur=g.result; if(!cur||(+cur.t||0)<(+reg.t||0)) st.put(reg,String(id)); };
    return g;
  }).then(r=>r.ok);
}
function bdBorrar(id){ return _bdTx("readwrite",st=>st.delete(String(id))).then(r=>r.ok); }
function bdVaciar(){ return _bdTx("readwrite",st=>st.clear()).then(r=>r.ok); }
function bdLlaves(){ return _bdTx("readonly",st=>st.getAllKeys()).then(r=>r.ok?(r.val||[]).map(String):null); }

/* ---------- localStorage (lo chico y la copia rápida) ---------- */
function _lsTxt(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } }
function _lsQuitar(k){ try{ localStorage.removeItem(k); }catch(e){} }
function _lsPoner(k,txt){ try{ localStorage.setItem(k,txt); return true; }catch(e){ PARTIDAS.errLS=e; return false; } }
function _lsLlavesPartida(){
  const out=[];
  try{ for(let i=0;i<localStorage.length;i++){ const k=localStorage.key(i); if(k&&k.indexOf(PARTIDAS.PREFIJO)===0) out.push(k); } }catch(e){}
  return out;
}
/* caracteres usados en localStorage (el tope del navegador va por ahí: ~5,2 millones en Chrome) */
function partidasUsoLS(){
  let n=0;
  try{ for(let i=0;i<localStorage.length;i++){ const k=localStorage.key(i)||""; n+=k.length+(localStorage.getItem(k)||"").length; } }catch(e){}
  return n;
}
function _jsonPartida(txt){
  if(!txt) return null;
  try{ const o=JSON.parse(txt); return (o&&typeof o==="object"&&o.club)?o:null; }catch(e){ return null; }
}
function _hayStorageExterno(){ return typeof window!=="undefined"&&!!(window.storage&&window.storage.set&&window.storage.get); }
function _selloDe(est){ return (est&&+est._guardadoEn)||0; }
function _errTxt(e){
  if(!e) return "";
  if(e.name==="QuotaExceededError"||/quota/i.test(String(e.message||e))) return "el navegador no tiene más espacio";
  return String(e.message||e.name||e).slice(0,120);
}
function slotMasNuevo(lista){
  return (lista||[]).slice().sort((a,b)=>((+b.t||+b.guardado||0)-(+a.t||+a.guardado||0)))[0]||null;
}

/* ---------- leer ---------- */
/* todas las copias que existen de una partida, la más nueva primero */
async function partidaCopias(id){
  id=String(id);
  const out=[];
  const sumar=(est,donde)=>{ if(est&&est.club){ est._slot=id; out.push({est:est, t:_selloDe(est), donde:donde}); } };
  if(_hayStorageExterno()){
    sumar(await Store.get(slotKey(id)),"storage");
    const j=await Store.get(LLAVE); if(j&&j._slot===id) sumar(j,"rapida");
  } else {
    sumar(_jsonPartida(_lsTxt(slotKey(id))),"ls");
    const j=_jsonPartida(_lsTxt(LLAVE)); if(j&&j._slot===id) sumar(j,"rapida");
    const r=await bdLeer(id); if(r&&r.txt) sumar(_jsonPartida(r.txt),"bd");
  }
  const pref={bd:0, storage:0, ls:1, rapida:2};
  out.sort((a,b)=>(b.t-a.t)||(pref[a.donde]-pref[b.donde]));
  return out;
}
async function partidaLeer(id){ const c=await partidaCopias(id); return c.length?c[0].est:null; }
/* al abrir el juego: la partida activa SIN esperar a IndexedDB, solo si la copia rápida (o la ranura vieja) es tan
   nueva como dice la lista. Si no, null: el botón de inicio la carga de la base (la más nueva). */
async function partidaRapidaInicio(id,lista){
  if(!id) return null;
  lista=lista||[];
  const meta=lista.find(s=>s.id===id);
  if(lista.length&&!meta) return null;   /* una partida borrada no vuelve por la copia rápida */
  if(_hayStorageExterno()){ const s=await Store.get(slotKey(id)); return (s&&s.club)?s:null; }
  const cand=[];
  const j=_jsonPartida(_lsTxt(LLAVE)); if(j&&j._slot===id) cand.push(j);
  const l=_jsonPartida(_lsTxt(slotKey(id))); if(l){ l._slot=id; cand.push(l); }
  cand.sort((a,b)=>_selloDe(b)-_selloDe(a));
  const g=cand[0]||null;
  return (g&&_selloDe(g)>=((meta&&+meta.t)||0))?g:null;
}

/* ---------- escribir ---------- */
/* copia rápida (síncrona) + copia durable (IndexedDB, o la ranura de localStorage si no hay base).
   Devuelve {ok, parcial, donde[], err}: ok = quedó una copia durable; parcial = solo quedó la copia rápida. */
async function partidaEscribir(est,txt){
  const id=String(est._slot), t=_selloDe(est)||Date.now();
  const res={ok:false, parcial:false, donde:[], err:"", t:t, kb:Math.round(txt.length/1024), id:id};
  if(_hayStorageExterno()){
    try{ await window.storage.set(slotKey(id),txt); await window.storage.set(LLAVE,txt); res.ok=true; res.donde.push("storage"); }
    catch(e){ res.err=_errTxt(e)||"no se pudo guardar"; }
    PARTIDAS.ultimo=res; return res;
  }
  PARTIDAS.errLS=null;
  /* 1) copia rápida: ANTES de cualquier await (al cerrar la pestaña es la única que alcanza a quedar) */
  const rapida=_lsPoner(LLAVE,txt);
  /* 2) copia durable */
  let bd=false;
  if(_bdSoporta()) bd=await bdEscribir(id,{id:id, t:t, club:est.club, anio:est.anio, txt:txt});
  if(bd){ res.donde.push("bd"); _lsQuitar(slotKey(id)); }   /* la ranura vieja de localStorage ya sobra */
  else if(_lsPoner(slotKey(id),txt)) res.donde.push("ls");
  if(rapida) res.donde.push("rapida");
  res.ok=bd||res.donde.indexOf("ls")>=0;
  res.parcial=!res.ok&&rapida;
  /* una copia rápida que no se pudo escribir quedó con datos viejos: si la durable sí quedó, se borra para que nadie
     la confunda con la buena (si no quedó ninguna, se deja: puede ser lo único que hay de esta partida) */
  if(!rapida&&res.ok) _lsQuitar(LLAVE);
  if(!res.ok) res.err=_errTxt(PARTIDAS.errLS)||"el navegador no dejó guardar";
  PARTIDAS.ultimo=res;
  return res;
}
/* la partida abierta pasa a ser la copia rápida (al cargar otra partida) */
async function partidaCopiaRapida(est){
  if(!est) return false;
  if(_hayStorageExterno()){ await Store.set(LLAVE,est); return true; }
  let ok=false; try{ ok=_lsPoner(LLAVE,JSON.stringify(est)); }catch(e){}
  if(!ok) _lsQuitar(LLAVE);   /* mejor sin copia rápida que con la de otra partida */
  return ok;
}
/* guarda YA la partida abierta (sin agrupar: eso lo hace rendimiento.js) */
async function partidaGuardarYa(){
  if(!E||E._bulkSim) return null;
  const est=E;
  est.saveVer=SAVE_VER;
  if(!est._slot) est._slot=nuevoSlotId();
  if(typeof saneaEstado==="function") saneaEstado(est);
  est._guardadoEn=Math.max(Date.now(),_selloDe(est)+1);
  const txt=JSON.stringify(est);
  const res=await partidaEscribir(est,txt);
  _ram[LLAVE]=est;
  if(res.ok||res.parcial){
    try{ await slotFijarActivo(est._slot); }catch(e){}
    try{ await slotActualizarIndice(est); }catch(e){}
  }
  avisoGuardado(res);
  if(res.ok&&typeof nubeAutoRespaldo==="function"){ try{ nubeAutoRespaldo(est); }catch(e){} }
  if(res.ok) partidasPedirPersistencia();
  return res;
}
async function partidaBorrarDatos(id){
  id=String(id);
  if(_hayStorageExterno()){ await Store.del(slotKey(id)); return; }
  _lsQuitar(slotKey(id)); delete _ram[slotKey(id)];
  if(_bdSoporta()) await bdBorrar(id);
}

/* ---------- que se note cuando NO se guardó ---------- */
function avisoGuardado(res){
  if(typeof document==="undefined"||!res) return;
  const n=document.getElementById("guardadoTxt");
  let hora=""; try{ hora=new Date().toLocaleTimeString("es-CL",{hour:"2-digit",minute:"2-digit",hour12:false}); }catch(e){}
  if(n){
    if(res.ok){
      _relojHora=hora;
      n.classList.remove("guardado-mal");
      n.textContent=_tjRelojTxt(hora);
    }else{
      n.textContent=res.parcial?"⚠️ guardado a medias":"⚠️ SIN GUARDAR";
      n.classList.add("guardado-mal");
    }
  }
  relojPintar();
  let b=document.getElementById("guardadoFallo");
  if(res.ok){ if(b) b.remove(); return; }
  if(!b){ b=document.createElement("div"); b.id="guardadoFallo"; b.className="guardado-fallo"; b.setAttribute("role","alert"); document.body.appendChild(b); }
  b.innerHTML="";
  const tit=document.createElement("b"); tit.textContent=res.parcial?"⚠️ Tu partida quedó guardada a medias":"⚠️ No se pudo guardar tu partida";
  const txt=document.createElement("span");
  txt.textContent=res.parcial
    ?"El navegador no tiene más espacio: solo quedó la copia rápida de esta pestaña. Descárgala para no perderla, o borra partidas viejas en Ajustes ▸ Mis partidas."
    :"Motivo: "+(res.err||"el navegador no dejó guardar")+". Descárgala ahora: si cierras, se pierde lo último.";
  const bd=el("button","btn-aqua chico verde"); bd.textContent="💾 Descargar partida";
  bd.onclick=function(){ if(typeof descargarPartida==="function") descargarPartida(); };
  const bp=el("button","btn-aqua chico"); bp.textContent="🗂️ Mis partidas";
  bp.onclick=function(){ if(typeof abrirAjustes==="function") abrirAjustes(); };
  const bx=el("button","btn-aqua chico"); bx.textContent="✕"; bx.title="Ocultar"; bx.setAttribute("aria-label","Ocultar aviso");
  bx.onclick=function(){ b.remove(); };
  b.appendChild(tit); b.appendChild(txt); b.appendChild(bd); b.appendChild(bp); b.appendChild(bx);
}
/* que el navegador no borre las partidas cuando le falte espacio. Sin preguntar solo si el juego está instalado como
   app (Chrome/Safari lo conceden sin cartel); en el resto lo pide el jugador desde Mis partidas. */
var _persistPedida=false;
function partidasPedirPersistencia(aMano){
  if(_persistPedida&&!aMano) return Promise.resolve(null);
  try{
    if(!navigator.storage||!navigator.storage.persist) return Promise.resolve(null);
    const app=!!(window.matchMedia&&window.matchMedia("(display-mode: standalone)").matches);
    if(!aMano&&!app) return Promise.resolve(null);
    _persistPedida=true;
    return navigator.storage.persist().catch(()=>false);
  }catch(e){ return Promise.resolve(null); }
}

/* ---------- mantenimiento al abrir: mudanza, inventario y rescate ---------- */
async function partidasMantener(){
  const rep={bd:false, movidas:0, quedanLS:0, recuperadas:[], sinDatos:[], conDatos:new Set(), total:0, enBD:0, usoLS:0, errores:[]};
  if(_hayStorageExterno()){ PARTIDAS.estado=rep; return rep; }
  const db=await bdAbrir(); rep.bd=!!db;
  /* 1) mudanza: ranuras de localStorage → IndexedDB (verificada antes de borrar) */
  if(db){
    for(const k of _lsLlavesPartida()){
      const id=k.slice(PARTIDAS.PREFIJO.length), txt=_lsTxt(k);
      const est=_jsonPartida(txt); if(!est) continue;   /* lo que no se entiende no se toca */
      const t=_selloDe(est);
      let ok=await bdEscribirSiMasNueva(id,{id:id, t:t, club:est.club, anio:est.anio, txt:txt});
      if(ok){ const v=await bdLeer(id); ok=!!(v&&v.txt&&(+v.t||0)>=t); }
      if(ok){ _lsQuitar(k); rep.movidas++; } else rep.errores.push("no se pudo mudar "+id);
    }
    /* 2) la copia rápida también queda en la base si es más nueva (por si la base no alcanzó al cerrar) */
    const jt=_lsTxt(LLAVE), j=_jsonPartida(jt);
    if(j&&j._slot) await bdEscribirSiMasNueva(j._slot,{id:j._slot, t:_selloDe(j), club:j.club, anio:j.anio, txt:jt});
  }
  /* 3) inventario: qué partidas tienen datos */
  _lsLlavesPartida().forEach(k=>{ rep.conDatos.add(k.slice(PARTIDAS.PREFIJO.length)); rep.quedanLS++; });
  if(db){ const ll=await bdLlaves(); (ll||[]).forEach(id=>rep.conDatos.add(id)); rep.enBD=(ll||[]).length; }
  const j=_jsonPartida(_lsTxt(LLAVE)); if(j&&j._slot) rep.conDatos.add(j._slot);
  /* 4) rescate: datos sin ficha en la lista vuelven a la lista */
  const lista=await slotsLista(), enLista=new Set(lista.map(s=>s.id));
  for(const id of rep.conDatos){
    if(enLista.has(id)) continue;
    const est=await partidaLeer(id); if(!est||!est.club) continue;
    const m=slotMetaDe(est); m.guardado=_selloDe(est)||m.guardado; m.recuperada=true;
    lista.push(m); rep.recuperadas.push(id);
  }
  if(rep.recuperadas.length) await slotsGuardarLista(lista);
  /* 5) fichas sin datos: se marcan (no se borran solas: decide el jugador) */
  rep.sinDatos=lista.filter(s=>!rep.conDatos.has(s.id)).map(s=>s.id);
  rep.total=lista.length;
  rep.usoLS=partidasUsoLS();
  PARTIDAS.estado=rep;
  return rep;
}
/* texto para Mis partidas: dónde están y cuánto ocupan */
function partidasResumenTxt(){
  const r=PARTIDAS.estado; if(!r) return "";
  const mb=Math.round(r.usoLS/104857.6)/10;
  return (r.bd?"Tus partidas viven en la base del navegador (IndexedDB): caben muchas, sin internet. ":"Este navegador no deja usar IndexedDB: las partidas van en localStorage (caben ~8). ")+
    "Copia rápida y ajustes: "+mb+" MB de ~5 MB.";
}
/* descargar CUALQUIER partida de la lista (no solo la abierta): sirve para rescatar una que no abre */
async function descargarPartidaDe(id){
  const est=await partidaLeer(id);
  if(!est){ if(typeof aviso==="function") aviso("Esa partida no tiene datos guardados"); return false; }
  const paquete={app:"futbolini", saveVer:(typeof SAVE_VER==="number"?SAVE_VER:est.saveVer||1), guardado:Date.now(), E:est};
  const blob=new Blob([JSON.stringify(paquete)],{type:"application/json"}), url=URL.createObjectURL(blob);
  const nombre="futbolini-"+String(est.clubNombre||est.club||"club").toLowerCase().replace(/[^a-z0-9]+/g,"-")+"-"+(est.anio||"")+".fut";
  const a=el("a"); a.href=url; a.download=nombre; document.body.appendChild(a); a.click();
  setTimeout(()=>{ a.remove(); URL.revokeObjectURL(url); },200);
  return true;
}

/* 7.9140 · reloj de la esquina: hora del último guardado que sí quedó, y tiempo jugado.
   El error no se toca: "⚠️ SIN GUARDAR" y "⚠️ guardado a medias" siguen igual (guardado_honesto).
   El tiempo solo corre con la pestaña visible. Cada tick suma como máximo 2 s para que el reloj
   virtual de las pruebas no meta horas de un saque. */
var _tjUlt=0, _tjSesion=0, _tjForzar=null, _relojHora="";
function tiempoJugadoVisible(){
  if(_tjForzar===true) return true;
  if(_tjForzar===false) return false;
  try{ return typeof document==="undefined" || document.visibilityState!=="hidden"; }catch(e){ return true; }
}
function _tjHoyClave(){
  const d=new Date();
  return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
}
function _tjTxt(seg){
  seg=Math.max(0, Math.floor(+seg||0));
  const h=Math.floor(seg/3600), m=Math.floor((seg%3600)/60);
  if(h>0) return h+" h "+m+" min";
  if(m>0) return m+" min";
  return seg+" s";
}
function tiempoJugadoSumar(seg){
  if(!tiempoJugadoVisible()) return 0;
  if(typeof E==="undefined"||!E||E._bulkSim) return 0;
  seg=+seg; if(!(seg>0)) return 0;
  _tjSesion+=seg;
  E.tiempoJugado=(+E.tiempoJugado||0)+seg;
  const k=_tjHoyClave();
  if(!E.tiempoHoy||E.tiempoHoy.dia!==k) E.tiempoHoy={dia:k, seg:0};
  E.tiempoHoy.seg=(+E.tiempoHoy.seg||0)+seg;
  return seg;
}
function _tjHoySeg(){
  if(typeof E!=="undefined"&&E&&E.tiempoHoy&&E.tiempoHoy.dia===_tjHoyClave()) return +E.tiempoHoy.seg||0;
  return _tjSesion;
}
function _tjRelojTxt(hora){
  const hoy=(typeof T==="function")?T("reloj_hoy","hoy"):"hoy";
  const tot=(typeof T==="function")?T("reloj_total","total"):"total";
  const hoyS=_tjTxt(_tjHoySeg());
  const totS=_tjTxt(typeof E!=="undefined"&&E?(+E.tiempoJugado||0):0);
  return "💾 "+(hora||"—")+" · ⏱ "+hoy+" "+hoyS+" · "+tot+" "+totS;
}
function relojAjustesTxt(){
  const et=(typeof T==="function")?T("aj_reloj","Tiempo jugado"):"Tiempo jugado";
  const hoy=(typeof T==="function")?T("reloj_hoy","hoy"):"hoy";
  const tot=(typeof T==="function")?T("reloj_total","total"):"total";
  return et+": "+hoy+" "+_tjTxt(_tjHoySeg())+" · "+tot+" "+_tjTxt(typeof E!=="undefined"&&E?(+E.tiempoJugado||0):0)+" · 💾 "+(_relojHora||"—");
}
function relojPintar(){
  const n=typeof document!=="undefined"?document.getElementById("guardadoTxt"):null;
  if(n){
    const malo=n.classList.contains("guardado-mal");
    const fallo=typeof PARTIDAS!=="undefined"&&PARTIDAS.ultimo&&PARTIDAS.ultimo.ok===false;
    const txt=n.textContent||"";
    if(!malo && !fallo && txt.indexOf("SIN GUARDAR")<0 && txt.indexOf("guardado a medias")<0){
      n.textContent=_tjRelojTxt(_relojHora);
    }
  }
  const aj=typeof document!=="undefined"?document.getElementById("relojAjustes"):null;
  if(aj) aj.textContent=relojAjustesTxt();
}
function _tjTick(){
  const ahora=Date.now();
  if(!_tjUlt){ _tjUlt=ahora; relojPintar(); return; }
  let dt=(ahora-_tjUlt)/1000;
  _tjUlt=ahora;
  if(dt<0) dt=0;
  if(dt>2) dt=2;
  if(tiempoJugadoVisible()&&dt>0) tiempoJugadoSumar(dt);
  relojPintar();
}
if(typeof document!=="undefined"&&typeof setInterval==="function"){
  setInterval(_tjTick, 1000);
  document.addEventListener("visibilitychange", function(){ _tjUlt=Date.now(); });
}

