    if(pal78){ pal78.squad="PLANTEL_PAL_1978"; pal78.desc="Campeón del Nacional 1978. Elías Figueroa de eje, Óscar Fabbiani goleador (35) y 44 fechas invicto. Dirigía Caupolicán Peña."; }
