/* 7.998 · tope de cambios IFAB: 2 hasta 1994, 3 desde 1995, 5 desde 2020 (COVID, permanente 2022). */
function cambiosMaxEra(anio){
  anio=anio||((typeof E!=="undefined"&&E&&E.anio)||2026);
  if(anio>=2020) return 5;
  if(anio>=1995) return 3;
  return 2;
}
function ventanasMaxEra(anio){
  anio=anio||((typeof E!=="undefined"&&E&&E.anio)||2026);
  return anio>=2020?3:99;
}
/* 7.999 · lista de concentrados (nomina): 16 hasta 1994 (11+5), 18 hasta 2019 (11+7), 23 desde 2020 (11+12). */
function listaMaxEra(anio){
  anio=anio||((typeof E!=="undefined"&&E&&E.anio)||2026);
  if(anio>=2020) return 23;
  if(anio>=1995) return 18;
  return 16;
}
function bancaMaxEra(anio){ return Math.max(1, listaMaxEra(anio)-11); }
function dispPlantel(){
  return (E&&E.plantel||[]).filter(j=>!j.vendido&&!j.cedido&&!(j.lesion>0));
}
function bancaIdeal(once){
  once=once||[];
  const disp=dispPlantel().filter(j=>once.indexOf(j)<0);
  const n=bancaMaxEra();
  const arqs=disp.filter(j=>j.pos==="ARQ").sort((a,b)=>scoreOnce(b)-scoreOnce(a));
  const resto=disp.filter(j=>j.pos!=="ARQ").sort((a,b)=>scoreOnce(b)-scoreOnce(a));
  const out=[];
  if(arqs[0]) out.push(arqs[0]);
  resto.forEach(j=>{ if(out.length<n) out.push(j); });
  arqs.slice(1).forEach(j=>{ if(out.length<n && out.indexOf(j)<0) out.push(j); });
  return out.slice(0,n);
}
function listaIdeal(once){
  once=once||onceIdeal();
  const cupo=bancaMaxEra();
  if(E.tactica && Array.isArray(E.tactica.bancaManual) && E.tactica.bancaManual.length){
    const disp=dispPlantel().filter(j=>once.indexOf(j)<0);
    let banca=E.tactica.bancaManual.map(n=>disp.find(j=>j.n===n)).filter(Boolean);
    if(banca.length<cupo){
      const extra=bancaIdeal(once).filter(j=>banca.indexOf(j)<0);
      banca=banca.concat(extra).slice(0,cupo);
    }
    return once.concat(banca.slice(0,cupo));
  }
  return once.concat(bancaIdeal(once));
}
function estrellasCortadas(once){
  once=once||onceIdeal();
  const lista=listaIdeal(once);
  const names=lista.map(j=>j&&j.n);
  return dispPlantel().filter(j=>names.indexOf(j.n)<0 && ((j.nivel||0)>=74 || (j.rasgos&&(j.rasgos.indexOf("ídolo")>=0||j.rasgos.indexOf("capitán")>=0))));
}
function calcularDescuento(P){
  const goles=(P.gl||0)+(P.gv||0);
  const cambios=P.cambios||0;
  const tarj=(P.tarjetas||[]).length;
  const les=(P.lesionados||[]).length;
  let n=2+Math.min(2,goles)+(cambios>=3?1:0)+(tarj>=3?1:0)+(les?1:0);
  return (typeof clamp==="function")?clamp(n,2,7):Math.max(2,Math.min(7,n));
}
function topePartido(P){
  if(P && P.tanda) return P.min||120;
  if(P && P.prorroga===2) return 120;
  if(P && P.prorroga===1) return 105;
  return 90+(P&&P.descuento2||0);
}
function textoReloj(P,pausado){
  if(!P) return "";
  const p=pausado?"⏸ ":"";
  if(P.terminado) return "Final del partido";
  if(P.tanda){
    const t=P.tanda;
    return p+"Tanda "+(t.yo||0)+"-"+(t.el||0)+(t.done?(t.gano?" · pasamos":" · fuera"):"");
  }
  if(P.prorroga===1) return p+"Prórroga "+P.min+"' · 1E";
  if(P.prorroga===2) return p+"Prórroga "+P.min+"' · 2E";
  if(P.min<45) return p+"Minuto "+P.min+" · 1T";
  if(P.min<90) return p+"Minuto "+P.min+" · 2T";
  const extra=Math.max(1,P.min-90);
  const cupo=P.descuento2||0;
  return p+"90+"+extra+(cupo?" · descuento "+cupo+"'":" · descuento");
}
/* 7.9005 · llave que no puede quedar empatada: copa KO, playoff de 4°s, final única. */
function esLlaveDirecta(part){
  if(!part) return false;
  if(part.fase==="playoff4") return true;
  if(part.tipo!=="copa") return false;
  const r=String(part.ronda||"");
  if(/Grupo|Fase de grupos|Zona\s/i.test(r)) return false;
  return true;
}
function pideProrroga(part){
  if(!part) return false;
  /* Copa Argentina: bases reales, partido único SIN alargue (documentado en el juego). */
  if(/Copa Argentina/i.test(part.torneo||"")) return false;
  return esLlaveDirecta(part);
}
function esPartidoUnicoDesempate(part){
  if(!esLlaveDirecta(part)) return false;
  if(part.fase==="playoff4") return true;
  const r=String(part.ronda||""), t=String(part.torneo||"");
  if(/Copa Argentina/i.test(t)) return true;
  if(/FINAL/i.test(r) && /Copa Chile/i.test(t)) return true;
  if(/Primera fase/i.test(r)) return true;
  if(typeof esEraHardcode==="function" && typeof E!=="undefined" && E && !esEraHardcode(E.eraBase) && part.tipo==="copa") return true;
  const same=((typeof E!=="undefined"&&E&&E.calendario)||[]).filter(function(p){
    return p && p.tipo==="copa" && p.torneo===part.torneo && p.ronda===part.ronda;
  });
  return same.length<=1;
}
function marcadorDefine(P){
  if(!P||!P.part) return {necesita:false, yo:0, otro:0};
  const [yo,otro]=miMarcador(P);
  if(P.diosForzar) return {necesita:false, yo:yo, otro:otro};
  if(!esLlaveDirecta(P.part)) return {necesita:false, yo:yo, otro:otro};
  if(esPartidoUnicoDesempate(P.part)) return {necesita:yo===otro, yo:yo, otro:otro};
  const part=P.part;
  const same=((E&&E.calendario)||[]).filter(function(p){
    return p && p.tipo==="copa" && p.torneo===part.torneo && p.ronda===part.ronda;
  });
  const pending=same.filter(function(p){ return !p.jugado && p!==part; });
  if(pending.length) return {necesita:false, yo:yo, otro:otro};
  const key=/Copa Chile/i.test(part.torneo||"") ? ("CC-"+part.ronda) : part.ronda;
  const acc=(E.flags&&E.flags.copaAcum&&E.flags.copaAcum[key])||{gf:0,gc:0};
  return {necesita:(acc.gf+yo)===(acc.gc+otro), yo:yo, otro:otro, acumYo:acc.gf+yo, acumEl:acc.gc+otro};
}
function ordenTanda(once){
  const c=(once||[]).filter(function(j){ return j && j.pos!=="ARQ"; });
  const punt=function(j){
    return (j.nivel||60)
      +((j.rasgos&&j.rasgos.indexOf("penales")>=0)?25:0)
      +((j.rasgos&&(j.rasgos.indexOf("frio de definicion")>=0||j.rasgos.indexOf("definición")>=0))?12:0);
  };
  return c.slice().sort(function(a,b){ return punt(b)-punt(a); });
}
function tandaPuedeCortar(t){
  if(!t) return false;
  const nYo=t.seq.filter(function(x){ return x.lado==="yo"; }).length;
  const nEl=t.seq.filter(function(x){ return x.lado==="el"; }).length;
  if(nYo<5 || nEl<5){
    const remainYo=5-nYo, remainEl=5-nEl;
    if(t.yo+remainYo < t.el) return true;
    if(t.el+remainEl < t.yo) return true;
    return false;
  }
  if(nYo===nEl && nYo>=5 && t.yo!==t.el) return true;
  return false;
}
function iniciarTanda(P){
  if(!P) return {tipo:"fin",min:0};
  const mios=ordenTanda(P.once);
  const sus=(P.rivalPlantel||[]).filter(function(x){ return x && x.pos!=="ARQ"; });
  P.tanda={yo:0, el:0, seq:[], done:false, gano:false, mios:mios, sus:sus};
  if(typeof linea==="function") linea(P,P.min,"Siguen empate. Se van a la tanda de penales.","grave");
  return {tipo:"tanda", min:P.min};
}
function cobrarTandaAuto(P, aFavor){
  const t=P.tanda; if(!t) return false;
  const nYo=t.seq.filter(function(x){ return x.lado==="yo"; }).length;
  const nEl=t.seq.filter(function(x){ return x.lado==="el"; }).length;
  const pat=aFavor
    ? (t.mios[nYo % Math.max(1,t.mios.length)]||{n:"tu pateador",nivel:70})
    : (t.sus[nEl % Math.max(1,t.sus.length)]||{n:"el rival",nivel:70});
  const arq=aFavor
    ? ((typeof arqueroDe==="function")?arqueroDe(P.rivalPlantel):null)
    : ((typeof arqueroDe==="function")?arqueroDe(P.once):null);
  const gol=(typeof cobrarPenal==="function")?cobrarPenal(pat, arq||{nivel:70}):Math.random()<0.72;
  t.seq.push({lado:aFavor?"yo":"el", gol:!!gol, n:pat.n});
  if(gol){ if(aFavor) t.yo++; else t.el++; }
  if(typeof linea==="function"){
    linea(P,P.min,
      (aFavor?(pat.n+" "):( (P.part&&P.part.rivalNombre)||"el rival")+" ("+pat.n+") ")+(gol?"la manda adentro.":"falla.")+" Tanda "+t.yo+"-"+t.el+".",
      gol?"gol":"grave");
  }
  return !!gol;
}
function cerrarTanda(P){
  const t=P.tanda; if(!t) return;
  t.done=true;
  t.gano=t.yo>t.el;
  if(P.part) P.part.penales={yo:t.yo, el:t.el, gano:t.gano};
  if(typeof linea==="function"){
    linea(P,P.min, t.gano
      ? ("¡Pasamos en penales "+t.yo+"-"+t.el+"!")
      : ("Fuera en penales "+t.yo+"-"+t.el+"."), "grave");
  }
}
function simularTanda(P){
  if(!P) return null;
  if(!P.tanda) iniciarTanda(P);
  const t=P.tanda;
  let guard=0;
  while(!t.done && guard++<28){
    const nYo=t.seq.filter(function(x){ return x.lado==="yo"; }).length;
    const nEl=t.seq.filter(function(x){ return x.lado==="el"; }).length;
    const tocaYo=nYo<=nEl;
    cobrarTandaAuto(P, tocaYo);
    if(tandaPuedeCortar(t)) cerrarTanda(P);
  }
  if(!t.done) cerrarTanda(P);
  return t;
}
function intentarDesempate(P){
  if(!P) return {tipo:"fin",min:0};
  if(P.tanda) return {tipo:P.tanda.done?"tandaFin":"tanda", min:P.min};
  const d=marcadorDefine(P);
  if(!d.necesita) return {tipo:"fin", min:P.min};
  if(pideProrroga(P.part) && !P.prorroga){
    P.prorroga=1;
    if(typeof linea==="function") linea(P,P.min,"Empate "+((typeof marcadorTxt==="function")?marcadorTxt(P):"")+". Hay prórroga: treinta minutos más.","grave");
    return {tipo:"prorroga", min:P.min};
  }
  if(P.prorroga===1 && P.min>=105){
    P.prorroga=2;
    if(typeof linea==="function") linea(P,105,"Descanso de la prórroga. Van "+((typeof marcadorTxt==="function")?marcadorTxt(P):"")+".","grave");
    return {tipo:"prorrogaHT", min:105};
  }
  if(P.prorroga===2 && P.min>=120){
    /* 7.9035 · d.necesita ya mira el GLOBAL: en una llave a dos partidos el marcador
       de la vuelta puede no estar empatado y el global sí (antes se cortaba sin tanda) */
    return iniciarTanda(P);
  }
  if(!pideProrroga(P.part)) return iniciarTanda(P);
  return {tipo:"fin", min:P.min};
}

/* ---------- pizarra libre ----------
   La cancha es una grilla de 5 columnas (0=izq … 4=der) × 5 filas
   (0=nuestra defensa … 4=ataque rival). Cada titular ocupa una celda.
   De la distribución se deduce la forma táctica (ataque/orden/ancho),
   permitiendo esquemas asimétricos o bizarros. */
var PIZ_FILAS=5, PIZ_COLS=5;
/* Posiciones por defecto a partir de una formación clásica. */
function pizarraDesdeFormacion(once){
  const f=FORMACIONES[E.tactica.form]||FORMACIONES["4-4-2"];
  const piz=[];
  const arq=once.filter(j=>j.pos==="ARQ").slice(0,1);
  const resto=once.filter(j=>!arq.includes(j));
  const filaDe=(idx)=>{ // reparte por líneas def/vol/del
    if(idx<f.def) return 1;
    if(idx<f.def+f.vol) return 2;
    return 3;
  };
  const porFila={1:[],2:[],3:[]};
  resto.forEach((j,i)=>{ (porFila[filaDe(i)]=porFila[filaDe(i)]||[]).push(j); });
  if(arq[0]) piz.push({n:arq[0].n,pos:"ARQ",r:0,c:2});
  [1,2,3].forEach(r=>{
    const linea=porFila[r]||[];
    linea.forEach((j,i)=>{
      const c=linea.length===1?2:Math.round(i*(PIZ_COLS-1)/(linea.length-1));
      piz.push({n:j.n,pos:j.pos,r:r,c:c});
    });
  });
  return piz;
}
/* Deduce la forma táctica desde las celdas ocupadas. */
function formaLibre(piz){
  if(!piz||!piz.length) return null;
  const out=piz.filter(p=>p.pos!=="ARQ");
  if(!out.length) return null;
  const avgR=out.reduce((s,p)=>s+p.r,0)/out.length;                 // 0..4
  const def=out.filter(p=>p.r<=1).length, atk=out.filter(p=>p.r>=3).length;
  const cols=out.map(p=>p.c), meanC=cols.reduce((a,b)=>a+b,0)/cols.length;
  const spread=Math.sqrt(cols.reduce((s,c)=>s+(c-meanC)*(c-meanC),0)/cols.length);
  const asim=Math.abs(meanC-(PIZ_COLS-1)/2);
  return {
    ataque:(avgR-2)*3 + (atk-2)*2,
    orden:(2-avgR)*2.5 + (def-3)*2 - asim*1.6,
    ancho:(spread-1.3)*2
  };
}
function scoreOnce(j){
  const same=E.plantel.filter(x=>!x.vendido&&!x.cedido&&(x.lesion||0)<=0&&x.pos===j.pos)
    .sort((a,b)=>b.nivel-a.nivel);
  const i=same.findIndex(x=>x.n===j.n);
  const rolN=i>1?-7:(i===1?-2:0);
  return j.nivel*0.52+(j.forma||70)*0.20+(j.moral||70)*0.18-((j.cansancio||0)*0.35)+rolN;
}
function onceIdeal(){
  const disp=E.plantel.filter(j=>!j.vendido&&!j.cedido&&(j.lesion||0)<=0);
  /* 6.8 · XI manual: si el DT armó su once, se respeta (y se completa si alguno se lesionó/vendió) */
  if(E.tactica && Array.isArray(E.tactica.xiManual) && E.tactica.xiManual.length){
    let once=E.tactica.xiManual.map(n=>disp.find(j=>j.n===n)).filter(Boolean);
    if(once.length<11){
      const resto=disp.filter(j=>once.indexOf(j)<0).sort((a,b)=>scoreOnce(b)-scoreOnce(a));
      once=once.concat(resto.slice(0,11-once.length));
    }
    if(once.length>=11) return once.slice(0,11);
  }
  const f=FORMACIONES[E.tactica.form]||FORMACIONES["4-4-2"];
  const pick=(pos,n)=>disp.filter(j=>j.pos===pos).sort((a,b)=>scoreOnce(b)-scoreOnce(a)).slice(0,n);
  let once=pick("ARQ",1).concat(pick("DEF",f.def),pick("VOL",f.vol),pick("DEL",f.del));
  if(once.length<11){
    const resto=disp.filter(j=>!once.includes(j)).sort((a,b)=>scoreOnce(b)-scoreOnce(a));
    once=once.concat(resto.slice(0,11-once.length));
  }
  return once;
}
function esClasico(part){
  const grandes=["CC","UCH","UC"];
  const riv=part&&part.rivalId;
  if(grandes.indexOf(E.club)>=0 && grandes.indexOf(riv)>=0) return true;
  /* 7.00 · rivalidades regionales de los clubes nuevos */
  if(typeof esRivalidadRegional==="function" && esRivalidadRegional(E.club,riv)) return true;
  return false;
}
function fuerzaEquipo(once){
  if(!once.length) return 40;
  /* 7.9029 · escala 1:1 con el nivel (la misma de fuerzaRival). La vieja
     (nivel×0,68 + constantes) aplastaba todo a ~70: con un chico eras grande y
     con un grande eras del montón. Las partidas viejas siguen con la vieja. */
  const v2=(typeof E!=="undefined"&&E&&E._fuerzaV===2);
  const base=v2
    ? once.reduce((s,j)=>s+j.nivel+((j.forma||70)-70)*0.16+((j.moral||70)-70)*0.10-(j.cansancio||0)*0.22,0)/once.length
    : once.reduce((s,j)=>s+j.nivel*0.68+j.forma*0.16+j.moral*0.10-(j.cansancio||0)*0.22,0)/once.length;
  const f=FORMACIONES[E.tactica.form]||FORMACIONES["4-4-2"];
  const es=ESTILOS[E.tactica.estilo]||ESTILOS["Equilibrado"];
  const pr=PRESIONES[E.tactica.presion]||PRESIONES["Media"];
  const me=MENTALIDADES[E.tactica.mentalidad]||MENTALIDADES["Equilibrado"];
  const bl=(typeof BLOQUES!=="undefined"&&BLOQUES[E.tactica.bloque])||{ataque:0,orden:0,desgaste:0};
  const rt=(typeof RITMOS!=="undefined"&&RITMOS[E.tactica.ritmo])||{ataque:0,orden:0,desgaste:0};
  const libre=(E.tactica.pizarra&&E.tactica.pizarra.length)?formaLibre(E.tactica.pizarra):null;
  const shape=libre||f.ef;
  /* 6.13 · roles/duties por jugador (estilo FM): la suma de duties inclina al equipo */
  let rolA=0, rolO=0;
  if(E.tactica.roles){
    once.forEach(j=>{ const d=E.tactica.roles[j.n];
      if(d==="ofe"){ rolA+=1.3; rolO-=1.0; } else if(d==="def"){ rolA-=1.0; rolO+=1.3; } });
  }
  return {
    base:base,
    ataque:base+((shape.ataque||0)+es.ataque+pr.ataque+me.ataque+(bl.ataque||0)+(rt.ataque||0))*1.2+(E.ind.moral-55)*0.08+(shape.ancho||0)*0.6+rolA*1.1,
    orden:base+((shape.orden||0)+es.orden+pr.orden+me.orden+(bl.orden||0)+(rt.orden||0))*1.2+(E.ind.plantel-55)*0.05+rolO*1.1,
    desgaste:es.desgaste+pr.desgaste+me.desgaste+(bl.desgaste||0)+(rt.desgaste||0)
  };
}
/* 7.99952 · snapshot del plan táctico (mentalidad/estilo/presión/bloque/ritmo).
   Sirve para reaplicar en vivo sin resetear goles, empuje ni momentos. */
function snapshotPlan(once){
  once=once||[];
  const fz=fuerzaEquipo(once);
  if(!fz||typeof fz!=="object") return {ataque:40,orden:40,desgaste:0,recup:0,expo:0};
  const pr=(typeof PRESIONES!=="undefined"&&PRESIONES[E.tactica.presion])||{recup:0,expo:0};
  const me=(typeof MENTALIDADES!=="undefined"&&MENTALIDADES[E.tactica.mentalidad])||{recup:0,expo:0};
  const bl=(typeof BLOQUES!=="undefined"&&BLOQUES[E.tactica.bloque])||{recup:0,expo:0};
  return {
    ataque:fz.ataque, orden:fz.orden, desgaste:fz.desgaste,
    recup:(pr.recup||0)+(me.recup||0)+(bl.recup||0),
    expo:(pr.expo||0)+(me.expo||0)+(bl.expo||0)
  };
}
function reaplicarPlan(P){
  if(!P||!E||!E.tactica) return null;
  const prev=P._planSnap||snapshotPlan(P.once||[]);
  const now=snapshotPlan(P.once||[]);
  P.ataque+=(now.ataque-prev.ataque);
  P.orden+=(now.orden-prev.orden);
  P.desgaste+=(now.desgaste-prev.desgaste);
  P.recup=(P.recup||0)+(now.recup-prev.recup);
  P.expo=(P.expo||0)+(now.expo-prev.expo);
  P._planSnap=now;
  P._ajustes=(P._ajustes||0)+1;
  if(P._ajustes>=3){ P.orden-=1.1; } /* demasiado retoque: el equipo se mareá */
  return now;
}
/* 6.7 · detecta la formación desde la pizarra (incl. bizarras tipo 2-4-4) */
function formacionDetectada(piz){
  if(!piz||!piz.length) return null;
  const out=piz.filter(p=>p.pos!=="ARQ");
  if(out.length<9) return null;
  const def=out.filter(p=>p.r<=1).length;
  const del=out.filter(p=>p.r>=3).length;
  const vol=out.length-def-del;
  return def+"-"+vol+"-"+del;
}
/* ============================================================
   6.30 · QUÍMICA DEL EQUIPO
   Los que se llevan bien rinden más. La química de un par es
   determinística (edad, rasgos compartidos, de la casa, partidos
   juntos, y un "click/roce" fijo por par) → estable, no azar por
   partido. Se dibuja en la pizarra y suma/resta nivel real.
   ============================================================ */
/* 7.9052 · partidos jugados juntos por cada par del once */
function registrarJuntos(once){
  if(!E||!once) return;
  E.juntos=E.juntos||{};
  for(let i=0;i<once.length;i++) for(let j=i+1;j<once.length;j++){
    const a=once[i].n, b=once[j].n, k=a<b?a+"|"+b:b+"|"+a;
    E.juntos[k]=(E.juntos[k]||0)+1;
  }
  /* poda: solo pares de jugadores que siguen en el plantel (la partida no crece sin fin) */
  const ks=Object.keys(E.juntos);
  if(ks.length>1500){
    const vivos={}; (E.plantel||[]).forEach(x=>{ if(!x.vendido) vivos[x.n]=1; });
    ks.forEach(k=>{ const pr=k.split("|"); if(!vivos[pr[0]]||!vivos[pr[1]]) delete E.juntos[k]; });
  }
}
function hashStr(s){ let h=0; for(let i=0;i<(s||"").length;i++){ h=(h*31+s.charCodeAt(i))|0; } return h; }
function quimicaPar(a,b){
  if(!a||!b||a===b) return 50;
  const key=a.n<b.n?a.n+"|"+b.n:b.n+"|"+a.n;
  let q=52;
  const de=Math.abs((a.edad||25)-(b.edad||25));
  q+= de<=3?12:(de<=6?4:(de>=10?-10:0));
  const rs=(a.rasgos||[]).filter(r=>(b.rasgos||[]).indexOf(r)>=0).length;
  q+= rs*6;
  if((a.rasgos||[]).indexOf("de la casa")>=0 && (b.rasgos||[]).indexOf("de la casa")>=0) q+=10;
  /* 7.9052 · la química crece con partidos JUNTOS en el once (continuidad), no con partidos sueltos */
  if(E&&E.juntos) q+= Math.min(14,(E.juntos[a.n<b.n?a.n+"|"+b.n:b.n+"|"+a.n]||0)*0.7);
  else q+= Math.min(10,(Math.min(a.partidos||0,b.partidos||0))/8);
  q+= (Math.abs(hashStr(key))%25)-12;   /* click (+) o roce (−) fijo del par */
  return clamp(Math.round(q),5,99);
}
/* pares "conectados": vecinos en la pizarra (dist<=2) o, si no hay, misma línea */
function paresConectados(once){
  const piz=E.tactica&&E.tactica.pizarra;
  const posDe={};
  if(piz){ piz.forEach(p=>{ posDe[p.n]={r:p.r,c:p.c}; }); }
  const pares=[];
  for(let i=0;i<once.length;i++) for(let j=i+1;j<once.length;j++){
    const a=once[i],b=once[j]; let conecta=false;
    if(piz && posDe[a.n] && posDe[b.n]){
      const d=Math.abs(posDe[a.n].r-posDe[b.n].r)+Math.abs(posDe[a.n].c-posDe[b.n].c);
      conecta=d<=2;
    } else { conecta=(a.pos===b.pos); }
    if(conecta) pares.push([a,b]);
  }
  return pares;
}
function quimicaEquipo(once){
  const pares=paresConectados(once);
  const lazos=pares.map(([a,b])=>{ const q=quimicaPar(a,b); return {a:a.n,b:b.n,q:q,bueno:q>=64,malo:q<=42}; });
  if(!lazos.length) return {prom:55,bono:0,lazos:[],buenos:0,malos:0,total:0};
  const total=lazos.length;
  const buenos=lazos.filter(l=>l.bueno).length;
  const malos=lazos.filter(l=>l.malo).length;
  const media=lazos.reduce((s,l)=>s+l.q,0)/total;
  /* 3.a · antes se promediaba a secas y se aplastaba cerca de 52 (nunca pasaba de ~56).
     Ahora la media se AMPLIFICA con el balance bueno/malo de los lazos conectados, así
     juntar a los que congenian se nota de verdad y se puede llegar alto (o bajo). */
  let prom=Math.round(media + (buenos-malos)/total*40);
  prom=clamp(prom,15,100);   /* 7.9089 · con duplas trabajadas se llega a 100 (pizarra-auto.js) */
  /* 7.9079 · la química heredada se EXPRESA con partidos juntos: al llegar el DT pesa el 40 % y llega
     al 100 % cuando el once suma ~12 partidos juntos. Antes una partida nueva arrancaba con −4 a +5,3
     según un sorteo por pareja (medido en 47 clubes) y eso movía ±0,3 pts/partido (doctor motor_vs_ia). */
  let jm=0; if(E&&E.juntos){ pares.forEach(([a,b])=>{ jm+=E.juntos[a.n<b.n?a.n+"|"+b.n:b.n+"|"+a.n]||0; }); jm/=pares.length; }
  const expresa=clamp(0.4+jm/20,0.4,1);
  const bono=clamp((prom-55)/6,-4,6)*expresa;
  return {prom:prom,bono:bono,lazos:lazos,buenos:buenos,malos:malos,total:total,expresa:expresa};
}
/* 7.10 · árbitro con nombre (ficticio) y sesgo visible. Determinista por fixture
   para que la previa y el partido muestren el mismo. NUNCA usa nombres de árbitros reales. */
var ARB_ESTILOS=[
  {k:"parejo",      d:"la lleva pareja, cobra lo justo",   cartas:1.0,  casero:0},
  {k:"casero",      d:"fama de cobrar para el local",       cartas:1.0,  casero:1},
  {k:"tarjetero",   d:"saca tarjeta por cualquier cosa",    cartas:1.5,  casero:0},
  {k:"estricto",    d:"riguroso, no deja pasar una",        cartas:1.25, casero:0},
  {k:"deja jugar",  d:"guarda las tarjetas, deja jugar",    cartas:0.7,  casero:0}
];
function arbitroDe(part){
  const key="arb"+((part&&part.fecha)||"x")+((part&&(part.rivalId||part.rivalNombre))||"")+((typeof E!=="undefined"&&E&&E.anio)||"");
  const rr=azarFijo(semilla(key));
  const pila=NOMBRES_PILA[Math.floor(rr()*NOMBRES_PILA.length)];
  const ape=APELLIDOS[Math.floor(rr()*APELLIDOS.length)];
  const est=ARB_ESTILOS[Math.floor(rr()*ARB_ESTILOS.length)];
  return {n:pila+" "+ape, estilo:est.k, desc:est.d, cartas:est.cartas, casero:est.casero};
}
function tieneRasgo(j,r){ return !!(j&&j.rasgos&&j.rasgos.indexOf(r)>=0); }
function contarRasgo(once,r){ return (once||[]).filter(j=>tieneRasgo(j,r)).length; }
function aplicarBonoRasgos(P){
  const once=P.once||[];
  const vel=contarRasgo(once,"velocidad");
  const aer=contarRasgo(once,"juego aéreo");
  const gol=contarRasgo(once,"goleador");
  const con=contarRasgo(once,"contención");
  if(vel){ P.ataque+=Math.min(3.2,vel*0.9); P.empuje+=Math.min(1.8,vel*0.45); }
  if(gol){ P.ataque+=Math.min(2.8,gol*1.05); }
  if(con){ P.orden+=Math.min(3.4,con*1.05); P.rival=Math.max(0,(P.rival||0)-Math.min(1.8,con*0.5)); }
  if(aer){ P.ataque+=Math.min(1.6,aer*0.4); P.orden+=Math.min(1.4,aer*0.35); }
  P.rasgoBono={vel:vel,aereo:aer,gol:gol,cont:con};
}
var MOTOR_AJUSTE={c:5,s:0.5}; /* medido con devCalibrarMotor: brecha ≈ 0 en CC, UCH, AUD, LIM */
function iniciarPartido(part,modo){
  const once=onceIdeal();
  const lista=listaIdeal(once);
  const fz=fuerzaEquipo(once);
  const qui=quimicaEquipo(once);   /* 6.30 · la química suma nivel real */
  let bonoLocal=part.local?4.5+modSuma("local"):-2;
  let bonoTorneo=part.tipo==="copa"?modSuma("copa"):modSuma("liga");
  const arb=modSuma("arbitraje");
  let rivalBase=part.fuerzaRival+(part.local?0:3);
  /* 7.9029 · el motor en vivo amplificaba la diferencia de fuerza respecto del
     modelo con que la IA juega entre sí (medido con devCalibrarMotor): el club
     del jugador sacaba hasta +0,7 pts por partido de más. Se corrige en la
     entrada, no en la lógica del partido. Solo partidas nuevas (escala v2). */
  if(typeof E!=="undefined"&&E&&E._fuerzaV===2&&typeof MOTOR_AJUSTE!=="undefined"&&MOTOR_AJUSTE){
    const mioEff=(fz.ataque+fz.orden)/2;
    rivalBase+=MOTOR_AJUSTE.c+(mioEff-rivalBase)*MOTOR_AJUSTE.s;
  }
  const cl=(typeof CLIMAS!=="undefined"&&CLIMAS[part.clima])||{desgaste:0,precision:1};
  const pr=PRESIONES[E.tactica.presion]||PRESIONES["Media"];
  const me=MENTALIDADES[E.tactica.mentalidad]||MENTALIDADES["Equilibrado"];
  const bl=(typeof BLOQUES!=="undefined"&&BLOQUES[E.tactica.bloque])||{recup:0,expo:0};
  const P={
    part:part, modo:modo||"simular", min:0, gl:0, gv:0, once:once, lista:lista, rivalPlantel:plantelRival(part.rivalId||part.rivalNombre,part.fuerzaRival),
    ataque:fz.ataque+bonoLocal+bonoTorneo+arb, orden:fz.orden+bonoLocal*0.6+bonoTorneo+arb,
    desgaste:fz.desgaste+(cl.desgaste||0), cansancio:0, rival:rivalBase, empuje:0, riesgoPlan:0,
    recup:(pr.recup||0)+(me.recup||0)+(bl.recup||0), expo:(pr.expo||0)+(me.expo||0)+(bl.expo||0),
    precClima:cl.precision||1, arb:arb,
    lineas:[], goleadores:[], tarjetas:[], lesionados:[], ticker:[], terminado:false,
    momentos:momentosPartido(part), momentoIdx:0, fase:"equilibrio",
    clasico:esClasico(part), var:((E&&E.anio)||0)>=2016,
    iner:{cor:0,ataj:0,falta:0}, _varHold:false, _skipVar:false,
    prorroga:0, tanda:null,
    cambios:0, cambiosMax:cambiosMaxEra((E&&E.anio)||2026),
    ventanas:0, ventanasMax:ventanasMaxEra((E&&E.anio)||2026),
    descuento2:0, _descDicho:false, _htDicho:false, _salieron:[]
  };
  P.once.forEach(j=>{ j.estado="once"; });
  lista.forEach(j=>{ if(P.once.indexOf(j)<0) j.estado="banca"; });
  const namesLista=lista.map(j=>j&&j.n);
  P.cortados=dispPlantel().filter(j=>namesLista.indexOf(j.n)<0);
  P.cortados.forEach(j=>{
    if((j.nivel||0)>=74 || (j.rasgos&&(j.rasgos.indexOf("ídolo")>=0||j.rasgos.indexOf("capitán")>=0))){
      j.moral=clamp((j.moral||70)-3,0,100);
    }
    j.estado="corte";
  });
  P.stats={pos:0.5, remMio:0, remRiv:0, arcMio:0, arcRiv:0, corMio:0, corRiv:0};   /* 7.10 · stats de transmisión */
  P.arbitro=arbitroDe(part);   /* 7.10 · árbitro con sesgo visible */
  P._planSnap=snapshotPlan(P.once);
  P._ajustes=0;
  if(P.arbitro.casero){ if(part.local){ P.ataque+=2.5; P.orden+=1.5; } else { P.rival+=2.5; } }
  P.quimica=qui; P.empuje+=qui.bono; P.orden+=qui.bono*0.5;   /* 6.30 · química al ruedo */
  if(typeof aplicarBonoRasgos==="function") aplicarBonoRasgos(P);
  /* 6.33 · el clima de prensa (lo que dejaste en la conferencia) empuja o pesa */
  if(E.grupos && E.grupos.prensa){ P.empuje+=clamp(E.grupos.prensa.aprob/90,-0.7,0.7); }
  if(P.clasico){ P.empuje+=1.4; P.desgaste+=1.2; P.rival+=1.5;
    const casa=P.once.filter(j=>j.rasgos&&j.rasgos.indexOf("de la casa")>=0).length;   /* 6.20 · los de la casa se agrandan en el clásico */
    if(casa) P.empuje+=Math.min(4,casa*2);
    /* 6.21 · barra contenta (3 pactos) = caldera de local, pero más riesgo de incidente */
    if(part.local && typeof barraContenta==="function" && barraContenta()){ P.empuje+=2; aplicarEfectos({riesgo:4}); }
  }
  /* 6.21 · pacto roto: la barra silba y el equipo lo siente los primeros minutos */
  if(part.local && E.barra && E.barra.roto){ P.empuje-=1.5; P.barraSilba=true; }
  if(part.tipo==="copa"){ P.empuje+=0.8; P.desgaste+=0.6; }
  /* 7 · Modo Dios: forzar ganar el próximo (se consume; se garantiza en terminarPartido) */
  if(E.flags && E.flags.diosGana){ P.ataque+=40; P.empuje+=20; P.orden+=20; P.rival=Math.max(0,P.rival-30); P.diosForzar=true; E.flags.diosGana=false; }
  /* 7.9121 · Modo Dios / dev: "ganar todo" o "perder todo" hasta que se apague (para probar títulos, copas y descensos) */
  if(E.flags && E.flags.diosTodo==="ganar"){ P.ataque+=40; P.empuje+=20; P.orden+=20; P.rival=Math.max(0,P.rival-30); P.diosForzar=true; }
  else if(E.flags && E.flags.diosTodo==="perder"){ P.ataque=Math.max(0,P.ataque-40); P.rival+=30; P.diosPerder=true; }
  return P;
}
/* 6.18 / 7.999 · banca = concentrados que no están en el once. El que sale no reingresa (IFAB). */
function bancaPartido(P){
  const used=P._salieron||[];
  const disp=E.plantel.filter(j=>!j.vendido&&!j.cedido&&!(j.lesion>0)&&P.once.indexOf(j)<0&&used.indexOf(j)<0);
  if(P.lista&&P.lista.length){
    const names=P.lista.map(x=>x&&x.n);
    return disp.filter(j=>P.lista.indexOf(j)>=0 || names.indexOf(j.n)>=0);
  }
  return disp;
}
/* 6.18 · cambio manual con nombre: sale X, entra Y. El relato deja de citar a X (sale del once) */
function hacerCambio(P,sale,entra){
  if(!sale||!entra) return false;
  if((P.cambios||0)>=(P.cambiosMax||3)) return false;
  if(P.once.indexOf(sale)<0 || P.once.indexOf(entra)>=0) return false;
  const banca=bancaPartido(P);
  if(banca.indexOf(entra)<0) return false;
  const maxV=P.ventanasMax||99;
  const enHT=P.min>=45&&P.min<=47;
  if(maxV<99 && !enHT && !P._ventanaAbierta && (P.ventanas||0)>=maxV) return false;
  P.once=P.once.map(x=>x===sale?entra:x);
  entra.estado="once"; sale.estado="banca";
  P._salieron=P._salieron||[]; P._salieron.push(sale);
  sale.minutosTemporada=(sale.minutosTemporada||0)+(P.min-(sale.minEntrada||0));
  entra.minEntrada=P.min;
  entra.cansancio=Math.max(0,(entra.cansancio||0)-3);
  P.cambios=(P.cambios||0)+1;
  if(maxV<99 && !enHT && !P._ventanaAbierta){ P.ventanas=(P.ventanas||0)+1; P._ventanaAbierta=true; }
  linea(P,P.min,entra.n+" entra por "+sale.n+".","cambio");
  return true;
}
function recambioPorLesion(P,sale){
  const banca=bancaPartido(P).slice();
  const entra=banca.filter(j=>j.pos===sale.pos)[0]||banca.sort((a,b)=>(b.nivel||0)-(a.nivel||0))[0];
  if(!entra) return null;
  P.once=P.once.map(x=>x===sale?entra:x);
  entra.forma=clamp((entra.forma||70)-8,20,99);
  entra.cansancio=Math.max(entra.cansancio||0,5);
  sale.moral=clamp((sale.moral||70)-4,0,100);
  sale.estado="banca"; entra.estado="once";
  P._salieron=P._salieron||[]; P._salieron.push(sale);
  if((P.cambios||0)<(P.cambiosMax||3)) P.cambios=(P.cambios||0)+1;
  linea(P,P.min,entra.n+" entra frío por "+sale.n+". El cambio cuesta.","grave");
  return entra;
}
function actualizarFase(P){
  const [yo,el]=typeof miMarcador==="function"?miMarcador(P):[P.gl,P.gv];
  const pl=peligro(P);
  const prev=P.fase||"equilibrio";
  let fase="equilibrio";
  if(pl.yo>pl.el*1.18 && yo>=el) fase="dominio";
  else if(pl.el>pl.yo*1.18 || yo<el) fase="ahogo";
  P.fase=fase;
  if(fase!==prev && P.min>8){
    if(fase==="dominio") linea(P,P.min,E.clubNombre+" se come el partido. El rival no sale.");
    else if(fase==="ahogo") linea(P,P.min,"El partido se va para el otro lado. Hay que aguantar.","grave");
    else linea(P,P.min,"Se equilibra. Nadie tiene el control.");
  }
}
/* ---------- penales y polémica arbitral ---------- */
function arqueroDe(lista){ return (lista&&(lista.find(j=>j.pos==="ARQ")||lista[0]))||null; }
function pateadorDe(once){
  const c=once.filter(j=>j.pos!=="ARQ");
  const puntaje=j=>(j.nivel||60)+((j.rasgos&&j.rasgos.includes("penales"))?30:0)+((j.rasgos&&j.rasgos.includes("definición"))?12:0);
  return c.slice().sort((a,b)=>puntaje(b)-puntaje(a))[0]||once[0];
}
/* ~78% base, corregido por nivel del pateador vs temple (nivel) del arquero */
function cobrarPenal(pateador,arquero){
  let p=0.78;
  if(pateador) p+=((pateador.nivel||70)-70)*0.006+((pateador.rasgos&&pateador.rasgos.includes("penales"))?0.06:0)
    +((pateador.rasgos&&pateador.rasgos.indexOf("frio de definicion")>=0)?0.15:0);   /* 6.20 · frío en jugada, letal de penal */
  if(arquero)  p-=((arquero.nivel||70)-70)*0.005;
  return Math.random()<clamp(p,0.55,0.94);
}
/* forzado: si viene definido, salta el RNG (lo decide el minijuego).
   true = gol · false = atajado · "afuera" = tiro desviado */
function penalEnPartido(P,aFavor,motivo,patElegido,forzado){
  const min=P.min;
  if(aFavor){
    const pat=patElegido||pateadorDe(P.once), arq=arqueroDe(P.rivalPlantel);
    linea(P,min,(motivo||"Penal para "+E.clubNombre+".")+" Toma la pelota "+pat.n+"…");
    const gol=(forzado===undefined)?cobrarPenal(pat,arq):(forzado===true);
    if(forzado==="afuera"){
      linea(P,min,"¡"+pat.n+" la manda a las nubes! El penal se fue afuera.","grave"); P.empuje-=0.4;
      P.penalErrado=true; vozPenalErrado(P,min);   /* 7.00 · tuit de voz + flag para logro */
    } else if(forzado==="palo"){
      linea(P,min,"¡"+pat.n+" la manda al palo! El penal se estrella en la madera.","grave"); P.empuje-=0.4;
      P.penalErrado=true; vozPenalErrado(P,min);
    } else if(gol){
      pat.goles++; P.goleadores.push(pat.n); regGol(P,min,pat.n,true,"penal"); if(P.part.local)P.gl++; else P.gv++;
      linea(P,min,"¡Gol de penal de "+pat.n+"! "+marcadorTxt(P),"gol");
      if(pat.pos==="ARQ" && typeof desbloquear==="function") desbloquear("arquero_penal");   /* 6.25 · logro */
    } else { linea(P,min,"¡Atajadón! "+(arq?arq.n:"el arquero")+" le contiene el penal a "+pat.n+".","grave"); P.empuje-=0.4;
      P.penalErrado=true; vozPenalErrado(P,min); }
  } else {
    const pat=elige(P.rivalPlantel.filter(x=>x.pos!=="ARQ"))||P.rivalPlantel[0], arq=arqueroDe(P.once);
    linea(P,min,(motivo||"Penal para "+P.part.rivalNombre+".")+" Va a patear "+pat.n+"…");
    if(cobrarPenal(pat,arq)){
      if(P.part.local)P.gv++; else P.gl++; regGol(P,min,pat.n,false,"penal");
      linea(P,min,"Gol de penal de "+P.part.rivalNombre+": "+pat.n+". "+marcadorTxt(P),"gol");
    } else { linea(P,min,"¡"+(arq?arq.n:"el arquero")+" le ataja el penal! El estadio explota.","gol"); P.empuje+=0.5; }
  }
}
/* 7.00 · emite un tuit de "penal errado" al ticker si la voz (data-voz.js) está cargada */
function vozPenalErrado(P,min){
  if(typeof tuitDeCtx!=="function"||typeof empujarTicker!=="function") return;
  const t=tuitDeCtx("penal_errado"); if(t) empujarTicker(P,t.quien,t.txt,"malo",min);
}
/* polémica en minutos calientes: penal dudoso o gol anulado, con sesgo según
   el modificador de arbitraje (pactos oscuros inclinan la balanza a tu favor). */
function polemicaArbitral(P){
  const sesgo=clamp(0.5+(P.arb||0)*0.04,0.15,0.85);
  const aFavor=Math.random()<sesgo;
  if(Math.random()<0.5){
    penalEnPartido(P,aFavor,aFavor?("Penal muy dudoso para "+E.clubNombre+". El rival protesta."):("Penal dudosísimo para "+P.part.rivalNombre+". La banca salta furiosa."));
    aplicarEfectos({moral:aFavor?1:-2});
  } else if(aFavor){
    linea(P,P.min,"Le anulan un gol al rival por un offside milimétrico. Se salva "+E.clubNombre+".","gol");
    aplicarEfectos({moral:1}); P.empuje+=0.3;
  } else {
    linea(P,P.min,"¡Gol anulado a "+E.clubNombre+"! El línea levantó la bandera y nadie entendió por qué.","grave");
    aplicarEfectos({moral:-2}); P.empuje-=0.3;
  }
}
function momentosPartido(part){
  /* 12 y 32 el primer tiempo. El 45 es el descanso (no un momento).
     Segundo tiempo a partir del 52: el 46 robaba la charla si el reloj saltaba. */
  const base=[12,32,52,64,76,84];
  if(part.ronda==="FINAL"||part.tipo==="copa") base.push(88);
  return base;
}
function recordarFrase(P,txt){
  if(!P) return;
  P._frasesRecientes=P._frasesRecientes||[];
  P._frasesRecientes.push(txt);
  if(P._frasesRecientes.length>14) P._frasesRecientes.shift();
}
function eligeNuevo(P,arr){
  if(!arr||!arr.length) return "";
  const rec=(P&&P._frasesRecientes)||[];
  const fresh=arr.filter(x=>x&&rec.indexOf(x)<0);
  const pick=elige(fresh.length?fresh:arr);
  recordarFrase(P,pick);
  return pick;
}
function linea(P,min,txt,clase){
  if(!P||!txt) return;
  P.lineas=P.lineas||[];
  const last=P.lineas.length?P.lineas[P.lineas.length-1].t:"";
  if(last===txt) return;
  P.lineas.push({m:min,t:txt,c:clase||""});
  recordarFrase(P,txt);
}
/* registra un gol con minuto y autor, para la caja de resumen (efemérides) */
function regGol(P,min,quien,propio,tipo,asist){ P.golesDetalle=P.golesDetalle||[]; P.golesDetalle.push({min:min,quien:quien,propio:!!propio,tipo:tipo||"jugada",asist:asist||null}); }
function anotaPropio(P,min){
  const cand=P.once.filter(j=>j.pos==="DEL").concat(P.once.filter(j=>j.pos==="VOL"))
    .concat(P.once.filter(j=>j.pos==="DEF"&&tieneRasgo(j,"juego aéreo")));
  const j=eligePeso(cand,x=>(x.pos==="DEL"?3:(x.pos==="DEF"?0.7:1))*(x.nivel/50)
    *(tieneRasgo(x,"llegador")?1.8:1)
    *(tieneRasgo(x,"frio de definicion")?0.75:1)
    *(tieneRasgo(x,"goleador")?1.7:1)
    *(tieneRasgo(x,"velocidad")?1.25:1)
    *(tieneRasgo(x,"juego aéreo")?1.35:1)
  )||elige(P.once);
  let asist=null;
  if(Math.random()<0.6){ const otros=P.once.filter(x=>x!==j&&x.pos!=="ARQ"); const a=eligePeso(otros,x=>(x.pos==="VOL"?2:1)*(tieneRasgo(x,"llegador")?1.7:1)*(tieneRasgo(x,"velocidad")?1.2:1))||elige(otros); asist=a?a.n:null; }
  const deCabeza=tieneRasgo(j,"juego aéreo")?(Math.random()<0.42):(j.pos==="DEF"?Math.random()<0.55:Math.random()<0.08);
  const tipo=deCabeza?"cabeza":"jugada";
  j.goles++; P.goleadores.push(j.n); regGol(P,min,j.n,true,tipo,asist);
  if(deCabeza && j.pos==="DEF" && typeof desbloquear==="function") desbloquear("gol_defensa");
  if(deCabeza && typeof desbloquear==="function") desbloquear("cabeza_de_area");
  if(P.part.local) P.gl++; else P.gv++;
  linea(P,min,"¡Gol"+(deCabeza?" de cabeza":"")+" de "+j.n+"!"+(asist?" (asistencia de "+asist+")":"")+" "+marcadorTxt(P),"gol");
}
function anotaRival(P,min){
  const j=elige(P.rivalPlantel.filter(x=>x.pos!=="ARQ"));
  if(P.part.local) P.gv++; else P.gl++;
  regGol(P,min,j.n,false,"jugada",null);
  linea(P,min,"Gol de "+P.part.rivalNombre+": "+j.n+". "+marcadorTxt(P),"gol");
  const m=miMarcador(P); if(m[1]-m[0]>=2) P.abajo2=true;   /* 6.25 · para el logro de remontada */
}
/* 7.9108 · como en la tele y en el marcador de arriba: el LOCAL primero (antes tu club iba primero aunque jugaras de
   visita, y el relato decía "Colo-Colo 0 - 2 Limache" con el marcador en "Limache 2 - 0 Colo-Colo") */
function marcadorTxt(P){
  const loc=P.part.local?E.clubNombre:P.part.rivalNombre, vis=P.part.local?P.part.rivalNombre:E.clubNombre;
  return "("+loc+" "+(P.gl|0)+" - "+(P.gv|0)+" "+vis+")";
}
function miMarcador(P){ return P.part.local?[P.gl,P.gv]:[P.gv,P.gl]; }
function diffMarcador(P){ const m=miMarcador(P); return (m[0]||0)-(m[1]||0); }
/* 7.99954 · el plan pesa MÁS cuando vas perdiendo: atacar abre, defender se cierra. */
function planCuandoVasPerdiendo(P){
  const ment=(E&&E.tactica&&E.tactica.mentalidad)||"";
  if(/Ultraofensivo/.test(ment)) return {yo:1.18, el:1.12, empuje:1.1};
  if(/Ofensivo/.test(ment)) return {yo:1.10, el:1.05, empuje:0.5};
  if(/Ultradefensivo/.test(ment)) return {yo:0.86, el:0.84, empuje:-0.2};
  if(/Defensivo/.test(ment)) return {yo:0.92, el:0.90, empuje:0};
  return {yo:1, el:1, empuje:0};
}
/* 5.0 · barras de apoyo en vivo: Ánimo Hinchada / Confianza Plantel / Criterio DT.
   Se recalculan cada minuto persiguiendo un objetivo según marcador, físico y decisiones. */
function actualizarApoyo(P){
  if(!P.apoyo){
    P.apoyo={
      hinchada:clamp(E.ind.hinchada||60,8,95),
      plantel: clamp(E.ind.moral||60,8,95),
      criterio:clamp(48+(((E.staff&&E.staff.deportivo)||60)-60)/2,20,82),
      momentos:0
    };
  }
  const a=P.apoyo, [yo,otro]=miMarcador(P), diff=yo-otro;
  const fatiga=clamp((P.cansancio||0)*6,0,60);
  const tarde=(P.min>75);
  const tHin=clamp((E.ind.hinchada||60) + diff*13 + (tarde&&diff<0?-8:0) + (tarde&&diff>0?5:0), 3,99);
  const tPla=clamp((E.ind.moral||60) + diff*11 - fatiga*0.4, 3,99);
  const tCri=clamp(48 + diff*7 + a.momentos*5 + (((E.staff&&E.staff.deportivo)||60)-60)/3, 3,99);
  a.hinchada+=(tHin-a.hinchada)*0.25;
  a.plantel +=(tPla-a.plantel )*0.25;
  a.criterio+=(tCri-a.criterio)*0.20;
}

/* 7.9042 · las tres barras ahora HACEN algo (antes eran adorno y nadie las entendía).
   Efecto chico y a la vista: cada barra dice en palabras qué está provocando. */
function efectoApoyo(P){
  const a=P&&P.apoyo, out={yo:1,el:1,txt:{}};
  if(!a) return out;
  const loc=!!(P.part&&P.part.local);
  if(a.hinchada>=70){ const k=loc?1.05:1.03; out.yo*=k; out.txt.hinchada="empuja: +"+Math.round((k-1)*100)+" % de llegadas"; }
  else if(a.hinchada<35){ out.yo*=0.97; out.txt.hinchada="impaciente: el equipo se apura (−3 % de llegadas)"; }
  else out.txt.hinchada="acompaña, sin mover la aguja";
  if(a.plantel>=70){ out.el*=0.96; out.txt.plantel="te creen: aguantan mejor atrás (−4 % de llegadas del rival)"; }
  else if(a.plantel<35){ out.el*=1.05; out.txt.plantel="dudan: se desarman atrás (+5 % de llegadas del rival)"; }
  else out.txt.plantel="neutral: ni suma ni resta";
  if(a.criterio>=65) out.txt.criterio="tus correcciones pegan más fuerte (+"+Math.round((pesoCriterio(P)-1)*100)+" %)";
  else if(a.criterio<35) out.txt.criterio="el equipo no entiende tus cambios (−"+Math.round((1-pesoCriterio(P))*100)+" % de efecto)";
  else out.txt.criterio="tus correcciones pesan lo normal";
  return out;
}
/* el criterio escala cuánto pesan las decisiones en vivo: 0,85× a 1,2× */
function pesoCriterio(P){
  const c=P&&P.apoyo?P.apoyo.criterio:50;
  return clamp(0.85+(c-35)*(0.35/40),0.85,1.2);
}
/* 7.9042 · botón de la barra: una vez por partido, canta más fuerte. */
function arengarBarra(P){
  if(!P||P._arengo||P.terminado) return false;
  P._arengo=true;
  if(typeof actualizarApoyo==="function" && !P.apoyo) actualizarApoyo(P);
  if(P.apoyo) P.apoyo.hinchada=clamp(P.apoyo.hinchada+18,0,99);
  P.empuje+=(P.part&&P.part.local)?0.8:0.4;
  if(typeof aplicarEfectos==="function") aplicarEfectos({hinchada:1});
  linea(P,P.min,(P.part&&P.part.local)
    ?"El DT se da vuelta y levanta los brazos: la barra revienta el estadio. Se canta más fuerte que nunca."
    :"El DT mira a los que viajaron y les pide más. El rincón visitante se hace escuchar.","gol");
  return true;
}
/* avanza el reloj hasta 'hasta' generando eventos.
   Modelo: se calcula cuánto peligro genera cada lado por partido
   (algo parecido a goles esperados) y se reparte minuto a minuto. */
/* 7.9042 · perillas del motor de goles. Objetivo (liga chilena real): ~2,6 goles por partido,
   25–28 % de empates, goleadas por 4+ raras (~3 %) pero posibles si el plan es malo y no se corrige.
   El doctor 'motor_goles' mide contra estos rangos. */
var MOTOR_GOL={ N:42, dom:36, aho:38, pend:0.38, corner:{base:0.035,iner:0.015,aereo:0.03,min:0.02,max:0.11} };
function peligro(P){
  const mio=P.ataque+P.empuje-P.cansancio*1.6;
  /* 7.9042 · el riesgo ya no resta del mismo lado que el ataque (se anulaban y "tirarse
     encima" no hacía nada): ahora ABRE el partido, más llegadas tuyas y bastantes más del rival. */
  const suyo=P.rival+P.riesgoPlan*0.5-(P.orden-P.rival)*0.16;
  const d=clamp((mio-suyo)/11,-2.1,2.1);
  /* la presión se aplica FUERA del clamp para que pese aun contra rivales
     saturados: recuperar arriba (se apaga con el cansancio) sube tu peligro;
     exponer la defensa (peor cansado) sube el del rival. */
  const recup=(P.recup||0)*Math.max(0,1-P.cansancio*0.09);
  const expo=(P.expo||0)*(0.3+P.cansancio*0.06);
  let yo=Math.max(0.20,1.30+d*MOTOR_GOL.pend+recup*0.06);
  let el=Math.max(0.20,1.30-d*MOTOR_GOL.pend+expo*0.06);
  /* 7.9042 · el orden pedido en vivo cierra de verdad: menos llegadas del rival (antes no bajaba nada). */
  const ci=P.cierre||0;
  if(ci){ el*=clamp(1-ci*0.05,0.55,1.25); }
  const ap=efectoApoyo(P); yo*=ap.yo; el*=ap.el;
  const rp=P.riesgoPlan||0;
  if(rp){ yo*=clamp(1+rp*0.02,0.9,1.2); el*=clamp(1+rp*0.07,0.85,1.6); }
  /* 7.99954 · si vas perdiendo, la pizarra se siente: atacar abre el partido. */
  if(diffMarcador(P)<0){
    const k=planCuandoVasPerdiendo(P);
    yo*=k.yo; el*=k.el;
  }
  /* 7.9042 · con 3 de ventaja el que gana afloja (se cuida, cambia, administra).
     Tu equipo solo sigue a fondo si el plan es ofensivo; el rival sigue haciéndote
     daño si dejaste el equipo expuesto (riesgo/exposición altos): la goleada existe,
     pero la fabrica un mal plan que no se corrigió. */
  const dm=diffMarcador(P);
  if(dm>=3){
    const ment=(E&&E.tactica&&E.tactica.mentalidad)||"";
    yo*=/Ofensivo/.test(ment)?0.9:0.68;
  } else if(dm<=-3){
    el*=clamp(0.62+Math.max(0,P.riesgoPlan||0)*0.05+Math.max(0,P.expo||0)*0.03,0.62,1);
  }
  /* 7.9003 · inercia: córners / atajadas / faltas seguidas empujan el próximo tiro. */
  const iner=inerciaTiro(P);
  yo*=iner.yo; el*=iner.el;
  if(P.prorroga){ yo*=0.88; el*=0.88; }
  return { yo:yo, el:el };
}
/* 7.9003 · VAR en vivo: zócalo + pausa dramática. No en simular, no antes de 2018,
   no cuando se salta al resultado (_skipVar). P.var (2016+) sigue sirviendo para polémica. */
function hayVarEnVivo(P){
  if(!P || !P.var || P._skipVar) return false;
  if(P.modo==="simular") return false;
  const anio=((typeof E!=="undefined"&&E&&E.anio)||0);
  return anio>=2018;
}
/* 7.9044 · quién mandó en cada tramo: (peligro propio − rival) / total, de −1 a 1.
   Se guarda uno por tick (~30 por partido) para el gráfico del final. */
function registrarDominio(P,pl){
  if(!P||!pl) return;
  P.dom=P.dom||[];
  const t=pl.yo+pl.el;
  P.dom.push({m:P.min, v:t>0?Math.round((pl.yo-pl.el)/t*100)/100:0, c:Math.round((P.cansancio||0)*10)/10});
}
/* lo que pasó en el tick mueve la aguja: un remate atajado o un córner es un tramo tuyo */
var DOM_EVENTO={gol:0.55,golRival:-0.55,chance:0.18,corner:0.2,penal:0.4,penalRival:-0.4,tiroLibre:0.15};
function marcarDominioEvento(P,ev){
  if(!P||!ev||!P.dom||!P.dom.length) return;
  const u=P.dom[P.dom.length-1]; if(u.m!==(ev.min!=null?ev.min:P.min)) return;
  let k=DOM_EVENTO[ev.tipo]||0;
  if(ev.tipo==="atajada") k=ev.aFavor?0.3:-0.3;
  if(ev.tipo==="corner" && ev.aFavor===false) k=-0.2;
  if(k) u.v=Math.round(clamp(u.v+k,-1,1)*100)/100;
}
function _promDom(arr){ return arr.length?arr.reduce((a,x)=>a+x.v,0)/arr.length:0; }
/* lectura del partido para el cierre: qué mejorar (no qué hiciste mal). Máximo 3. */
function consejosPartido(P){
  const d=(P&&P.dom)||[]; if(d.length<6) return [];
  const [yo,otro]=miMarcador(P);
  const ini=_promDom(d.filter(x=>x.m<=20)), medio=_promDom(d.filter(x=>x.m>45&&x.m<=70)), fin=_promDom(d.filter(x=>x.m>70));
  const total=_promDom(d), cans=(d[d.length-1]||{}).c||0;
  const out=[];
  if(ini<-0.15) out.push({ic:"🧱",t:"Para arrancar mejor",d:"Los primeros 20' fueron del rival. Prueba salir con más orden (bloque medio o «Empezar de menos a más») y suelta al equipo después del 15'."});
  if(fin<medio-0.18 && cans>=4) out.push({ic:"🔋",t:"Para cerrar mejor",d:"Del 70' en adelante el equipo se apagó (se nota el cansancio). Si metes los cambios antes del 65' o bajas el ritmo, el final se sostiene."});
  if(total>0.15 && yo<=otro) out.push({ic:"🎯",t:"Para convertir lo que generas",d:"Mandaste más de lo que dice el marcador. Más gente en el área (centros, doble nueve) o trabajar definición en la semana transforma ese dominio en goles."});
  if(total<-0.25) out.push({ic:"🛡",t:"Para competir este tipo de partido",d:"El rival generó más peligro que tú casi todo el partido. Contra equipos así rinde más un bloque bajo y salir de contra que ir de igual a igual."});
  if(Math.abs(total)<=0.12 && yo===otro) out.push({ic:"⚖",t:"Para desnivelar un partido parejo",d:"Fue muy parejo. En estos partidos la decisión del segundo tiempo pesa: un cambio ofensivo a tiempo o una pelota parada ensayada lo rompen."});
  if(P.modo==="dirigir" && !(P.apoyo&&P.apoyo.momentos)) out.push({ic:"🧠",t:"Para usar tu criterio",d:"No tomaste decisiones en vivo. Cada decisión sube tu Criterio DT y hace que tus correcciones pesen más."});
  if(!out.length) out.push({ic:"✅",t:"Para mantener",d:yo>otro?"El partido salió como se planeó: la idea funciona, conviene sostenerla.":"Hiciste un partido correcto; el detalle estuvo en las áreas."});
  return out.slice(0,3);
}
/* 7.9042 · el VAR NO revisa cada gol: solo las jugadas dudosas. El resto se grita en paz.
   Cuando revisa, la duda es real: anula más seguido (≈ 5 % de los goles en total). */
var VAR_REVISION={ gol:0.14, penal:0.35, anulaGol:0.38, anulaPenal:0.30 };
function varRevisa(P,kind){
  if(!hayVarEnVivo(P)) return false;
  const esPenal=kind==="penal"||kind==="penalRival";
  return Math.random()<(esPenal?VAR_REVISION.penal:VAR_REVISION.gol);
}
/* 7.9003 · racha de córners / atajadas / faltas. Tope 3. Reset al gol. */
function inerciaTiro(P){
  const i=(P&&P.iner)||{};
  const cor=Math.min(3,i.cor||0), ataj=Math.min(3,i.ataj||0), falta=Math.min(3,i.falta||0);
  return { yo:1+cor*0.08+ataj*0.05, el:1+(falta>=2?0.03:0), remate:1+cor*0.12+ataj*0.08 };
}
function resetInercia(P){
  if(!P) return;
  P.iner={cor:0,ataj:0,falta:0};
}
function actualizarInercia(P,ev){
  if(!P||!ev) return;
  marcarDominioEvento(P,ev);   /* 7.9044 */
  P.iner=P.iner||{cor:0,ataj:0,falta:0};
  const i=P.iner;
  const min=ev.min||P.min||0;
  switch(ev.tipo){
    case "gol":
    case "golRival":
      resetInercia(P);
      break;
    case "corner":
      if(ev.aFavor!==false){
        i.cor=Math.min(3,(i.cor||0)+1);
        if(ev.deAtajada) i.ataj=Math.min(3,(i.ataj||0)+1);
        if((i.cor===2||i.cor===3) && typeof linea==="function"){
          linea(P,min,"Asedio: van "+i.cor+" córners seguidos. El área rival no respira.","grave");
        }
      } else {
        i.cor=0;
      }
      break;
    case "atajada":
      if(ev.aFavor){
        i.ataj=Math.min(3,(i.ataj||0)+1);
        if((i.ataj===2||i.ataj===3) && typeof linea==="function"){
          linea(P,min,"El arquero rival vuela de nuevo. "+i.ataj+" atajadas seguidas: algo tiene que caer.","grave");
        }
      } else {
        i.ataj=0;
      }
      break;
    case "tarjeta":
    case "roja":
      i.falta=Math.min(3,(i.falta||0)+1);
      if((i.falta===2||i.falta===3) && typeof linea==="function"){
        linea(P,min,"Faltas seguidas. El árbitro ya no perdona y el rival huele sangre.","");
      }
      break;
    default: break;
  }
}
/* Un tick avanza el reloj un poco y devuelve UN evento. Los eventos simples
   (gol, chance, tarjeta, color) se aplican acá; los de acción (penal, tiro
   libre, lesión) se devuelven SIN resolver para que el modo dirigir pueda
   auto-pausar y pedir una decisión. En simular se resuelven en automático. */
function tickPartido(P){
  if(P.terminado) return {tipo:"fin",min:P.min};
  if(P.tanda) return {tipo:P.tanda.done?"tandaFin":"tanda",min:P.min};
  const tope=topePartido(P);
  if(P._descDicho && P.min>=tope){
    return (typeof intentarDesempate==="function")?intentarDesempate(P):{tipo:"fin",min:P.min};
  }
  const paso=P.min>=90?ri(1,2):ri(2,4);
  const next=P.min+paso;
  /* 7.99955 · descanso clavado al 45' (igual que el 90' de descuento).
     El salto de 2–4 min se comía la ventana min>=45 && min<48 (44+4=48). */
  if(!P._htDicho && !P._descDicho && next>=45 && P.min<45){
    P.min=45;
    P._htDicho=true;
    linea(P,45,"Descanso. Van "+marcadorTxt(P)+". Quince minutos para hablar.","grave");
    return {tipo:"entretiempo",min:45};
  }
  if(!P._descDicho && next>=90){
    P.min=90;
    P.descuento2=calcularDescuento(P);
    P._descDicho=true;
    linea(P,90,"El cuarto árbitro marca "+P.descuento2+" minuto"+(P.descuento2===1?"":"s")+".","grave");
    return {tipo:"nada",min:90};
  }
  P.min=P._descDicho?Math.min(tope,next):Math.min(90,next);
  P.cansancio+=P.desgaste*0.011*paso;
  (P.once||[]).forEach(j=>{ j.cansancio=clamp((j.cansancio||0)+P.desgaste*0.009*paso,0,30); });
  const min=P.min;
  /* 7.99954 · vas perdiendo: la tribuna y el capitán hablan. El plan ofensivo empuja. */
  if(diffMarcador(P)<0 && min>=55 && !P._tensionDicha){
    P._tensionDicha=true;
    const cap=(P.once||[]).find(function(j){ return tieneRasgo(j,"capitán"); })||(P.once||[])[0];
    const ment=(E&&E.tactica&&E.tactica.mentalidad)||"";
    const k=planCuandoVasPerdiendo(P);
    P.empuje+=(k.empuje||0);
    if(/Ultraofensivo|Ofensivo/.test(ment)){
      linea(P,min,(cap&&cap.n?cap.n+" arrastra a los de adelante. ":"")+"Van perdiendo "+marcadorTxt(P)+". Pediste ir a buscarlo: se abre el partido.","grave");
    } else if(/Defensivo|Ultradefensivo/.test(ment)){
      linea(P,min,"Vas perdiendo "+marcadorTxt(P)+". El plan es no abrir: la tribuna no entiende, el banco espera un cambio.","grave");
    } else {
      linea(P,min,(cap&&cap.n?cap.n+" junta al círculo. ":"")+"Vas perdiendo "+marcadorTxt(P)+". Hay que decidir: ir a buscarlo o aguantar.","grave");
    }
    return {tipo:"tension",min:min};
  }
  /* 6.21 · silbidos de la barra por un pacto roto */
  if(P.barraSilba && min>=15 && !P.silbidoDicho){ P.silbidoDicho=true;
    linea(P,min,"Silbidos desde la tribuna: la barra no le perdona el pacto roto a la dirigencia.","grave");
    return {tipo:"nada",min:min}; }
  const pl=peligro(P);
  if(P.precClima&&P.precClima!==1){ pl.yo*=P.precClima; pl.el*=P.precClima; }
  actualizarFase(P);
  /* 7.9042 · divisores recalibrados (antes 28/23/25 → ~4 goles por partido). */
  let N=MOTOR_GOL.N;
  if(P.fase==="dominio"){ N=MOTOR_GOL.dom; pl.yo*=1.08; }
  if(P.fase==="ahogo"){ N=MOTOR_GOL.aho; pl.el*=1.08; }
  registrarDominio(P,pl);
  const r=Math.random();
  if(r<pl.yo/N){
    if(varRevisa(P,"gol")) return {tipo:"varCheck",kind:"gol",min:min};
    anotaPropio(P,min); return {tipo:"gol",min:min};
  }
  if(r<(pl.yo+pl.el)/N){
    if(varRevisa(P,"golRival")) return {tipo:"varCheck",kind:"golRival",min:min};
    anotaRival(P,min); return {tipo:"golRival",min:min};
  }
  /* acción: penal */
  if(Math.random()<0.006){ const aFavor=Math.random()<clamp(0.5+(P.ataque-P.rival)*0.004,0.2,0.8);
    P._penalCancha=aFavor?1:-1;
    P._penalSeq=(P._penalSeq||0)+1;
    if(varRevisa(P,aFavor?"penal":"penalRival")) return {tipo:"varCheck",kind:aFavor?"penal":"penalRival",min:min,aFavor:aFavor};
    return {tipo:aFavor?"penal":"penalRival",min:min,aFavor:aFavor}; }
  /* acción: lesión */
  if(min>20&&Math.random()<(P.sinLesiones?0.0006:0.006*(P.lesionClima||1))){   /* 7.9065 · frío/calor: más lesiones musculares */ return {tipo:"lesion",min:min}; }   /* 7.9061 · pretemporada: casi sin lesiones */
  /* acción: tiro libre peligroso propio */
  if(Math.random()<0.010){ return {tipo:"tiroLibre",min:min}; }
  /* autogol (raro), en cualquiera de los dos arcos */
  if(Math.random()<0.004){
    if(Math.random()<0.5){ /* el rival se la mete solo → gol propio */
      const rd=elige(P.rivalPlantel.filter(x=>x.pos!=="ARQ"))||{n:"un defensor rival"};
      if(P.part.local)P.gl++; else P.gv++; regGol(P,min,rd.n,true,"autogol",null);
      linea(P,min,"¡AUTOGOL de "+rd.n+" ("+P.part.rivalNombre+")! Regalo insólito. "+marcadorTxt(P),"gol");
      return {tipo:"gol",min:min};
    } else { /* uno tuyo la manda a tu propia red → gol rival */
      const md=elige(P.once.filter(x=>x.pos==="DEF"))||elige(P.once)||{n:"un defensor"};
      if(P.part.local)P.gv++; else P.gl++; regGol(P,min,md.n,false,"autogol",null);
      linea(P,min,"Autogol de "+md.n+"… se la mandó a su propio arco. "+marcadorTxt(P),"grave");
      return {tipo:"golRival",min:min};
    }
  }
  /* polémica en el tramo caliente */
  const pPol=(P.clasico||P.var)?0.018:0.012;
  if(min>60&&Math.random()<pPol){ polemicaArbitral(P); return {tipo:"polemica",min:min}; }
  /* tarjeta · 6.20 · "cabeza caliente": post-60' arriesga más (mitad si viene ganando); 2ª amarilla = roja */
  if(Math.random()<0.03*((P.arbitro&&P.arbitro.cartas)||1)){
    const ganando=(P.part.local?P.gl>P.gv:P.gv>P.gl);
    const calientes=P.once.filter(x=>x.rasgos&&x.rasgos.indexOf("cabeza caliente")>=0);
    let j;
    if(min>60 && calientes.length && Math.random()<(ganando?0.06:0.12)+0.4) j=elige(calientes);
    else j=elige(P.once);
    const caliente=j.rasgos&&j.rasgos.indexOf("cabeza caliente")>=0;
    P.amar=P.amar||{}; P.amar[j.n]=(P.amar[j.n]||0)+1; j.tarjetas++; P.tarjetas.push(j.n);
    if(caliente && P.amar[j.n]>=2 && Math.random()<0.25){
      P.once=P.once.filter(x=>x!==j); j.estado="banca"; P.empuje-=1; P.orden-=3; P.tuvoRoja=true;   /* 6.25 · logro roja+gana */
      linea(P,min,"¡ROJA para "+j.n+"! Segunda amarilla: se le calentó la cabeza y deja a los suyos con diez.","grave");
      return {tipo:"roja",min:min};
    }
    linea(P,min,min>75?("Amarilla para "+j.n+". En este tramo duele más.")
      :("Amarilla para "+j.n+(caliente?", que juega siempre al límite.":".")),min>70?"grave":"");
    return {tipo:"tarjeta",min:min}; }
  /* 7.77 · MÁS PATEOS: remates al arco y atajadas. 7.9003 · la inercia sube la chance. */
  const iner=inerciaTiro(P);
  if(Math.random()<0.075*iner.remate){
    const j=elige(P.once.filter(x=>x.pos!=="ARQ"))||{n:"tu delantero"};
    const remates=[
      "¡"+j.n+" saca el zurdazo y el arquero de "+P.part.rivalNombre+" manotea al córner! Estuvo cerquísima.",
      "Remató "+j.n+" de primera y tapó el golero. ¡Qué atajada!",
      "Cabezazo de "+j.n+" y el arquero rival vuela a sacarla del ángulo. ¡Uf!",
      j.n+" probó de lejos y obligó a la palomita. Sigue el asedio."
    ];
    const frase=elige(remates);
    if(Math.random()<0.45){
      linea(P,min,frase+" Córner.");
      return {tipo:"corner",min:min,aFavor:true,deAtajada:true};
    }
    linea(P,min,frase);
    return {tipo:"atajada",min:min,aFavor:true};
  }
  if(Math.random()<0.055){
    linea(P,min,"Remate peligroso de "+P.part.rivalNombre+"… ¡y tu arquero la saca de un manotazo! La tribuna lo ovaciona.");
    return {tipo:"atajada",min:min,aFavor:false};
  }
  /* 7.9003 · córner de asedio (sin atajada previa). */
  if(Math.random()<0.04*iner.remate){
    linea(P,min,"Córner para "+((typeof E!=="undefined"&&E&&E.clubNombre)||"nosotros")+".");
    return {tipo:"corner",min:min,aFavor:true};
  }
  /* chance perdida — con contexto de marcador y minuto (más seguido: más pateos) */
  if(Math.random()<0.20){
    linea(P,min,fraseChance(P,min));
    return {tipo:"chance",min:min};
  }
  /* color / relato — más denso, menos “nada” */
  if(Math.random()<0.20){
    linea(P,min,fraseRelato(P,min));
    return {tipo:"relato",min:min};
  }
  return {tipo:"nada",min:min};
}
/* 7.10 · estadísticas en vivo (posesión, remates, al arco, córners).
   Se llama después de cada tick con el evento devuelto. */
function actualizarStats(P,ev){
  if(!P.stats) P.stats={pos:0.5,remMio:0,remRiv:0,arcMio:0,arcRiv:0,corMio:0,corRiv:0};
  if(typeof actualizarInercia==="function") actualizarInercia(P,ev);
  const s=P.stats;
  const posT=clamp(0.5+((P.ataque||0)-(P.rival||0))*0.006+(P.fase==="dominio"?0.12:(P.fase==="ahogo"?-0.12:0))+(P.empuje||0)*0.008,0.22,0.78);
  s.pos+=(posT-s.pos)*0.08;
  if(ev) switch(ev.tipo){
    case "gol": s.remMio++; s.arcMio++; break;
    case "golRival": s.remRiv++; s.arcRiv++; break;
    case "penal": case "tiroLibre": s.remMio++; s.arcMio++; break;
    case "penalRival": s.remRiv++; s.arcRiv++; break;
    case "chance": s.remMio++; if(Math.random()<0.5) s.arcMio++; if(Math.random()<0.35) s.corMio++; break;
    case "atajada": if(ev.aFavor){ s.remMio++; s.arcMio++; if(Math.random()<0.4) s.corMio++; } else { s.remRiv++; s.arcRiv++; } break;   /* 7.77 */
    case "corner": if(ev.aFavor!==false){ s.corMio++; if(ev.deAtajada){ s.remMio++; s.arcMio++; } } else s.corRiv++; break;
    case "polemica": if(Math.random()<0.5) s.remMio++; break;
  }
  if(Math.random()<0.014) s.corRiv++;
  if(Math.random()<0.010) s.remRiv++;
}
/* frases de chance según marcador y tramo */
function fraseChance(P,min){
  const [yo,otro]=miMarcador(P);
  const dif=yo-otro;
  const riv=P.part.rivalNombre||"el rival";
  if(dif<0&&min>60) return elige([
    "Ocasión clara y se va afuera. El empate estaba ahí.",
    "El arquero rival saca un milagro. La tribuna se agarra la cabeza.",
    "Se pierde una mano a mano. El partido se está yendo.",
    riv+" se salva en la línea. Parecía el  gol del empate."
  ]);
  if(dif>0&&min>70) return elige([
    "Casi el segundo que lo liquida. Se fue rozando el palo.",
    "Contraataque limpio y el delantero la manda afuera. Sigue vivo el rival.",
    "El arquero rival vuela otra vez. Todavía no está cerrado."
  ]);
  return elige([
    "Tiro de media distancia que se va apenas afuera.",
    "El arquero rival manda al córner una que iba adentro.",
    "Se pierde una clarísima en el área chica.",
    riv+" avisa con un cabezazo que pasa cerca.",
    "Se salva en la línea. El estadio se agarra la cabeza.",
    "Centro peligroso y nadie llega al remate. Se pierde la chance."
  ]);
}
/* color del partido según cansancio, minuto y clima */
/* color del partido según cansancio, minuto, clima, rasgos y época */
function fraseRelato(P,min){
  const cans=P.cansancio||0;
  const riv=P.part.rivalNombre||"el rival";
  const once=P.once||[];
  const j=elige(once.filter(x=>x&&x.n))||elige(once)||{};
  const nom=j.n;
  const ras=(j.rasgos&&j.rasgos[0])||"";
  const modo=(E&&E.modo)||"historico";
  const era=E&&E.eraBase;
  const pool=[];
  const dif=diffMarcador(P);
  if(dif<0){
    pool.push("Vas perdiendo. Cada pelota atrás se discute en la tribuna.");
    pool.push("El marcador duele. El banco mira el reloj y el plan.");
    if(min>60) pool.push("La hinchada pide cambios. El partido se está yendo.");
    if(/Ultraofensivo|Ofensivo/.test((E.tactica&&E.tactica.mentalidad)||""))
      pool.push("Pediste ir a buscarlo: hay espacios atrás y espacios adelante.");
  }
  if(P.clasico){
    pool.push("Clásico. La platea no perdona un error.");
    pool.push("Cada falta se discute como si fuera la final.");
    pool.push("Esto no es un partido. Es un ajuste de cuentas de barrio.");
    if(nom) pool.push(nom+" se crece. En el clásico los mediocres no existen.");
  }
  if(era===1925) pool.push("No hay cámaras. El grito de la tribuna de madera es todo el relato.");
  if(era===1991 && min<25) pool.push("Sin VAR. El juez manda y punto. La tribuna discute igual.");
  if(era===2006 && min<20) pool.push("Televisión nacional, 3 puntos, y el año se juega en dos torneos.");
  if(modo==="caos") pool.push("Pasa algo raro en la banda. Nadie entiende.","El partido se desordena de un saque.");
  if(nom&&min>12){
    pool.push(nom+" pide la pelota y no se la dan.");
    pool.push(nom+" recupera y la juega simple.");
    if(cans>5) pool.push(nom+" se queda corto. El físico ya pesa.");
    pool.push("La tribuna canta el nombre de "+nom+".");
    if(ras==="capitán") pool.push(nom+" para el partido con un grito. El 5 manda.");
    if(ras==="ídolo") pool.push("Cuando toca "+nom+" la gente se para. Lo saben de memoria.");
    if(ras==="goleador"||ras==="definición") pool.push(nom+" se asoma al área. Huele a gol.");
    if(ras==="joven") pool.push(nom+" se manda. La inexperiencia y las ganas, las dos.");
  }
  if(min>=90){
    pool.push("El cuarto árbitro mira el reloj. Cada pelota es la última.");
    pool.push("Descuento. Las piernas pesan y la platea no se sienta.");
    pool.push("90 y tantos. Acá ya no se juega, se pelea el aire.");
    if(nom) pool.push(nom+" pide un último esfuerzo. La voz se le quiebra.");
  }
  if(P.cambios){
    pool.push("El recambio se nota: piernas nuevas contra piernas pesadas.");
    pool.push("El que acaba de entrar pide la pelota. Quiere justificar la ficha.");
  }
  if((P.cortados||[]).length && min<20){
    pool.push("En la tribuna se discute la lista. Hay un nombre que no salió.");
  }
  if(min<15){
    pool.push("El partido recién arranca. Los dos se estudian.");
    pool.push("Saque al medio y la pelota se queda en el círculo. Nadie quiere el error temprano.");
    pool.push("La tribuna empuja desde el primer minuto.");
    pool.push("Primer pelotazo largo de prueba. Nadie gana la dividida todavía.");
  }
  if(cans>7){
    pool.push("Se nota el desgaste. Las piernas ya no responden igual.");
    pool.push("El ritmo bajó. El físico empieza a mandar.");
    pool.push("Hay más errores por cansancio que por falta de ideas.");
  }
  if(min>75){
    pool.push("Último tramo. Cada pelota parece la definitiva.");
    pool.push("El árbitro mira el reloj. La tensión sube en la platea.");
    pool.push("Se juega con el corazón más que con la cabeza.");
  }
  if(P.precClima&&P.precClima<0.95){
    pool.push("El clima complica. La pelota no corre limpia.");
    pool.push("Cancha pesada. Cuesta encontrar espacios.");
    pool.push("El viento desvía un centro. El partido se pone trabado.");
  }
  pool.push(
    "Juego trabado en la mitad de la cancha.",
    "El árbitro cobra falta y la tribuna reclama.",
    "Cambio de ritmo: el partido se abrió.",
    "Se juega con el balón parado como única arma.",
    "Momento de estudio: nadie quiere equivocarse.",
    riv+" recupera y tira un pelotazo largo. Se diluye la jugada.",
    "Buen intercambio de pases, pero sin llegada clara."
  );
  return eligeNuevo(P, pool);
}
function lesionEnPartido(P){
  const j=elige(P.once.filter(x=>x.pos!=="ARQ"));
  if(j){
    j.lesion=ri(2,5); P.lesionados.push(j.n);
    linea(P,P.min,j.n+" se resiente y no puede seguir.","grave");
    recambioPorLesion(P,j);
  }
  return j;
}
function tiroLibreAuto(P){
  const j=pateadorDe(P.once);
  linea(P,P.min,"Tiro libre peligroso para "+E.clubNombre+", lo toma "+j.n+"…");
  const prob=clamp(0.11+((j.nivel||70)-70)*0.004+((j.rasgos&&j.rasgos.includes("tiro libre"))?0.10:0),0.05,0.32);
  if(Math.random()<prob){ j.goles++; P.goleadores.push(j.n); regGol(P,P.min,j.n,true,"tiro libre"); if(P.part.local)P.gl++; else P.gv++;
    linea(P,P.min,"¡GOLAZO de tiro libre de "+j.n+"! "+marcadorTxt(P),"gol"); return true; }
  linea(P,P.min,elige(["La barrera la desvía al córner.","¡Al travesaño! Por un pelo.",
    "El arquero vuela y la manda al córner.","Se fue rozando el palo."])); return false;
}
function centroCorner(P){
  const des=(E.tactica&&E.tactica.corner&&P.once&&P.once.find(function(j){ return j.n===E.tactica.corner; }));
  const aereo=des||(P.once||[]).filter(function(j){ return j.rasgos&&j.rasgos.indexOf("juego aéreo")>=0; })[0]
    || (P.once||[]).filter(function(j){ return j.pos==="DEL"||j.pos==="DEF"; })[0] || (P.once&&P.once[0]);
  const iner=((P.iner&&P.iner.cor)||0);
  if(typeof linea==="function") linea(P,P.min,"Córner. Centro al área, sube "+((aereo&&aereo.n)||"el área")+".");
  const aereoOk=aereo&&aereo.rasgos&&aereo.rasgos.indexOf("juego aéreo")>=0;
  /* 7.9042 · antes 10–30 % de los centros era gol (y solo a favor): real ronda 3–5 %. */
  const c=MOTOR_GOL.corner;
  const prob=clamp(c.base+(iner*c.iner)+(aereoOk?c.aereo:0)+(((aereo&&aereo.nivel)||70)-70)*0.0015,c.min,c.max);
  if(Math.random()<prob){
    if(aereo){ aereo.goles=(aereo.goles||0)+1; P.goleadores.push(aereo.n); if(typeof regGol==="function") regGol(P,P.min,aereo.n,true,"cabeza"); }
    if(P.part.local) P.gl++; else P.gv++;
    if(typeof linea==="function") linea(P,P.min,"¡Gol de cabeza"+(aereo?" de "+aereo.n:"")+" de córner! "+((typeof marcadorTxt==="function")?marcadorTxt(P):""),"gol");
    return true;
  }
  if(typeof linea==="function") linea(P,P.min,elige(["Despeja el primero.","El arquero se queda con el centro.","Cabezazo desviado."]));
  return false;
}
function resolverEventoAuto(P,ev){
  if(ev.tipo==="penal") penalEnPartido(P,true);
  else if(ev.tipo==="penalRival") penalEnPartido(P,false);
  else if(ev.tipo==="lesion") lesionEnPartido(P);
  else if(ev.tipo==="tiroLibre") tiroLibreAuto(P);
  else if(ev.tipo==="corner" && ev.aFavor!==false) centroCorner(P);
}
/* Corrida en bloque (simular y para completar tramos). */
function correrHasta(P,hasta){
  const prevSkip=P._skipVar; P._skipVar=true;
  let guard=0;
  while(!P.terminado&&guard++<1000){
    const techo=(hasta>=90)?topePartido(P):hasta;
    if(P.min>=techo && (hasta<90 || P._descDicho)){
      if(hasta>=90 && !P.tanda && typeof intentarDesempate==="function"){
        const de=intentarDesempate(P);
        if(de.tipo==="tanda"||de.tipo==="tandaFin"){
          if(typeof simularTanda==="function") simularTanda(P);
          break;
        }
        if(de.tipo==="prorroga"||de.tipo==="prorrogaHT") continue;
      }
      break;
    }
    const ev=tickPartido(P);
    if(typeof actualizarInercia==="function") actualizarInercia(P,ev);
    if(ev.tipo==="tanda"||ev.tipo==="tandaFin"){
      if(typeof simularTanda==="function") simularTanda(P);
      break;
    }
    if(ev.tipo==="fin") break;
    if(ev.tipo==="prorroga"||ev.tipo==="prorrogaHT") continue;
    if(ev.tipo==="penal"||ev.tipo==="penalRival"||ev.tipo==="lesion"||ev.tipo==="tiroLibre") resolverEventoAuto(P,ev);
    if(ev.tipo==="corner" && ev.aFavor!==false && typeof centroCorner==="function") centroCorner(P);
  }
  P._skipVar=prevSkip;
}
