/* texto sin sentido: muy corto, sin vocales o sin ninguna palabra de verdad */
function textoSinSentido(txt){
  const t=String(txt||"").toLowerCase().replace(/[@#]\S+/g," ").replace(/[^a-záéíóúñü\s]/g," ").trim();
  if(t.length<4) return true;
  const pal=t.split(/\s+/).filter(w=>w.length>=3 && /[aeiouáéíóú]/.test(w));
  return pal.length===0;
}
function responderHilo(t, txtYo){
  if(!t) return [];
  t.hilo=t.hilo||[];
  const yo=(txtYo||"").toLowerCase();
  const club=(E&&E.clubNombre)||"el club";
  const n=typeof ri==="function"?ri(4,6):4;
  const out=[];
  const pick=function(arr){ return (typeof elige==="function")?elige(arr):arr[Math.floor(Math.random()*arr.length)]; };
  const h=(typeof HANDLES_HINCHA!=="undefined")?HANDLES_HINCHA:["@hincha_de_ley"];
  /* 7.9055 · si escribiste algo sin sentido ("cf"), la gente no te contesta como si fuera un comunicado */
  if(textoSinSentido(txtYo)){
    const who=(typeof REDES_PEST!=="undefined"&&REDES_PEST==="club")?"la cuenta oficial":"el dt";
    const conf=["¿"+String(txtYo||"").trim().slice(0,12)+"? ¿se le cayó el celu a "+who+"?","jajaja "+who+" escribiendo con el codo","hackearon a "+who+" o qué 😂","¿mensaje en clave? no entendí nada","screenshot antes que lo borre 📸"];
    const k=2+Math.floor(Math.random()*2);
    const ini=Math.floor(Math.random()*conf.length);
    for(let i=0;i<k;i++){ const item={autor:pick(h),texto:conf[(ini+i)%conf.length],fecha:"ahora",tipo:"hincha"}; t.hilo.push(item); t.replies=(t.replies||0)+1; out.push(item); }
    return out;
  }
  const p=(typeof HANDLES_PRENSA!=="undefined")?HANDLES_PRENSA:["@RadioGolAM"];
  for(let i=0;i<n;i++){
    let autor, texto, tipo="hincha";
    if(i===0 && /ganar|título|estrella|me voy/.test(yo)){
      autor=pick(p); tipo="prensa";
      texto="el dt prometió en público. queda registrado.";
    } else if(i===n-1 && Math.random()<0.45){
      autor="@cuenta_troll"; tipo="hincha"; texto=pick(PLOP_RESP_TROLL);
    } else if(i===1 && Math.random()<0.35){
      autor=(typeof handleJugador==="function")?handleJugador():"@jugador_oficial";
      tipo="jugador"; texto=pick(PLOP_RESP_JUG);
    } else if(Math.random()<0.25){
      autor=pick(p); tipo="prensa"; texto=pick(PLOP_RESP_PRENSA);
    } else {
      autor=pick(h); texto=pick(PLOP_RESP_HINCHA);
    }
    texto=String(texto).replace(/\{CLUB\}/g,club);
    const item={autor:autor,texto:texto,fecha:"ahora",tipo:tipo};
    t.hilo.push(item);
    t.replies=(t.replies||0)+1;
    out.push(item);
  }
  return out;
}
function responderAlPostPropio(item, txt){
  if(!item) return;
  responderHilo(item, txt||item.texto||"");
}
/* 6.11 · convierte un recuerdo (2ª persona) en algo que la gente comenta (3ª persona) */
function memoriaEn3a(txt){
  let t=" "+txt;
  const map={ganaste:"ganó",perdiste:"perdió",goleaste:"goleó",vendiste:"vendió",prometiste:"prometió",
    saliste:"salió",levantaste:"levantó",reposteaste:"reposteó",moviste:"movió",forzaste:"forzó",
    metiste:"metió"};
  Object.keys(map).forEach(k=>{ t=t.replace(new RegExp("\\b"+k+"\\b","g"),map[k]); });
  t=t.replace(/\bte golearon\b/g,"lo golearon").replace(/\bte hiciste\b/g,"se hizo").replace(/\bte cobra\b/g,"le cobra");
  t=t.trim();
  return "el DT "+t;
}
/* un tweet que cita un hecho REAL de tu historia (memoria) */
function tweetDesdeMemoria(){
  if(typeof memoriaReciente!=="function") return null;
  const hechos=memoriaReciente(m=>(m.usado||0)<3, 8);
  if(!hechos.length) return null;
  const m=elige(hechos); m.usado=(m.usado||0)+1;
  const frase=memoriaEn3a(m.txt);
  if(m.tono==="bueno"){
    return postProc(elige(HANDLES_HINCHA),"hincha",elige([
      "Todavía me acuerdo cuando "+frase+". Grande 🙌",
      "El que dude que se acuerde: "+frase+" 💙",
      "Momentos que no se olvidan: "+frase+"."]),"bueno");
  }
  if(m.tono==="malo"||m.tono==="riesgo"){
    return postProc(elige(["@bancado_de_sillon","@el_verdadero_hincha","@memoria_de_hincha","@critico_del_club"]),"hincha",elige([
      "Nadie olvida que "+frase+". Ojo con eso 👀",
      "El hincha tiene memoria: "+frase+".",
      "Todavía duele que "+frase+"."]),"malo");
  }
  return postProc(elige(HANDLES_PRENSA),"prensa","Se sigue comentando que "+frase+".","neutro");
}
