/* 6.19 · SOLO hechos que existen AHORA en el save (no un banco 2010) */
function actualidadRedes(){
  const a={ club:(E&&E.clubNombre)||"el club", anio:E&&E.anio, modo:E&&E.modo };
  const prox=(typeof proximoPartido==="function")?proximoPartido():null;
  if(prox){ a.rival=prox.rivalNombre; a.sede=prox.sede; a.local=prox.local; }
  const ult=(E&&E.idx>0)?E.calendario[E.idx-1]:null;
  if(ult&&ult.jugado){ a.ultRival=ult.rivalNombre; a.ultGF=ult.gf; a.ultGC=ult.gc; a.ultLocal=ult.local;
    if(ult.goleadores&&ult.goleadores.length) a.goleador=elige(ult.goleadores); }
  const vent=((E&&E.memoria)||[]).filter(m=>m.tipo==="venta"&&m.anio===E.anio&&(E.idx-(m.idx||0))<=2).pop();
  if(vent&&vent.quien) a.vendido=vent.quien;
  const les=((E&&E.plantel)||[]).filter(j=>!j.vendido&&j.lesion>0);
  if(les.length){ const l=elige(les); a.lesionado=l.n; a.lesionadoPos=l.pos; }
  if(E&&E.temporada&&E.temporada.pj>0&&typeof posicionEnTabla==="function"){ a.pos=posicionEnTabla(); a.pts=E.temporada.pts; a.fecha=E.temporada.pj; }
  if(E&&E.barra){ if(E.barra.roto) a.pactoRoto=true;
    else { const vig=(E.barra.pactos||[]).filter(p=>!p.roto); if(vig.length&&(E.idx-(vig[vig.length-1].idx||0))<=3) a.pacto=vig[vig.length-1].resumen; } }
  return a;
}
/* 6.19 · genera un tuit a partir de un hecho real; el fresco (venta/resultado/lesión) manda */
function tuitDesdeActualidad(){
  const a=actualidadRedes(), c=[];
  if(a.ultGF!=null){
    const m=a.ultGF+"-"+a.ultGC, viz=a.ultLocal?" en casa":" de visita";
    if(a.ultGF>a.ultGC) c.push({f:1,tono:"bueno",tipo:"hincha",x:elige([
      m+" a "+a.ultRival+viz+". Así da gusto 💪",
      "Ganamos "+m+" a "+a.ultRival+". "+(a.goleador?"Grande "+a.goleador+" 🔥":"A seguir.")])});
    else if(a.ultGF===a.ultGC) c.push({f:1,tono:"malo",tipo:"hincha",x:"Otro "+m+" con "+a.ultRival+". Nos falta gol, siempre lo mismo."});
    else c.push({f:1,tono:"malo",tipo:"hincha",x:elige([
      m+" con "+a.ultRival+(a.ultLocal?" y de local":", de visita")+". Así no se juega.",
      "Perder "+m+" con "+a.ultRival+"... esto ya cansa 😤"])});
  }
  if(a.vendido) c.push({f:1,tono:"malo",tipo:"hincha",x:elige([
    "Se va "+a.vendido+". Plata lista, el equipo más pobre. Gracias "+a.club+".",
    a.vendido+" afuera. ¿Con quién jugamos ahora? 🤦"])});
  if(a.lesionado) c.push({f:1,tono:"neutro",tipo:"hincha",x:a.lesionado+" no llega. ¿Y ahora quién juega de "+(a.lesionadoPos||"eso")+"?"});
  if(a.rival) c.push({f:0,tono:"neutro",tipo:"prensa",x:elige([
    "El finde es "+a.rival+" en "+a.sede+". "+(a.goleador?"Si no aparece "+a.goleador+", esto es otro 0-0.":"Partido bravo."),
    a.club+" va con "+a.rival+" en "+a.sede+". A ver con qué cara se planta."])});
  if(a.pts!=null) c.push({f:0,tono:"malo",tipo:"hincha",x:"Fecha "+a.fecha+", "+a.pts+" pts, "+ordinal(a.pos)+". Esto ya no es proyecto."});
  if(a.pactoRoto) c.push({f:1,tono:"malo",tipo:"hincha",x:"La mesa era clara y la rompieron. Con la barra no se juega. 🚩"});
  else if(a.pacto) c.push({f:1,tono:"neutro",tipo:"hincha",x:"La barra acordó "+a.pacto+". Ahora que la dirigencia cumpla."});
  if(!c.length) return null;
  const frescos=c.filter(x=>x.f), pool=(frescos.length&&Math.random()<0.75)?frescos:c;
  const pick=elige(pool);
  const handle=pick.tipo==="prensa"?elige(HANDLES_PRENSA):(Math.random()<0.5?handleHinchaDeClub():elige(HANDLES_HINCHA));
  /* anti-repetición: no repetir el texto del último post */
  if(E&&E.timeline&&E.timeline[0]&&E.timeline[0].texto===pick.x) return null;
  return postProc(handle, pick.tipo, pick.x, pick.tono);
}
/* un post de "bot" para que el feed se mueva solo, como Twitter */
function botPost(){
  const part=typeof proximoPartido==="function"?proximoPartido():null;
  const riv=part?part.rivalNombre:"el próximo rival";
  /* 6.19 · el hecho FRESCO del save manda (venta, resultado, lesión, previa, tabla) */
  const fresco=(typeof tuitDesdeActualidad==="function")?tuitDesdeActualidad():null;
  if(fresco) return fresco;
  /* memoria al 40% cuando no hay hecho fresco */
  if(Math.random()<0.4){ const m=tweetDesdeMemoria(); if(m) return m; }
  /* relleno estático (máx ~20%): solo si no hubo fresco ni memoria */
  const dados=[
    ()=>postProc(elige(HANDLES_HINCHA),"hincha",elige(TWEETS_HINCHA).x,"bueno"),
    ()=>postProc(elige(HANDLES_PRENSA),"prensa",elige([
        "Rumores de mercado en "+((E&&E.clubNombre)||"el club")+". Seguimos de cerca.",
        "El plantel entrena pensando en "+riv+".",
        "Se habla de cambios en la formación para el finde.",
        "La tabla aprieta y cada punto vale oro."]),"neutro"),
    ()=>postProc("@hincha_rival","rival",elige([
        "Los vamos a pasar por arriba 😎","Puro humo el rival de la fecha.","Acá se viene a sufrir, avisados están."]),"malo"),
    ()=>postProc(elige(HANDLES_HINCHA),"hincha",elige(TWEETS_HINCHA).x,"bueno"),
    ()=>{ const ho=elige(TWEETS_HOSTIL); return postProc(elige(["@bancado_de_sillon","@el_verdadero_hincha","@critico_del_club"]),"hincha",ho.x,"malo"); }
  ];
  return elige(dados)();
}

/* ---------- reacciones con contexto ---------- */
function redesReaccion(tipo,data){
  if(!E) return;
  data=data||{};

  if(tipo==="partido"){
    const dif=(data.yo||0)-(data.otro||0);
    const rival=data.rival||"el rival";
    if(dif>0){
      const frasesH=[
        "¡GRANDE! "+data.yo+"-"+data.otro+". Así se juega, con huevos 💪",
        "Victoria trabajada. El pueblo lo siente ❤️",
        "Le ganamos a "+rival+" y se notó la jerarquía. ¡ARRIBA!",
        "Tres puntos de oro. Ahora a pensar en el próximo.",
        "Esto es del club. Nadie regala nada y lo sacamos igual."
      ];
      postProc(elige(HANDLES_HINCHA),"hincha",elige(frasesH),"bueno");
      if(dif>=3){
        const pr=cuentaPrensa();
        postProc(pr.h,"prensa",
          pr.linea<0
            ?"Goleada "+data.yo+"-"+data.otro+" ante "+rival+". No se emocionen: esto no tapa el resto."
            :"Goleada contundente: "+data.yo+"-"+data.otro+" ante "+rival+". El equipo se afirma.",
          pr.linea<0?"neutro":"bueno");
        postProc(handleJugador(),"jugador",elige([
          "Feliz por el triunfo del grupo. Seguimos 👊",
          "Buen trabajo de todos. A disfrutar un rato y después a pensar en lo que viene."
        ]),"bueno");
      } else if(dif===1){
        postProc(elige(HANDLES_PRENSA),"prensa",
          "Victoria ajustada ante "+rival+" ("+data.yo+"-"+data.otro+"). Sufrió, pero sumó.",
          "neutro");
      }
      moverSeguidores(ri(180,1100)+dif*280);
    } else if(dif<0){
      const frasesM=[
        "Otra vez lo mismo... 😡 La gente se cansa.",
        "Así no, muchachos. Faltó actitud contra "+rival+".",
        "Un papelón. ¿Hasta cuándo vamos a apoyar esto?",
        "Perdimos bien feo. El vestuario tiene que mirarse a la cara.",
        "La hinchada bancó y el equipo no respondió. Duele."
      ];
      postProc(elige(HANDLES_HINCHA),"hincha",elige(frasesM),"malo");
      postProc(elige(HANDLES_PRENSA),"prensa",
        "Derrota ante "+rival+" ("+data.otro+"-"+data.yo+") que enciende las alarmas en el entorno.",
        "malo");
      if(Math.abs(dif)>=3){
        postProc(elige(HANDLES_HINCHA),"hincha","Esto ya no es casualidad. Hay que cambiar algo ya.","malo");
      }
      moverSeguidores(-ri(120,900));
    } else {
      postProc(elige(HANDLES_HINCHA),"hincha",elige([
        "Empate tibio. Faltó profundidad.",
        "Un punto que sabe a poco. Había que ganar.",
        "Empatamos con "+rival+". Ni fu ni fa."
      ]),"neutro");
      moverSeguidores(ri(-80,220));
    }
    return;
  }

  if(tipo==="desfalco"){
    const monto=data.monto;
    const cifra=(typeof plata==="function"&&monto)?plata(monto):"plata del club";
    postProc(elige(HANDLES_PRENSA),"prensa",
      "Auditoría en "+(E.clubNombre||"el club")+": hay irregularidades en tesorería por "+cifra+". El entorno pide explicaciones.","malo");
    postProc(elige(HANDLES_HINCHA),"hincha",elige([
      "¿Se llevaron la plata del club? Si es cierto, que se vayan TODOS.",
      "Esto no es un rumor de camarín. Si desviaron fondos, la hinchada no perdona.",
      "Dirigencia ladrona. Queremos nombres y queremos la plata de vuelta."
    ]),"malo");
    moverSeguidores(-ri(400,1800));
    return;
  }

  if(tipo==="ficha"){
    postProc(elige(HANDLES_HINCHA),"hincha",elige([
      "¡Bienvenido "+data.n+"! Ojalá rompa todo 🙌",
      data.n+" llega con ganas. A apoyarlo desde el primer día.",
      "Nuevo refuerzo: "+data.n+". Que se ponga la camiseta de verdad."
    ]),"bueno");
    postProc(handleJugador(),"jugador",elige([
      "Contento con la llegada de "+data.n+". Suma al grupo 👊",
      "Bienvenido al vestuario, "+data.n+". Acá se trabaja en serio."
    ]),"bueno");
    if(ri(0,1)){
      postProc(elige(HANDLES_PRENSA),"prensa",
        "El club oficializó a "+data.n+". Operación que apunta a reforzar el plantel de cara a lo que viene.",
        "neutro");
    }
    moverSeguidores(ri(280,1600));
    return;
  }

  if(tipo==="venta"){
    /* Variedad real: no siempre amurrado.
       data.flash = remate de urgencia
       data.ref   = ídolo/capitán
       data.edad / data.nivel opcionales
    */
    const n=data.n||"el jugador";
    const esFlash=!!data.flash;
    const esRef=!!data.ref;
    const roll=Math.random();

    if(esFlash){
      // remate: casi siempre malo, pero con matices
      if(esRef){
        postProc(elige(HANDLES_HINCHA),"hincha",elige([
          "¿Cómo van a rematar así a "+n+"?? Vergüenza dirigencial 🤬",
          "Vender a un referente de urgencia es no entender nada del club.",
          n+" se va por dos mangos. La historia no lo va a olvidar."
        ]),"malo");
        moverSeguidores(-ri(500,1800));
      } else {
        postProc(elige(HANDLES_HINCHA),"hincha",elige([
          "Remate de "+n+". Plata rápida, pero se nota el apuro.",
          "Se fue "+n+" a precio de liquidación. Ojalá sirva para ordenar la casa."
        ]),"malo");
        postProc(elige(HANDLES_PRENSA),"prensa",
          n+" salió en operación de urgencia. El club priorizó caja por sobre valor de mercado.",
          "neutro");
        moverSeguidores(-ri(150,700));
      }
    } else if(esRef){
      // referente vendido "bien": reacción mixta
      if(roll<0.45){
        postProc(elige(HANDLES_HINCHA),"hincha",elige([
          "Se va "+n+". Duele, pero si la plata es seria y el club se fortalece, se entiende.",
          n+" dio todo. Ojalá le vaya bien... y que el club no se equivoque con el reemplazo."
        ]),"neutro");
        postProc(elige(HANDLES_PRENSA),"prensa",
          "Salida de un referente: "+n+" cambia de club. Operación que genera debate en el entorno.",
          "neutro");
        moverSeguidores(-ri(200,900));
      } else {
        postProc(elige(HANDLES_HINCHA),"hincha",elige([
          "No puedo creer que dejen ir a "+n+". Esto es una traición a la historia del club.",
          "Primero los ídolos, después los dirigentes. Así siempre."
        ]),"malo");
        moverSeguidores(-ri(400,1400));
      }
    } else {
      // jugador normal: mayoría neutra/positiva de caja
      if(roll<0.55){
        postProc(elige(HANDLES_PRENSA),"prensa",
          n+" deja el club. Operación que ayuda a la caja y abre espacio en el plantel.",
          "neutro");
        if(ri(0,1)){
          postProc(elige(HANDLES_HINCHA),"hincha",elige([
            "Se fue "+n+". No era intocable. A mirar para adelante.",
            "Buena venta si la plata vuelve al plantel. Hay que ser fríos a veces."
          ]),"neutro");
        }
        moverSeguidores(ri(-80,350));
      } else if(roll<0.8){
        postProc(elige(HANDLES_HINCHA),"hincha",
          "Se va "+n+". Ojalá el club sepa reinvertir, porque si no es más de lo mismo.",
          "neutro");
        moverSeguidores(ri(-150,200));
      } else {
        postProc(elige(HANDLES_HINCHA),"hincha",
          "Otra salida más. El plantel se desarma y después nos piden paciencia.",
          "malo");
        moverSeguidores(-ri(100,500));
      }
    }
    return;
  }

  if(tipo==="precio"){
    if(data.ratio>1.35){
      postProc(elige(HANDLES_HINCHA),"hincha",elige([
        "Suben las entradas otra vez y el fútbol lo paga el hincha de siempre 😤",
        "Precios de marquesina para un equipo que todavía no demuestra. Así no se llena."
      ]),"malo");
      moverSeguidores(-ri(60,320));
    } else if(data.ratio<0.82){
      postProc(elige(HANDLES_HINCHA),"hincha",elige([
        "Entradas populares, así se llena la cancha 👏",
        "Buen gesto de la dirigencia con los precios. El pueblo responde."
      ]),"bueno");
      moverSeguidores(ri(120,550));
    }
    return;
  }
}

/* campañas del Community Manager (requiere E.staff.cm) */
function campanaCM(tipo){
  if(!E.staff||!E.staff.cm){
    if(typeof aviso==="function") aviso("Primero contrata un Community Manager (Finanzas)");
    return;
  }
  if(tipo==="humo"){
    aplicarEfectos({hinchada:6,moral:2});
    aplicarRep({credibilidad:-3});
    moverSeguidores(ri(600,2600));
    postProc(handleClub(),"club",elige([
      "El club más grande. Vamos por todo, familia.",
      "Historia, gloria y futuro. Esto es "+(E.clubNombre||"el club")+" 💪",
      "Nadie nos calla. Orgullo de vestir estos colores."
    ]),"bueno");
    notificar({t:"Campaña de humo",tipo:"neutro",
      d:"El CM encendió a la gente (+hinchada, +seguidores) a costa de algo de credibilidad si después no acompañan los resultados.",
      bandeja:false});
  } else {
    aplicarRep({credibilidad:6,publica:2});
    aplicarGrupos({prensa:5});
    moverSeguidores(ri(-100,300));
    postProc(handleClub(),"club",
      "Comunicado oficial: el club informa con transparencia sobre su situación institucional.",
      "neutro");
    notificar({t:"Comunicado oficial",tipo:"neutro",
      d:"El CM emitió un comunicado serio: suma credibilidad y ordena el mensaje.",
      bandeja:false});
  }
  guardar();
}

/* ingreso anual por seguidores (sponsor digital), solo si hay CM */
function ingresoDigital(){
  return (E.staff&&E.staff.cm)?Math.round((E.seguidores||0)*0.02):0;
}

/* ============================================================
   5.0 · Bloque 3 — Ticker EN VIVO durante el partido (FutbolGram)
   Se llama por cada tick del partido; empuja posts cortos a
   P.ticker (feed local del partido). No toca E.timeline.
   ============================================================ */
function tickerPost(P, ev){
  if(!P || !ev) return;
  P.ticker=P.ticker||[];
  const m=ev.min||P.min||0;
  const club=(typeof E!=="undefined"&&E.clubNombre)?E.clubNombre:"el club";
  const rival=(P.part&&P.part.rivalNombre)||"el rival";
  let autor=elige(HANDLES_HINCHA), texto=null, tono="neutro";
  switch(ev.tipo){
    case "gol":{
      autor=elige(HANDLES_HINCHA); tono="bueno";
      const gd=(P.golesDetalle||[]).filter(g=>g.propio); const aut=gd.length?gd[gd.length-1].quien:null;
      const [y1,o1]=(typeof miMarcador==="function")?miMarcador(P):[0,0];
      texto=aut?elige(["¡GOOOL de "+aut+"! "+m+"' 🔥🔥","¡LA METIÓ "+aut+"! "+m+"', vamos carajo 💪","Golazo de "+aut+", "+m+"' ⚽ ("+y1+"-"+o1+")","¡ARRIBA! "+aut+" la clavó, "+m+"' ❤️"])
        :elige(["¡GOOOOL NUESTRO! "+m+"' 🔥🔥","¡LA METIÓ! "+m+"', vamos carajo 💪","Golazo. Se grita con todo, "+m+"' ⚽"]); break; }
    case "golRival":{
      autor=elige(HANDLES_HINCHA); tono="malo";
      const gd=(P.golesDetalle||[]).filter(g=>!g.propio); const aut=gd.length?gd[gd.length-1].quien:null;
      texto=elige(["Nos hicieron gol"+(aut?" ("+aut+")":"")+"... "+m+"' 😩","Uh no, gol de "+rival+". A despertar, "+m+"'.","Otra vez mal parados atrás, "+m+"' 😡","Gol de "+rival+". Duele, "+m+"'."]); break; }
    case "penal":
      autor=elige(HANDLES_PRENSA); tono="bueno";
      texto="🚨 ¡PENAL para "+club+" en el "+m+"'! El VAR lo mira con lupa…"; break;
    case "penalRival":
      autor=elige(HANDLES_PRENSA); tono="malo";
      texto="🚨 Penal en contra, "+m+"'. Polémico: la banca protesta y las redes explotan."; break;
    case "tiroLibre":
      autor=elige(HANDLES_HINCHA); tono="neutro";
      texto="Tiro libre peligrosísimo, "+m+"'. A meterla de una 🙏"; break;
    case "tarjeta":
      autor=elige(HANDLES_PRENSA); tono="neutro";
      texto="🟨 Amarilla en el "+m+"'. Ojo con la próxima."; break;
    case "lesion":
      autor=elige(HANDLES_HINCHA); tono="malo";
      texto="Uno quedó tirado en el "+m+"'… ojalá no sea grave 🤕"; break;
    case "chance":
      if(Math.random()<0.45){ autor=elige(HANDLES_HINCHA); texto="¡UHHH la que se perdió! "+m+"' 😱"; tono="neutro"; }
      break;
    case "polemica":
      autor=elige(HANDLES_PRENSA); texto="📺 Repiten la jugada del "+m+"'… el árbitro ya es tendencia."; tono="neutro"; break;
    case "varCheck":
      autor=elige(HANDLES_PRENSA); tono="neutro";
      texto="📺 VAR en el "+m+"'. El juez se va al monitor y el estadio se queda mudo."; break;
    case "corner":
      if(ev.aFavor!==false && Math.random()<0.55){
        autor=elige(HANDLES_HINCHA); tono="neutro";
        texto="Córner nuestro, "+m+"'. A meterla de cabeza 🙏";
      }
      break;
    case "prorroga":
      autor=elige(HANDLES_PRENSA); tono="neutro";
      texto="⏱️ Empate. Hay alargue. Treinta minutos más y el corazón en la boca."; break;
    case "prorrogaHT":
      autor=elige(HANDLES_HINCHA); tono="neutro";
      texto="Descanso de la prórroga. Todavía no se define. 😬"; break;
    case "tanda":
      autor=elige(HANDLES_PRENSA); tono="neutro";
      texto="🚨 Tanda de penales. Que no le tiemble el pie."; break;
    default: return;
  }
  if(!texto) return;
  P.ticker.unshift({m:m, autor:autor, texto:texto, tono:tono});
  if(P.ticker.length>TICKER_MAX) P.ticker.length=TICKER_MAX;
}
/* 6.36 · tuits que reaccionan al MOMENTO (marcador, tensión, tiempo), no a la jugada.
   Se llaman de a ratos desde el loop: hacen sentir FutbolGram vivo. */
/* 7.9055 · Plop en vivo con utilidad: análisis con números reales y encuestas que dicen qué pide la gente.
   Uno a los 30', otro a los 60' y otro a los 80' (antes el análisis casi nunca salía). */
function tickerAnalisis(P){
  if(!P||!P.ticker) return false;
  const m=P.min||0, marca=[30,60,80].find(x=>m>=x && !(P._anal||{})[x]);
  if(!marca) return false;
  P._anal=P._anal||{}; P._anal[marca]=true;
  const s=P.stats||{}, pos=Math.round((s.pos||0.5)*100);
  const dom=(P.dom||[]).slice(-6), dv=dom.length?dom.reduce((a,x)=>a+x.v,0)/dom.length:0;
  const [yo,otro]=(typeof miMarcador==="function")?miMarcador(P):[P.gl,P.gv];
  const lectura=dv>0.15?"el partido es tuyo, falta la puntada":(dv<-0.15?"te están llevando por delante":"está parejo, lo gana el que se equivoque menos");
  const txt="📊 "+m+"': posesión "+pos+"% · remates "+(s.remMio||0)+"-"+(s.remRiv||0)+" · al arco "+(s.arcMio||0)+"-"+(s.arcRiv||0)+". Lectura: "+lectura+".";
  P.ticker.unshift({m:m, autor:"@datofutbol_cl", texto:txt, tono:"neutro"});
  const dif=yo-otro;
  const preg=dif<0?"¿Cambio ofensivo YA?":(dif>0?"¿Cerrar el partido o ir por otro?":"¿Arriesgar o esperar el error?");
  const si=Math.round(clamp(50+(dif<0?18:(dif>0?-12:0))+(dv<0?8:-4)+ri(-6,6),20,85));
  P.ticker.unshift({m:m, autor:elige(HANDLES_HINCHA), texto:"🗳 Encuesta: "+preg+" Sí "+si+"% · No "+(100-si)+"%", tono:"neutro"});
  if(P.ticker.length>TICKER_MAX) P.ticker.length=TICKER_MAX;
  return true;
}
function tickerAmbiente(P){
  if(!P||!P.ticker) return;
  if(tickerAnalisis(P)) return;
  const [yo,otro]=(typeof miMarcador==="function")?miMarcador(P):[P.gl,P.gv];
  const dif=yo-otro, m=P.min||0, rival=(P.part&&P.part.rivalNombre)||"el rival";
  let ops=[];
  if(m>=80){
    if(dif>0) ops=["Aguanta esto corazón mío, "+m+"' 😰","QUE SE TERMINE YA, "+m+"' 🙏","Ganando y sufriendo como siempre 😅 "+m+"'","No mires el reloj, no mires el reloj… "+m+"'"];
    else if(dif<0) ops=["Se nos va el partido, "+m+"' 😔","Última bala, todos arriba "+m+"'","No puede ser, reaccionen "+m+"' 😡","Regalamos otra vez, "+m+"'…"];
    else ops=["Un gol lo cambia todo, "+m+"' 👀","Empate y a no volverse loco, "+m+"'","Cualquiera lo gana, "+m+"' 🫣"];
  } else if(m>=25 && m<=65){
    if(dif===0) ops=["Partido trabado, cero que ver "+m+"' 😴","Alguien que invente algo, "+m+"'","Se juega todo en el medio, "+m+"'","Falta un enganche que la piense, "+m+"'"];
    else if(dif>0) ops=["Vamos ganando pero hay que cerrarlo, "+m+"'","Dominamos, falta la sentencia "+m+"'","Cuando queremos, jugamos lindo 😍 "+m+"'"];
    else ops=["Nos pasan por arriba, "+m+"' 😤","El técnico tiene que mover algo YA, "+m+"'","Contra "+rival+" siempre lo mismo, "+m+"'"];
  } else return;
  /* 7.9056 · cada mensaje lleva hacia dónde empuja (el panel de decisiones marca los últimos del chat) */
  const dir=dif<0?"ataque":((dif>0&&m>=70)?"aguantar":"equilibrio");
  P.ticker.unshift({m:m, autor:elige(HANDLES_HINCHA), texto:elige(ops), tono:dif>0?"bueno":(dif<0?"malo":"neutro"), dir:dir});
  if(P.ticker.length>TICKER_MAX) P.ticker.length=TICKER_MAX;
}
/* 7.9071 · el chat en vivo guarda todo el partido (antes se cortaba a 18) */
var TICKER_MAX=150;
/* charla suelta: jugadores con nombre, la hinchada rival, el árbitro, el clima, la cancha.
   Para que el chat no se muera entre jugada y jugada (pedido del autor: "quedó fome"). */
function tickerCharla(P){
  if(!P) return null;
  P.ticker=P.ticker||[];
  const m=P.min||0, once=(P.once||[]).filter(j=>j&&j.n), j=once.length?elige(once).n.split(" ").slice(-1)[0]:"el diez";
  const riv=(P.part&&P.part.rivalNombre)||"el rival", sede=(P.part&&P.part.sede)||"la cancha";
  const [yo,otro]=(typeof miMarcador==="function")?miMarcador(P):[P.gl||0,P.gv||0];
  const cl=(typeof CLIMAS!=="undefined"&&P.part&&CLIMAS[P.part.clima])||null;
  const pool=[
    {a:"hincha",t:j+" está en otra, hoy no la toca "+m+"'",tono:"malo"},
    {a:"hincha",t:"Hoy "+j+" está intratable, denle la pelota a él",tono:"bueno"},
    {a:"hincha",t:"¿Alguien le avisó a "+j+" que empezó el partido? "+m+"'",tono:"malo"},
    {a:"hincha",t:"Que "+j+" le pegue de lejos, el arquero está adelantado",tono:"neutro"},
    {a:"rival",t:"Tranquilos, que "+riv+" ya les llega "+m+"'",tono:"malo"},
    {a:"rival",t:"Juegan con doce, el árbitro es de ustedes 🙄",tono:"malo"},
    {a:"rival",t:"Qué nervios tienen, jajaja, "+m+"'",tono:"malo"},
    {a:"hincha",t:"El árbitro no cobra nada para acá, "+m+"'",tono:"malo"},
    {a:"hincha",t:"Mi abuela patea mejor esos córners",tono:"neutro"},
    {a:"hincha",t:"Estoy en "+sede+" y se escucha a la barra desde la entrada",tono:"bueno"},
    {a:"prensa",t:"Desde "+sede+": "+(yo===otro?"partido de dientes apretados":(yo>otro?"el local se encuentra cómodo":"hay murmullo en la tribuna"))+", "+m+"'",tono:"neutro"},
    {a:"hincha",t:"El carrito del maní pasó tres veces y todavía no pasa nada en la cancha",tono:"neutro"}
  ];
  if(cl) pool.push({a:"hincha",t:({lluvia:"Llueve a cántaros y la pelota no corre",calor:"Qué calor, los jugadores no dan más",frio:"Un frío de cagarse en la galería",viento:"Con este viento, cada centro es una lotería",despejado:"Tarde linda para ganar"})[P.part.clima]||"",tono:"neutro"});
  const usados=P.ticker.slice(0,20).map(x=>x.texto);
  const libres=pool.filter(x=>x.t&&usados.indexOf(x.t)<0);
  const x=elige(libres.length?libres:pool);
  const autor=x.a==="prensa"?elige(HANDLES_PRENSA):(x.a==="rival"?"@hincha_"+String(riv).toLowerCase().replace(/[^a-z]/g,"").slice(0,10)+"_"+(10+(m%80)):elige(HANDLES_HINCHA));
  const it={m:m, autor:autor, texto:x.t, tono:x.tono, rival:x.a==="rival"};
  P.ticker.unshift(it);
  if(P.ticker.length>TICKER_MAX) P.ticker.length=TICKER_MAX;
  P._ultChat=m;
  return it;
}
/* mensajes del chat en vivo que empujan una dirección (misma voz que el resto del chat).
   Grok puede sumar frases acá (pedido del autor): que se entiendan, sin decir la respuesta obvia. */
var PISTAS_CHAT={
  ataque:["Hay que meter otro de arriba, así no llegamos nunca","Menos toque para atrás y más pelotas al área","Si no arriesgamos ahora, ¿cuándo?","El nueve está solo allá arriba, mándenle gente","Con este ritmo no le hacemos cosquillas al arquero","El área está vacía y nosotros paseando atrás","Una al segundo palo y se acaba la historia","Si no llegamos, que llegue al menos el centro","El arquero de ellos está regalando el primer palo","Ya está: hay que vivir en el área de ellos","El nueve pide y nadie le tira el centro","Así no se gana: falta gente arriba","El lateral tiene toda la banda libre, que suba de una vez","Los volantes están jugando de memoria, hay que arriesgar el pase","Con un cambio de ritmo esto se abre","Ese quinto defensa rival sobra, hay que aprovechar el hueco","Menos vuelta y más pelota adentro del área"],
  aguantar:["Cierren esto, no regalen nada","Paren la pelota, que el rival se desespera","Un volante más atrás y a cuidar lo que hay","El que se apura ahora la caga, tranquilos atrás","Nada de salir jugando corto ahora","El empate nos sirve. Que se note","Cada pelota dividida es nuestra","Atrás firmes. Esto se cuida, no se adorna","Que no se enamoren del balón","Un error y se nos va el partido","Manden la pelota afuera si hay que mandarla afuera","No hay premio por jugar bonito ganando así","Cada córner en contra es un peligro que no necesitamos","El que quiera lucirse ahora, que se aguante las ganas","Achicar los espacios y que corra el reloj"],
  equilibrio:["Tranquilos, sin volverse locos, el gol llega","Paciencia, que el partido está para nosotros","Ni tan atrás ni tan adelante, que se juegue en el medio","Así está bien, falta afinar el último pase","Está parejo. El que se desespera, pierde","Un cambio de ritmo, no un cambio de plan","Que el medio no se parta en dos","Bien así: presionar sin dejar la espalda sola","No hace falta inventar. Está para nosotros","Que circule. El hueco aparece solo","Ninguna urgencia todavía, el partido recién empieza","Buen trámite. Que nadie se apure por las puras","La cancha está pareja, gana el que no se pone nervioso","Sin regalar nada pero sin dormirse tampoco","Esto se define en un detalle, no en un arrebato"],
  riesgo:["A todo o nada ya, no hay nada que perder","Todos arriba, hasta el arquero si hace falta","O entra ahora o nos vamos con las manos vacías","Que suba gente. El cero no le sirve a nadie","Último cuarto: el que no arriesga, ya perdió","Una más al área. Después vemos","Si nos empatan igual, que sea por intentar","No queda tiempo para pensarlo dos veces","Al ataque con todo, ya no hay nada que cuidar","Si se pierde, que sea yendo para adelante","Manden hasta al lesionado de la banca si hace falta","Esto se juega de una vez, no quedan vueltas"]
};
function tickerPista(P,dir){
  if(!P) return null;
  P.ticker=P.ticker||[];
  const pool=PISTAS_CHAT[dir]||PISTAS_CHAT.equilibrio;
  const usados=P.ticker.map(x=>x.texto);
  const libres=pool.filter(t=>usados.every(u=>u.indexOf(t)<0));
  const it={m:P.min||0, autor:elige(HANDLES_HINCHA), texto:elige(libres.length?libres:pool)+", "+(P.min||0)+"'", tono:"neutro", dir:dir};
  P.ticker.unshift(it);
  if(P.ticker.length>TICKER_MAX) P.ticker.length=TICKER_MAX;
  return it;
}
/* los últimos 3 del chat que dicen qué hacer: 2 con lo que pide la mayoría y 1 que disiente */
function plopPistas(P,rec){
  if(!P) return [];
  P.ticker=P.ticker||[];
  let alineados=P.ticker.slice(0,8).filter(x=>x.dir===rec).length;
  while(alineados<2){ tickerPista(P,rec); alineados++; }
  const recientes=P.ticker.slice(0,8).filter(x=>x.dir);
  if(!recientes.some(x=>x.dir!==rec)){ const otros=Object.keys(PISTAS_CHAT).filter(k=>k!==rec&&k!=="riesgo"); tickerPista(P,elige(otros)); }
  const ult=P.ticker.slice(0,10).filter(x=>x.dir);
  const a=ult.filter(x=>x.dir===rec).slice(0,2), d=ult.filter(x=>x.dir!==rec).slice(0,1);
  const tres=a.concat(d).sort((x,y)=>P.ticker.indexOf(x)-P.ticker.indexOf(y));
  P.ticker.forEach(x=>{ x.pista=false; }); tres.forEach(x=>{ x.pista=true; });
  return tres;
}

/* ============================================================
   6.34 · Titulares de la liga para "Lo que pasó esta semana".
   Noticias RELEVANTES atadas al estado real: puntero de la tabla,
   goleada de la fecha, tu racha, el próximo rival, más una noticia
   posible del ambiente (estable dentro de la semana, por E.idx).
   ============================================================ */
function noticiaPosible(){
  const prox=(E.calendario&&E.calendario[E.idx])||null;
  const riv=prox?prox.rivalNombre:"el rival de turno";
  const pool=[
    {t:"🎙️ La previa ya calienta",d:"En los programas deportivos no hablan de otra cosa que del partido con "+riv+"."},
    {t:"🧑‍⚖️ Designaron al árbitro",d:"La ANFP nombró la terna para la fecha. En los foros ya desconfían, como siempre."},
    {t:"💸 Rumores de mercado",d:"Suena que un club grande anda mirando jugadores de media tabla. Nada firmado, puro humo por ahora."},
    {t:"🌧️ Parte meteorológico",d:"Anuncian tiempo variable para el fin de semana. Las canchas del sur, complicadas."},
    {t:"📺 Cambian el horario",d:"La TV movió el horario de varios partidos para acomodar la transmisión. Los hinchas, reclamando."},
    {t:"🏥 Parte médico en la liga",d:"Varios equipos llegan con bajas por lesión a esta fecha. El calendario apretado pasa la cuenta."},
    {t:"🔥 Otro técnico en la cuerda floja",d:"En otro club la hinchada pide la cabeza del DT tras un mal arranque. El fútbol no perdona."}
  ];
  return pool[(((E.idx|0)+(parseInt(E.anio,10)||0))%pool.length+pool.length)%pool.length];
}
function titularesSemana(){
  const out=[];
  if(E.tabla && typeof posicionEnTabla==="function" && E.temporada && E.temporada.pj>0){
    const arr=Object.keys(E.tabla).map(id=>({id:id,pts:E.tabla[id].pts||0})).sort((a,b)=>b.pts-a.pts);
    const lider=arr[0]&&(typeof CLUB_POR_ID!=="undefined")?CLUB_POR_ID[arr[0].id]:null;
    if(arr[0]) out.push({t:"📊 "+(lider?(lider.n||lider.c):"El puntero")+" manda la tabla",
      d:"Arriba con "+arr[0].pts+" puntos. Tú vas "+ordinal(posicionEnTabla())+"."});
  }
  if(E.ultimaFecha && E.ultimaFecha.length){
    const g=E.ultimaFecha.slice().sort((a,b)=>Math.abs(b.ga-b.gb)-Math.abs(a.ga-a.gb))[0];
    if(g && Math.abs(g.ga-g.gb)>=3) out.push({t:"🥅 Goleada de la fecha",d:g.a+" "+g.ga+"-"+g.gb+" "+g.b+". Papelón para uno, fiesta para el otro."});
  }
  const sinGanar=(E.temporada&&E.temporada.sinGanar)||0;
  if(sinGanar>=3) out.push({t:"📉 Te miran de reojo",d:"Son "+sinGanar+" fechas sin ganar. La prensa ya cuenta los partidos que te quedan."});
  const prox=E.calendario&&E.calendario[E.idx];
  if(prox) out.push({t:"🗓️ Se viene "+prox.rivalNombre,d:(prox.local?"De local":"De visita")+" en "+prox.sede+". A preparar la semana."});
  out.push(noticiaPosible());
  return out;
}

