/* ==== js/casino.js ==== */
"use strict";
/* ============================================================
   FUTBOLINI 5.0 · casino.js  (Bloque 2)
   Casino con plata personal (E.personal.bolsillo), corrupción /
   desfalco (meter mano a la caja del club E.plata) y redención.
   Tono realista y crudo, ficción de juego. Odds de ruleta reales.
   ============================================================ */

/* ---------- ruleta europea (37 casillas, ventaja de casa real ~2.7%) ---------- */
var RULETA_ROJOS=[1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];
var APUESTAS_CASINO=[
 {id:"rojo",  n:"Rojo",   pago:2,  gana:n=>n!==0&&RULETA_ROJOS.indexOf(n)>=0, prob:"48,6%"},
 {id:"negro", n:"Negro",  pago:2,  gana:n=>n!==0&&RULETA_ROJOS.indexOf(n)<0,  prob:"48,6%"},
 {id:"1a12",  n:"1 al 12",pago:3,  gana:n=>n>=1&&n<=12,  prob:"32,4%"},
 {id:"13a24", n:"13 al 24",pago:3, gana:n=>n>=13&&n<=24, prob:"32,4%"},
 {id:"25a36", n:"25 al 36",pago:3, gana:n=>n>=25&&n<=36, prob:"32,4%"},
 {id:"pleno", n:"Pleno (un número)",pago:36,gana:(n,e)=>n===e, prob:"2,7%"}
];
function colorRuleta(n){ return n===0?"verde":(RULETA_ROJOS.indexOf(n)>=0?"rojo":"negro"); }
function girarRuleta(apId, monto, plenoNum){
  const ap=APUESTAS_CASINO.find(a=>a.id===apId); if(!ap) return null;
  if(typeof bolsilloDT==="function") bolsilloDT();
  if(!E.personal) E.personal={};
  if(typeof E.personal.bolsillo!=="number" || isNaN(E.personal.bolsillo)) E.personal.bolsillo=0;
  const n=ri(0,36);
  const gano=ap.gana(n, plenoNum);
  const pago=gano?monto*ap.pago:0;
  const neto=pago-monto;
  E.personal.bolsillo=Math.max(0, (E.personal.bolsillo||0)+neto);
  E.personal.ruletaHist=E.personal.ruletaHist||[];
  E.personal.ruletaHist.unshift({n:n,color:colorRuleta(n),gano:gano,neto:neto});
  if(E.personal.ruletaHist.length>14) E.personal.ruletaHist.length=14;
  return {n:n, color:colorRuleta(n), gano:gano, pago:pago, neto:neto};
}

/* ---------- corrupción: desviar fondos del club ---------- */
function desviarFondos(monto){
  if(typeof bolsilloDT==="function") bolsilloDT();
  if(!E.personal) E.personal={};
  if(typeof E.personal.bolsillo!=="number" || isNaN(E.personal.bolsillo)) E.personal.bolsillo=0;
  if(!E.flags) E.flags={};
  monto=Math.round(Math.min(monto, (E.plata||0)*0.6));
  if(monto<=0){ if(typeof aviso==="function") aviso("No hay caja del club para desviar."); return; }
  E.plata=Math.max(0, E.plata-monto);
  E.personal.bolsillo=(E.personal.bolsillo||0)+monto;
  E.flags.desfalco=(E.flags.desfalco||0)+monto;
  E.ind.riesgo=clamp(E.ind.riesgo+Math.round(5+monto/60),0,100);
  aplicarRep({credibilidad:-3});
  notificar({t:"Metiste mano a la caja",tipo:"malo",
    d:"Desviaste "+plata(monto)+" de la tesorería del club a tu bolsillo. Total desviado: "+plata(E.flags.desfalco)+
      ". Sube el riesgo institucional; si te auditan, se pudre. Puedes blanquearlo con el Proceso de Redención en Finanzas."});
  if(typeof redesReaccion==="function"){}   // el desvío es secreto; Plop estalla al auditar
  guardar();
}
/* chequeo semanal: cuanto más desviaste y menos credibilidad, más chance de auditoría */
function chequearDesfalco(){
  if(!E || !E.flags || !E.flags.desfalco || E.flags.desfalco<=0) return;
  if(E.flags.investigacionAbierta) return;
  const p=clamp(E.flags.desfalco/1400 + (60-E.rep.credibilidad)/320, 0.015, 0.5);
  if(Math.random()<p){
    E.flags.investigacionAbierta=true;
    if(!E.decPend.some(x=>x.id==="enc_investigacion_dirigencial") && !E.decHechas["enc_investigacion_dirigencial_"+E.anio]){
      E.decPend.push({id:"enc_investigacion_dirigencial",clave:"enc_investigacion_dirigencial_"+E.anio,peso:"alto"});
    }
    notificar({t:"Auditoría en marcha",tipo:"malo",
      d:"Saltaron irregularidades en la tesorería. Hay una investigación abierta sobre los fondos desviados. Tienes que responder."});
    if(typeof redesReaccion==="function") redesReaccion("desfalco",{monto:E.flags.desfalco});
  }
}
/* ---------- redención ---------- */
function procesoRedencion(tipo){
  const d=E.flags.desfalco||0; if(d<=0) return;
  if(tipo==="devolver"){
    const costo=Math.round(d*1.2);
    const dePersonal=Math.min(E.personal.bolsillo, costo);
    E.personal.bolsillo-=dePersonal;
    const resto=costo-dePersonal;
    if(resto>0) E.plata=Math.max(0,E.plata-resto);
    E.flags.desfalco=0; E.flags.investigacionAbierta=false;
    E.ind.riesgo=clamp(E.ind.riesgo-14,0,100);
    aplicarRep({credibilidad:8,publica:3}); aplicarGrupos({directorio:8});
    notificar({t:"Devolviste los fondos",tipo:"bueno",
      d:"Restituiste "+plata(costo)+" (lo desviado + 20% de recargo administrativo). Se cierra la investigación, baja el riesgo y recuperas algo de credibilidad."});
  } else { /* donaciones comunitarias + bajar el perfil */
    const costo=Math.round(d*0.9);
    E.plata=Math.max(0,E.plata-costo);
    E.flags.desfalco=0; E.flags.investigacionAbierta=false;
    E.ind.riesgo=clamp(E.ind.riesgo-8,0,100);
    aplicarRep({publica:6,credibilidad:4}); aplicarGrupos({comunidad:14,socios:6});
    notificar({t:"Lavaste la culpa con obras",tipo:"neutro",
      d:"Canalizaste "+plata(costo)+" en donaciones comunitarias y bajaste el perfil. La comunidad lo agradece y la investigación se diluye, aunque el fantasma queda dando vueltas."});
  }
  guardar();
}

/* ============================================================
   UI
   ============================================================ */
function pintarHistRuleta(c){
  const h=E.personal.ruletaHist||[];
  if(!h.length) return;
  const fila=el("div","ruleta-hist");
  h.slice(0,12).forEach(x=>{
    const s=el("span","chip-n "+x.color,String(x.n));
    fila.appendChild(s);
  });
  c.appendChild(fila);
}
/* ---------- tragamonedas (temática fútbol; la casa gana a la larga, RTP ~88%) ---------- */
var TRAGA_SIMBOLOS=[
  {s:"⚽",w:6,x3:5},   {s:"👟",w:5,x3:6},   {s:"🥅",w:4,x3:9},
  {s:"🧤",w:3,x3:14},  {s:"🔥",w:2,x3:24},  {s:"🏆",w:1,x3:75}
];
function tragaGirarUno(){
  const tot=TRAGA_SIMBOLOS.reduce((s,x)=>s+x.w,0);
  let r=Math.random()*tot;
  for(const x of TRAGA_SIMBOLOS){ if((r-=x.w)<0) return x; }
  return TRAGA_SIMBOLOS[0];
}
function girarTragamonedas(monto){
  if(typeof bolsilloDT==="function") bolsilloDT();
  if(!E.personal) E.personal={};
  if(typeof E.personal.bolsillo!=="number" || isNaN(E.personal.bolsillo)) E.personal.bolsillo=0;
  monto=Math.max(1,Math.min(Math.round(monto)||1,E.personal.bolsillo));
  const r=[tragaGirarUno(),tragaGirarUno(),tragaGirarUno()];
  let mult=0, linea="";
  if(r[0].s===r[1].s && r[1].s===r[2].s){ mult=r[0].x3; linea="¡TRIPLE "+r[0].s+"!"; }
  else if(r[0].s===r[1].s || r[1].s===r[2].s || r[0].s===r[2].s){ mult=1.2; linea="Par"; }
  const pago=Math.round(monto*mult);
  const neto=pago-monto;
  E.personal.bolsillo=Math.round((E.personal.bolsillo||0)-monto+pago);
  E.tragaHist=(E.tragaHist||[]); E.tragaHist.unshift(r.map(x=>x.s).join(" ")); if(E.tragaHist.length>8) E.tragaHist.pop();
  return { reels:r.map(x=>x.s), mult:mult, pago:pago, neto:neto, gano:neto>0, linea:linea, monto:monto };
}
function modalTragamonedas(){
  let monto=Math.max(2,Math.min(20,E.personal.bolsillo||0)), ultimo=null, girando=false;
  modal(box=>{
    const pintar=()=>{
      box.innerHTML="";
      box.appendChild(el("div","cab",'<span class="ic">🎰</span><span>Casino · tragamonedas</span>'));
      const c=el("div","cuerpo"); box.appendChild(c);
      c.appendChild(el("p","mini","Tres rodillos. Triple paga fuerte (🏆 hasta 75x), un par devuelve 1,2x. La casa gana a la larga. Bolsillo: <b>"+plata(E.personal.bolsillo||0)+"</b>."));
      const car=el("div","traga-car");
      car.style.cssText="display:flex;gap:8px;justify-content:center;font-size:44px;margin:6px 0;padding:10px;border-radius:10px;background:rgba(0,40,25,.18);border:1px solid rgba(255,255,255,.35)";
      (ultimo?ultimo.reels:["❔","❔","❔"]).forEach(s=>{ const d=el("div","",girando?"🎲":s); d.style.cssText="width:64px;text-align:center"; car.appendChild(d); });
      c.appendChild(car);
      if(E.tragaHist&&E.tragaHist.length) c.appendChild(el("p","mini","Últimas: "+E.tragaHist.slice(0,6).join("  ·  ")));
      const maxB=Math.max(1,E.personal.bolsillo||0);
      monto=Math.min(monto,maxB);
      c.appendChild(el("label","lb","Apuesta: <b>"+plata(monto)+"</b>"));
      const row=el("div"); row.style.cssText="display:flex;gap:8px;align-items:center";
      const sm=el("input"); sm.type="range"; sm.min=1; sm.max=maxB; sm.value=monto; sm.className="rango"; sm.style.flex="1";
      const nm=el("input"); nm.type="number"; nm.min=1; nm.max=maxB; nm.value=monto; nm.style.cssText="width:88px;padding:7px;border-radius:8px;border:1px solid rgba(0,0,0,.15)";
      const sync=v=>{ monto=Math.max(1,Math.min(Math.round(v)||1,maxB)); sm.value=monto; nm.value=monto; const b=c.querySelector(".lb b"); if(b) b.textContent=plata(monto); };
      sm.oninput=()=>sync(sm.value); nm.oninput=()=>sync(nm.value);
      row.appendChild(sm); row.appendChild(nm); c.appendChild(row);
      const bg=el("button","btn-aqua ancho verde"+((E.personal.bolsillo||0)<=0||girando?" gris":""),girando?"Girando…":"🎰 ¡Girar!");
      bg.disabled=(E.personal.bolsillo||0)<=0||girando;
      bg.onclick=()=>{
        if(girando||(E.personal.bolsillo||0)<=0) return;
        girando=true; pintar();
        let k=0; const iv=setInterval(()=>{ const ds=car.querySelectorAll("div"); ds.forEach(d=>d.textContent=elige(TRAGA_SIMBOLOS).s); k++; },90);
        setTimeout(()=>{ clearInterval(iv); ultimo=girarTragamonedas(monto); girando=false; guardar(); pintar(); },1400);
      };
      c.appendChild(bg);
      if(ultimo&&!girando){
        c.appendChild(el("div","resul "+(ultimo.gano?"bien":"mal"),
          ultimo.reels.join(" ")+" — "+(ultimo.mult>=3?("🎉 "+ultimo.linea+" Ganaste "+plata(ultimo.pago)+" (neto +"+plata(ultimo.neto)+")"):(ultimo.mult>1?("Par: recuperas "+plata(ultimo.pago)+" (neto +"+plata(ultimo.neto)+")"):("Nada. Perdiste "+plata(ultimo.monto)+".")))));
      }
      const br=el("button","btn-aqua ancho","🎡 Ir a la ruleta"); br.style.marginTop="8px"; br.onclick=()=>{ cerrarModal(); modalCasino(); }; c.appendChild(br);
      if((E.personal.bolsillo||0)<=0){ const bd=el("button","btn-aqua ancho rojo","Meter mano a la caja del club"); bd.style.marginTop="6px"; bd.onclick=()=>{ cerrarModal(); modalDesviar(); }; c.appendChild(bd); }
      const x=el("button","btn-aqua ancho gris","Salir del casino"); x.style.marginTop="6px"; x.onclick=()=>{ cerrarModal(); render(); }; c.appendChild(x);
    };
    pintar();
  });
}
