  cartel(X(-5.3),Y(8),tc,17*pxm,true); cartel(X(-5.3),Y(43),tc,17*pxm,true);
  cartel(X(109.5),Y(8),tc,17*pxm,true); cartel(X(109.5),Y(43),tc,17*pxm,true);
