  ctx.fillStyle="rgba(235,240,245,.10)"; ctx.fillRect(Math.min(xa,xb),ya,Math.abs(xb-xa),yb-ya);
  ctx.strokeStyle="rgba(235,240,245,.55)"; ctx.lineWidth=Math.max(0.6,S*0.05);
