  for(let d=0;d<=prof+0.01;d+=paso){ const xx=C.sx(gx+sg*d); ctx.moveTo(xx,ya); ctx.lineTo(xx+(bolsa?sg*S*bolsa*0.5:0),C.sy(34)); ctx.lineTo(xx,yb); }
