/* piel y pelo: fijos por jugador (no cambian de un cuadro a otro) */
var CV_PIEL=["#f1c9a5","#e0ac7e","#c68b5c","#a86e42","#8a5634","#5e3a22"], CV_PELO=["#1b1410","#2e2016","#4a3020","#6b4a2a","#c9a15a","#101010","#3a2a20"];
