  ctx.fillStyle="rgba(0,0,0,"+(0.38-Math.min(0.2,z*0.03))+")";
  ctx.beginPath(); ctx.ellipse(x+z*S*0.45+S*0.12,y+z*S*0.35+S*0.1,S*0.28,S*0.2,0,0,Math.PI*2); ctx.fill();
