/* ---------- generar un tuit del contexto, con estado real ---------- */
function plopVocesPara(ctx){
  const tono=(typeof tonoDeCtx==="function")?tonoDeCtx(ctx):"neutro";
  let voces;
  if(tono==="bueno") voces=["exaltado","tierno","dato","serio","cotidiano"];
  else if(tono==="malo") voces=["amargado","ironico","rival","exaltado","tierno","serio"];
  else voces=["ironico","dato","amargado","cotidiano","analitico","serio","tierno"];
  return voces;
}
function generarPlop(ctx){
  try{
    const gen=PLOP_GRAM[ctx]; if(!gen) return null;
    const s=plopEstado();
    const voces=plopVocesPara(ctx);
    /* elegir una cuenta cuya voz calce con el tono, evitando repetir la última */
    const cand=[]; voces.forEach(function(v){ (PLOP_POR_VOZ[v]||[]).forEach(function(h){ cand.push({h:h,v:v}); }); });
    if(!cand.length) return null;
    const pick=cand[Math.floor(Math.random()*cand.length)];
    let txt=gen(pick.v, s);
    if(!txt) return null;
    txt=limpiaEsp(txt);
    const m=plopMem();
    if(m.hist.indexOf(txt)>=0) return null; /* no repetir textual reciente */
    plopRecuerda(txt);
    return {ctx:ctx, quien:pick.h, txt:txt};
  }catch(e){ return null; }
}

/* ---------- HOOK: envolver tuitDeCtx para mezclar generado + aprobado ---------- */
(function(){
  if(typeof tuitDeCtx!=="function" || tuitDeCtx._gen) return;
  const base=tuitDeCtx;
  tuitDeCtx=function(ctx){
    /* 55%: intenta generar con estado real; si falla, cae al pool aprobado */
    if(PLOP_GRAM[ctx] && Math.random()<0.55){
      const g=generarPlop(ctx);
      if(g) return g;
    }
    const b=base(ctx);
    if(b) return b;
    /* contexto sin pool aprobado (ej: tiroLibre, lesion_grave): generar siempre */
    if(PLOP_GRAM[ctx]) return generarPlop(ctx);
    return null;
  };
  tuitDeCtx._gen=true;
})();

/* ============================================================
   HILOS: las cuentas se responden entre ellas. Cuando un hincha postea en el
   feed, otra cuenta (con voz distinta) le tira 1-2 réplicas cortas según el
   tono. Se cuelga de postProc (que ya guarda item.hilo, renderizado con ↳).
   ============================================================ */
var PLOP_REPLICAS={
  bueno:{
    exaltado:["ESO WN 🔥","VAMOS QUE SE PUEDE 🙌","ARRIBA CARAJO","así se habla po"],
    ironico:["por fin alguien lo dice","no lo hubiera dicho mejor ksks","tomá pa vos"],
    amargado:["ojalá dure","no me ilusiono igual","a ver cuánto aguanta"],
    tierno:["ay qué lindo hijito 🥺","así me gusta","el corazón contento"],
    dato:["+1, los números lo respaldan","tal cual, dato firme"],
    rival:["disfruten mientras dure 😌","ya nos va a tocar"],
    cotidiano:["lo grité en la micro jaja","me hiciste el día"],
    serio:["comparto el análisis.","coincido, fue clave."]
  },
  malo:{
    exaltado:["ME CARGA ESTA WEA 😡","NO PUEDE SER PO","ya fue, ya fue"],
    ironico:["clásico de la casa","sorpresa cero ksks","lo veía venir"],
    amargado:["lo dije hace rato","este club me va a matar","siempre lo mismo"],
    tierno:["ay no hijito 😔","qué pena me da"],
    dato:["los números venían avisando","-moral, anoten"],
    rival:["gracias, se agradece 🤣","los amo por esto"],
    cotidiano:["me arruinaron el día","chao finde"],
    serio:["hay que corregir esto.","preocupa, sí."]
  },
  neutro:{
    ironico:["ver pa creer","mmm veremos","ni fu ni fa"],
    amargado:["a mí no me convence","tengo mis dudas"],
    dato:["dato para la mesa","anotado."],
    cotidiano:["jaja tal cual","lo mismo pienso"],
    serio:["punto válido."]
  }
};
function plopReplica(tono, evitar){
  const banco=PLOP_REPLICAS[tono]||PLOP_REPLICAS.neutro;
  const voces=Object.keys(banco); if(!voces.length) return null;
  for(let i=0;i<6;i++){
    const v=voces[Math.floor(Math.random()*voces.length)];
    const cuentas=(PLOP_POR_VOZ[v]||[]).filter(function(h){ return h!==evitar; });
    if(!cuentas.length) continue;
    const h=cuentas[Math.floor(Math.random()*cuentas.length)];
    const opts=banco[v]; const txt=opts[Math.floor(Math.random()*opts.length)];
    return {autor:h, texto:txt};
  }
  return null;
}
(function(){
  if(typeof postProc!=="function" || postProc._hilo) return;
  const base=postProc;
  postProc=function(autor,tipo,texto,tono,extra){
    const item=base(autor,tipo,texto,tono,extra);
    try{
      if(item && tipo==="hincha" && Math.random()<0.38){
        item.hilo=item.hilo||[];
        const r1=plopReplica(item.tono, autor);
        if(r1){ item.hilo.push({autor:r1.autor, texto:r1.texto, fecha:"ahora"});
          if(Math.random()<0.35){
            const r2=plopReplica(item.tono, r1.autor);
            if(r2 && r2.autor!==r1.autor) item.hilo.push({autor:r2.autor, texto:r2.texto, fecha:"ahora"});
          }
          item.replies=(item.replies||0)+item.hilo.length;
        }
      }
    }catch(e){}
    return item;
  };
  postProc._hilo=true;
})();

/* ============================================================
   MEMORIA ENTRE PARTIDOS: las cuentas se acuerdan de la racha y del
   resultado anterior. Al cerrar un partido se registra el resultado y, si hay
   un quiebre de racha (venías perdiendo y ganaste, se cortó la buena, etc.),
   una cuenta lo comenta en el feed con el "callback".
   ============================================================ */
function plopRachaCola(mem, tipo){
  let n=0; for(let i=mem.racha.length-1;i>=0;i--){ if(mem.racha[i]===tipo) n++; else break; } return n;
}
/* devuelve {autor,texto,tono} de callback usando la racha PREVIA, o null */
function plopFraseMemoria(mem, outcome, res){
  try{
    const rival=(res&&res.rival)||"el rival";
    const nL=plopRachaCola(mem,"L"), nW=plopRachaCola(mem,"W"), nD=plopRachaCola(mem,"D");
    let txt=null, tono="neutro", voz="amargado";
    if(outcome==="W" && nL>=2){ txt=P1(["veníamos de "+nL+" caídas seguidas y hoy ganamos. respira el barrio 😮‍💨","después de "+nL+" fechas funándolos, hoy toca callar bocas. incluida la mía","de "+nL+" derrotas al hilo a esta alegría. el fútbol te devuelve la mano"]); tono="bueno"; voz="viejo_del_bar"; }
    else if(outcome==="L" && nW>=2){ txt=P1(["se cortó la buena de "+nW+" triunfos. era hora, no nos íbamos a acostumbrar a ser felices","veníamos de "+nW+" al hilo y contra "+rival+" se acabó el sueño. típico","adiós rachita de "+nW+". lindo mientras duró 🫠"]); tono="malo"; voz="socio_enojado"; }
    else if(outcome==="W" && nW>=2){ txt=P1(["y van "+(nW+1)+" seguidas 🔥 no me hablen que estoy en una nube",""+(nW+1)+" triunfos al hilo. ¿esto es lo que se siente ser grande?","racha de "+(nW+1)+". que no despierte nadie"]); tono="bueno"; voz="albo_insomne"; }
    else if(outcome==="L" && nL>=2){ txt=P1(["otra más. van "+(nL+1)+" sin ganar y ya no sé si reír o llorar",""+(nL+1)+" derrotas seguidas. esto ya no es mala racha, es estilo de vida","el DT habla de proceso hace "+(nL+1)+" fechas. el proceso es de duelo"]); tono="malo"; voz="viejo_del_bar"; }
    else if(outcome==="D" && (nL>=2||nD>=2)){ txt=P1(["empatamos. ni ganamos ni perdemos, el limbo eterno de este club","otro empate. coleccionamos puntitos como quien junta monedas de $10"]); tono="neutro"; voz="garrafal_cl"; }
    if(!txt) return null;
    const h="@"+voz;
    return {autor:(PLOP_PERSONAS[h]?h:"@viejo_del_bar"), texto:txt, tono:tono};
  }catch(e){ return null; }
}
function plopRegistrarResultado(res){
  try{
    if(!res || (typeof E==="undefined")||!E || (E.anio||2026)<2008) return null;
    const mem=plopMem();
    const outcome=res.yo>res.otro?"W":(res.yo<res.otro?"L":"D");
    const callback=plopFraseMemoria(mem, outcome, res);   /* usa la racha PREVIA */
    mem.racha.push(outcome); if(mem.racha.length>8) mem.racha.shift();
    var riv=res.rival||(mem.ultRes&&(mem.ultRes.riv||mem.ultRes.rival))||"";
    mem.ultRes=Object.assign({}, mem.ultRes||{}, {
      o:outcome, marcador:res.yo+"-"+res.otro, rival:riv, riv:riv,
      yo:res.yo, otro:res.otro, gano:outcome==="W", empate:outcome==="D"
    });
    return callback;
  }catch(e){ return null; }
}
/* engancharse al cierre de partido (persistirTicker corre en cerrarPartido) */
(function(){
  if(typeof persistirTicker!=="function" || persistirTicker._mem) return;
  const base=persistirTicker;
  persistirTicker=function(P, res){
    base(P, res);
    try{
      const r=res?{yo:res.yo, otro:res.otro, rival:(P&&P.part&&P.part.rivalNombre)||"el rival"}:null;
      const cb=plopRegistrarResultado(r);
      if(cb && typeof postProc==="function"){
        postProc(cb.autor, "hincha", cb.texto, cb.tono, {fecha:"fecha "+((E.temporada&&E.temporada.pj)||""), postPartido:true, memoria:true});
      }
    }catch(e){}
  };
  persistirTicker._mem=true;
})();

;
