  ta.pj++; tb.pj++; ta.gf+=ga; ta.gc+=gb; tb.gf+=gb; tb.gc+=ga;
  if(ga>gb){ ta.pg++; ta.pts+=pv; tb.pp++; }
  else if(ga<gb){ tb.pg++; tb.pts+=pv; ta.pp++; }
