/* ==== js/dev-editor.js ==== */
"use strict";
/* ============================================================
   FUTBOLINI · dev-editor.js  (motor de edición · parte 3 de 3)
   EL "WORDPRESS" DE FUTBOLINI. Panel para editar clubes y ligas sin abrir
   un solo archivo .js, con medidor de rigor al lado.

   Cómo entrar: Ajustes → Modo desarrollador → clave → "Editor de contenido".

   Cómo funciona (importante):
   - Lo que editas se aplica EN VIVO sobre los mapas del juego y queda
     guardado como PARCHE en localStorage (no toca ningún archivo).
   - Cuando te gusta, "Exportar" te da un .js listo para dejar en js/ y
     cargar en index.html. Eso lo hace permanente y versionable en git.
   - Así nunca se pisa el trabajo de nadie: el parche es aparte.

   Aislado: envuelve vistaAjustes (patrón de epoca-intro.js). Cargar al final.
   ============================================================ */
(function(){
  if(typeof vistaAjustes!=="function" || vistaAjustes._editor8) return;
  var orig=vistaAjustes;
  vistaAjustes=function(host){ orig.apply(this,arguments); try{ _pintarAccesoEditor(host); }catch(e){ console.error("editor:",e); } }; /* 7.9027: respeta la ventana */
  vistaAjustes._editor8=true;

  var LLAVE_PARCHE="futbolini_dev_parche";
  var TAB="rigor", CLUB_SEL=null, LIGA_SEL=null;

  /* ---------- parche persistente ---------- */
  function parcheLeer(){
    try{ var s=localStorage.getItem(LLAVE_PARCHE); return s?JSON.parse(s):{}; }catch(e){ return {}; }
  }
  function parcheGuardar(p){
    try{ localStorage.setItem(LLAVE_PARCHE, JSON.stringify(p)); return true; }catch(e){ return false; }
  }
  function parcheSet(id,campo,valor){
    var p=parcheLeer(); if(!p[id]) p[id]={};
    p[id][campo]=valor; parcheGuardar(p); return p;
  }
  function parcheBorrar(){ try{ localStorage.removeItem(LLAVE_PARCHE); }catch(e){} }
  function parcheCuenta(){
    var p=parcheLeer(), n=0;
    Object.keys(p).forEach(function(id){ n+=Object.keys(p[id]||{}).length; });
    return n;
  }
  /* al cargar la página, re-aplicar lo editado */
  try{
    var p0=parcheLeer();
    if(Object.keys(p0).length && typeof aplicarParcheClubes==="function") aplicarParcheClubes(p0);
  }catch(e){}

  /* ---------- acceso desde Ajustes ---------- */
  function _pintarAccesoEditor(host){
    if(typeof devOn!=="function" || !devOn()) return;
    var v=host||document.getElementById("vista"); if(!v) return;
    if(v.querySelector(".dev-editor-acceso")) return;
    var p=panel("Editor de contenido","🧱","agua");
    p.classList.add("dev-editor-acceso");
    p.cuerpo.appendChild(el("p","mini",
      "Edita clubes, ligas y datos sin tocar archivos. Mide el <b>rigor</b> de cada club contra Colo-Colo y te dice qué falta. Lo editado queda como parche y se exporta a un .js."));
    var n=parcheCuenta();
    if(n) p.cuerpo.appendChild(el("p","mini","Tienes <b>"+n+"</b> campo(s) editados sin exportar."));
    var b=el("button","btn-aqua ancho verde","🧱 Abrir editor");
    b.onclick=function(){ abrirEditorContenido(); };
    p.cuerpo.appendChild(b);
    v.appendChild(p);
  }

  /* ---------- utilidades UI ---------- */
  function barraPct(pct){
    var c = pct>=95?"#2fa84f" : pct>=75?"#d68a1f" : "#c0392b";
    return '<div class="dev-barra"><i style="width:'+pct+'%;background:'+c+'"></i></div>';
  }
  function chip(txt,cls){ return el("span","dev-chip"+(cls?" "+cls:""),txt); }

  /* ---------- el editor ---------- */
  function abrirEditorContenido(){
    modal(function(box){
      box.classList.add("dev-editor");
      box.appendChild(el("div","cab",'<span class="ic">🧱</span><span>Editor de contenido · Futbolini</span>'));
      var c=el("div","cuerpo"); box.appendChild(c);

      var tabs=el("div","fichas dev-tabs");
      [["rigor","📏 Rigor"],["club","🏟️ Club"],["nuevo","➕ Nuevo"],["liga","🏆 Liga"],["alma","📚 Alma"],["doctor","🩺 Doctor"],["exportar","💾 Exportar"]].forEach(function(t){
        var b=el("button","ficha",t[1]);
        b.setAttribute("aria-pressed",TAB===t[0]?"true":"false");
        b.onclick=function(){ TAB=t[0]; pintar(); };
        tabs.appendChild(b);
      });

      var cont=el("div","dev-cont");
      function pintar(){
        c.innerHTML=""; c.appendChild(tabs);
        Array.prototype.forEach.call(tabs.children,function(b,i){
          b.setAttribute("aria-pressed",["rigor","club","nuevo","liga","alma","doctor","exportar"][i]===TAB?"true":"false");
        });
        cont.innerHTML=""; c.appendChild(cont);
        if(TAB==="rigor") pintarRigor(cont,pintar);
        else if(TAB==="club") pintarClub(cont,pintar);
        else if(TAB==="nuevo") pintarNuevo(cont,pintar);
        else if(TAB==="liga") pintarLiga(cont,pintar);
        else if(TAB==="alma"){ if(typeof devPintarCobertura==="function") devPintarCobertura(cont); else cont.appendChild(el("p","mini","Analizador de contenido no cargó.")); }
        else if(TAB==="doctor"){ if(typeof devPintarDoctor==="function") devPintarDoctor(cont); else cont.appendChild(el("p","mini","Doctor no cargó.")); }
        else pintarExportar(cont,pintar);
        var x=el("button","btn-aqua ancho","Cerrar"); x.style.marginTop="10px";
        x.onclick=cerrarModal; c.appendChild(x);
      }
      pintar();
    },{clase:"ancho"});
  }

  /* ---------- pestaña RIGOR ---------- */
  function pintarRigor(cont,repintar){
    cont.appendChild(el("p","mini",
      "Cada club se mide contra <b>"+DEV_CLUB_REF+"</b>: si tiene los mismos campos llenos, va 100%. "+
      "Los datos que <i>a propósito</i> no existen (sin fuente) no cuentan en contra."));
    var busca=el("input","dev-in"); busca.type="search"; busca.placeholder="Filtrar por nombre o ID…"; busca.style.margin="6px 0";
    var solo=el("label","mini"); var chk=el("input"); chk.type="checkbox";
    solo.appendChild(chk); solo.appendChild(document.createTextNode(" solo los que no llegan a 100%"));
    var host=el("div");
    function dibujar(){
      host.innerHTML="";
      var q=(busca.value||"").toLowerCase().trim();
      var todo=auditarTodo();
      todo.forEach(function(r){
        var p=el("div","dev-liga");
        var cab=el("div","dev-liga-cab");
        var tit=el("b"); tit.textContent=r.nombre||"";
        var mini=el("span","mini"); mini.textContent=" ["+r.era+"] · "+r.clubes+" clubes";
        var pct=el("b","dev-pct"); pct.textContent=r.pct+"%";
        cab.appendChild(tit); cab.appendChild(mini); cab.appendChild(pct);
        p.appendChild(cab);
        p.appendChild(el("div",null,barraPct(r.pct)));
        var grid=el("div","dev-grid");
        r.fichas.forEach(function(f){
          if(chk.checked && f.pct>=100) return;
          var nom=_nombreDe(f.id)||"";
          if(q && (f.id+" "+nom).toLowerCase().indexOf(q)<0) return;
          var b=el("button","dev-club"+(f.pct>=100?" ok":(f.pct>=75?" medio":" mal")));
          var ib=el("b"); ib.textContent=f.id; b.appendChild(ib);
          var sp=el("span"); sp.textContent=f.pct+"%"; b.appendChild(sp);
          b.title=nom+(f.faltanReq.length?(" · Falta: "+f.faltanReq.map(function(x){return x.n;}).join(", ")):" · Completo");
          b.onclick=function(){ CLUB_SEL=f.id; TAB="club"; repintar(); };
          grid.appendChild(b);
        });
        if(!grid.children.length) return;
        p.appendChild(grid);
        host.appendChild(p);
      });
    }
    busca.oninput=dibujar; chk.onchange=dibujar;
    cont.appendChild(busca); cont.appendChild(solo); cont.appendChild(host); dibujar();
  }

  /* ---------- pestaña CLUB ---------- */
  function pintarClub(cont,repintar){
    /* selector */
    var sel=el("select","dev-select");
    var vistos={};
    devErasLiga().forEach(function(era){
      var og=document.createElement("optgroup");
      og.label=((typeof ERA!=="undefined"&&ERA[era]&&ERA[era].n)||era)+" ["+era+"]";
      devIdsLiga(era).forEach(function(id){
        if(vistos[id]) return; vistos[id]=1;
        var o=document.createElement("option"); o.value=id;
        var a=auditarClub(id);
        o.textContent=id+" · "+((_nombreDe(id))||"")+"  ("+a.pct+"%)";
        og.appendChild(o);
      });
      if(og.children.length) sel.appendChild(og);
    });
    try{
      var idsP=Object.keys(parcheLeer()||{});
      var ogP=document.createElement("optgroup"); ogP.label="Parche (nuevos / editados)";
      idsP.forEach(function(id){
        if(vistos[id]) return; vistos[id]=1;
        var o=document.createElement("option"); o.value=id;
        o.textContent=id+" · "+((_nombreDe(id))||"(nuevo)")+"  (parche)";
        ogP.appendChild(o);
      });
      if(ogP.children.length) sel.appendChild(ogP);
    }catch(e){}
    if(!CLUB_SEL) CLUB_SEL=sel.value||"CC";
    sel.value=CLUB_SEL;
    sel.onchange=function(){ CLUB_SEL=sel.value; repintar(); };
    var busca=el("input","dev-in"); busca.type="search"; busca.placeholder="Buscar en el selector…";
    busca.style.marginBottom="6px";
    busca.oninput=function(){
      var q=(busca.value||"").toLowerCase();
      Array.prototype.forEach.call(sel.querySelectorAll("option"),function(o){
        o.hidden=!!q && (o.textContent||"").toLowerCase().indexOf(q)<0;
      });
    };
    var nav=el("div","dev-acc");
    nav.style.margin="4px 0 8px";
    function mover(delta){
      var ops=sel.querySelectorAll("option:not([hidden])");
      var idx=-1;
      for(var i=0;i<ops.length;i++) if(ops[i].value===sel.value){ idx=i; break; }
      var n=ops[(idx+delta+ops.length)%ops.length];
      if(n){ sel.value=n.value; CLUB_SEL=n.value; repintar(); }
    }
    var bp=el("button","btn-aqua chico gris","← Anterior"); bp.onclick=function(){ mover(-1); };
    var bn=el("button","btn-aqua chico gris","Siguiente →"); bn.onclick=function(){ mover(1); };
    nav.appendChild(bp); nav.appendChild(bn);
    nav.appendChild(el("span","mini","  Alt+← / Alt+→"));
    cont.appendChild(busca);
    cont.appendChild(sel);
    cont.appendChild(nav);
    if(!cont._navKeys){
      cont._navKeys=true;
      var host=cont.closest(".dev-editor")||document;
      host.addEventListener("keydown", function(ev){
        if(!ev.altKey) return;
        if(ev.key==="ArrowLeft"){ ev.preventDefault(); mover(-1); }
        if(ev.key==="ArrowRight"){ ev.preventDefault(); mover(1); }
      });
    }

    var a=auditarClub(CLUB_SEL);
    var cab=el("div","dev-club-cab");
    var nb=el("b"); nb.textContent=_nombreDe(CLUB_SEL)||CLUB_SEL;
    var idsp=el("span","mini"); idsp.textContent=" "+CLUB_SEL+" ";
    var pct=el("b","dev-pct"); pct.textContent=a.pct+"%";
    cab.appendChild(nb); cab.appendChild(idsp); cab.appendChild(pct);
    cab.appendChild(el("div",null,barraPct(a.pct)));
    cont.appendChild(cab);
    if(a.faltanReq && a.faltanReq.length){
      var jump=el("p","mini"); jump.appendChild(document.createTextNode("Falta: "));
      a.faltanReq.forEach(function(x,i){
        var s=el("button","btn-aqua chico gris"); s.textContent=x.n||x.k||"?"; s.style.margin="0 4px 4px 0";
        s.onclick=function(){
          var labs=cont.querySelectorAll(".dev-lab b");
          for(var j=0;j<labs.length;j++){
            if((labs[j].textContent||"")=== (x.n||"")){
              var wrap=labs[j].closest(".dev-campo"); if(wrap) wrap.scrollIntoView({block:"center"});
              var inp=wrap && wrap.querySelector("input,textarea"); if(inp) inp.focus();
              break;
            }
          }
        };
        jump.appendChild(s);
      });
      cont.appendChild(jump);
    }
    if(a.justificados&&a.justificados.length){
      a.justificados.forEach(function(j){
        cont.appendChild(el("p","mini dev-justi","🤍 <b>"+j.n+"</b> no se llena a propósito: "+j.motivo));
      });
    }

    DEV_GRUPOS.forEach(function(g){
      var campos=ESQUEMA_CLUB.filter(function(x){ return x.grupo===g.k; });
      if(!campos.length) return;
      cont.appendChild(el("h3","sub",g.ic+" "+g.n));
      campos.forEach(function(campo){ cont.appendChild(_filaCampo(campo,CLUB_SEL,repintar)); });
    });
  }

  function _nombreDe(id){
    try{
      if(typeof CLUB_INFO_2026!=="undefined" && CLUB_INFO_2026[id] && CLUB_INFO_2026[id].n) return CLUB_INFO_2026[id].n;
      if(typeof CLUB_INFO!=="undefined" && CLUB_INFO[id] && CLUB_INFO[id].n) return CLUB_INFO[id].n;
    }catch(e){}
    return null;
  }

  /* una fila editable según el tipo del campo */
  function _filaCampo(campo,id,repintar){
    var val=null; try{ val=campo.get(id); }catch(e){}
    var fila=el("div","dev-campo"+(val==null&&campo.req?" falta":""));
    var lab=el("label","dev-lab");
    lab.innerHTML="<b>"+campo.n+"</b> <span class='mini'>"+campo.donde+"</span>"+(val==null&&campo.req?" <span class='dev-falta'>falta</span>":"");
    fila.appendChild(lab);

    if(campo.tipo==="ro" || typeof campo.set!=="function"){
      fila.appendChild(el("div","mini dev-ro", val==null?"—":"(solo lectura) "+_resumen(val)));
      return fila;
    }
    var entrada, esJson=(campo.tipo==="json"||campo.tipo==="lista");
    if(esJson){
      entrada=el("textarea","dev-ta");
      entrada.rows=(campo.tipo==="lista")?2:5;
      entrada.value = val==null?"":JSON.stringify(val,null,1);
      entrada.placeholder = campo.tipo==="lista"?'["UCH","UC"]':"{ }";
    }else if(campo.tipo==="parrafo"){
      entrada=el("textarea","dev-ta"); entrada.rows=3; entrada.value=val==null?"":String(val);
    }else{
      entrada=el("input","dev-in");
      entrada.type=(campo.tipo==="numero")?"number":"text";
      entrada.value=val==null?"":String(val);
    }
    fila.appendChild(entrada);

    var acc=el("div","dev-acc");
    if(esJson && !String(entrada.value||"").trim()){
      var bp=el("button","btn-aqua chico gris","Plantilla");
      bp.onclick=function(){
        if(campo.k==="ind") entrada.value=JSON.stringify({plantel:50,moral:50,hinchada:50,socios:40,cantera:45,estadio:45,prestigio:40,riesgo:50},null,1);
        else if(campo.k==="caja") entrada.value=JSON.stringify({plata:80,deuda:40},null,1);
        else if(campo.k==="colores") entrada.value='["#111111","#ffffff"]';
        else if(campo.tipo==="lista") entrada.value='["CC"]';
        else entrada.value="{ }";
        entrada.focus();
      };
      acc.appendChild(bp);
    }
    var bg=el("button","btn-aqua chico verde","Guardar");
    var msg=el("span","mini dev-msg","");
    bg.onclick=function(){
      var nuevo;
      if(esJson){
        var t=entrada.value.trim();
        if(!t){ nuevo=null; }
        else {
          try{ nuevo=JSON.parse(t); }
          catch(err){ msg.textContent="❌ JSON inválido: "+err.message; msg.className="mini dev-msg mal"; return; }
        }
      }else if(campo.tipo==="numero"){
        if(!String(entrada.value).trim()){ nuevo=null; }
        else { nuevo=parseInt(entrada.value,10); if(isNaN(nuevo)){ msg.textContent="❌ no es número"; return; } }
      }else{
        nuevo=entrada.value.trim();
        if(!nuevo) nuevo=null;
      }
      try{ campo.set(id,nuevo); }catch(err){ msg.textContent="❌ "+err.message; return; }
      parcheSet(id,campo.k,nuevo);
      msg.textContent="✅ guardado (parche)"; msg.className="mini dev-msg bien";
      if(typeof aviso==="function") aviso("Guardado: "+campo.n+" de "+id);
      setTimeout(repintar,350);
    };
    acc.appendChild(bg); acc.appendChild(msg);
    fila.appendChild(acc);
    entrada.addEventListener("input", function(){ entrada.dataset.dirty="1"; });
    entrada.addEventListener("blur", function(){
      if(entrada.dataset.dirty==="1"){ entrada.dataset.dirty=""; bg.click(); }
    });
    return fila;
  }
  function _resumen(v){
    try{
      if(Array.isArray(v)) return v.length+" entrada(s)";
      if(typeof v==="object") return Object.keys(v).join(", ").slice(0,80);
      return String(v).slice(0,80);
    }catch(e){ return "—"; }
  }

  /* ---------- pestaña NUEVO (formulario + PEGAR) ---------- */
  function pintarNuevo(cont,repintar){
    cont.appendChild(el("p","mini","Crea o <b>mejora</b> un club. Si el ID ya existe, se actualiza (no se duplica). Si cambia el nombre, también se espeja en la ficha 1991. El HTML se recorta. Si pones liga, el club aparece en el selector."));
    var grid=el("div","pegar-grid");
    function campo(lbl,ph,cls){
      var lab=el("label"); lab.textContent=lbl;
      var i=el("input","dev-in"); i.placeholder=ph||""; if(cls) lab.className=cls;
      lab.appendChild(i); grid.appendChild(lab); return i;
    }
    var iId=campo("ID (2-6 letras)","SMO");
    var iNom=campo("Nombre","Club de ejemplo");
    var iCiu=campo("Ciudad","Santiago");
    var iFund=campo("Fundación","1909"); iFund.type="number";
    var iDt=campo("DT","Cuerpo técnico");
    var iLiga=campo("Liga (2026, 2026b, 2026c, 1991, arg2026…)","2026");
    iLiga.value="2026";
    var labD=el("label","span2"); labD.textContent="Descripción";
    var iDesc=el("textarea","dev-ta"); iDesc.rows=2; iDesc.placeholder="Quién es este club, en una frase.";
    labD.appendChild(iDesc); grid.appendChild(labD);
    var labS=el("label","span2"); labS.textContent="Situación (por qué dirigir acá)";
    var iSit=el("textarea","dev-ta"); iSit.rows=2; iSit.placeholder="Por qué el jugador elige este club.";
    labS.appendChild(iSit); grid.appendChild(labS);
    cont.appendChild(grid);

    var det=el("details","pegar-adv");
    var sum=el("summary"); sum.textContent="O pega un bloque de texto (PEGAR)";
    det.appendChild(sum);
    var ta=el("textarea","dev-ta"); ta.rows=8;
    ta.value=(typeof PEGAR_CLUB_EJEMPLO==="function")?PEGAR_CLUB_EJEMPLO():"ID: XXX\nnombre: Club de ejemplo";
    det.appendChild(ta);
    det.appendChild(el("p","mini","Formato: ID / nombre / ciudad / fund / dt / liga / desc / situacion. Una clave por línea."));
    cont.appendChild(det);

    var msg=el("p","mini","");
    var bg=el("button","btn-aqua ancho verde","Crear / mejorar club");
    bg.style.marginTop="8px";
    function bloqueDeForm(){
      var id=(iId.value||"").trim(), nom=(iNom.value||"").trim();
      if(!id&&!nom) return ta.value;
      return "ID: "+id+"\nnombre: "+nom+"\nciudad: "+(iCiu.value||"")+"\nfund: "+(iFund.value||"")+"\ndt: "+(iDt.value||"")+"\nliga: "+(iLiga.value||"")+"\ndesc: "+(iDesc.value||"")+"\nsituacion: "+(iSit.value||"");
    }
    bg.onclick=function(){
      if(typeof crearClubDesdePegar!=="function"){ msg.textContent="Motor de PEGAR no cargó"; return; }
      var r=crearClubDesdePegar(bloqueDeForm());
      if(!r.ok){ msg.textContent="❌ "+r.msg; msg.className="mini dev-msg mal"; return; }
      var p=(typeof parsearPegarClub==="function")?parsearPegarClub(bloqueDeForm()):{};
      if(p.nombre) parcheSet(r.id,"nombre",p.nombre);
      if(p.desc) parcheSet(r.id,"desc",p.desc);
      if(p.dt) parcheSet(r.id,"dt",p.dt);
      if(p.ciudad) parcheSet(r.id,"ciudad",p.ciudad);
      if(p.fund) parcheSet(r.id,"fund",p.fund);
      if(p.situacion) parcheSet(r.id,"situacion",p.situacion);
      msg.textContent="✅ "+r.id+" · "+r.nombre+(r.liga?" · liga "+r.liga:"")+" — abre en Club para números, historia y clásico.";
      msg.className="mini dev-msg bien";
      CLUB_SEL=r.id;
      if(typeof aviso==="function") aviso("Club "+r.id+" listo. Sigue en la pestaña Club.");
      TAB="club"; setTimeout(repintar,280);
    };
    var ir=el("button","btn-aqua chico","Abrir en Club →"); ir.style.marginTop="6px";
    ir.onclick=function(){ TAB="club"; repintar(); };
    cont.appendChild(bg); cont.appendChild(ir); cont.appendChild(msg);
    cont.appendChild(el("p","mini","Plantel y decisiones propias siguen en los .js (no se inventan acá). Segunda 2026 = cantera."));
  }

  /* ---------- pestaña LIGA ---------- */
  function pintarLiga(cont,repintar){
    cont.appendChild(el("p","mini","Estado del <b>formato</b> de cada torneo (no de sus clubes)."));
    devErasLiga().forEach(function(era){
      var f=auditarFormato(era), r=auditarLiga(era);
      var d=el("div","dev-liga");
      d.innerHTML="<div class='dev-liga-cab'><b>"+r.nombre+"</b> <span class='mini'>["+era+"]</span><b class='dev-pct'>"+f.pct+"%</b></div>"+barraPct(f.pct);
      var ul=el("div","mini");
      f.tiene.forEach(function(x){ ul.appendChild(chip("✓ "+x.n,"ok")); });
      f.faltan.forEach(function(x){ ul.appendChild(chip("✗ "+x.n,"mal")); });
      d.appendChild(ul);
      d.appendChild(el("p","mini","Clubes de este torneo: <b>"+r.pct+"%</b> de rigor promedio."));
      cont.appendChild(d);
    });
    _pintarLigaNueva(cont);
  }

  /* Liga nueva: generador de scaffold .js (como el Exportar de clubes, pero para
     una liga entera). Puro codegen — NO toca el motor. Copiás/descargás el .js,
     lo dejás en js/, lo sumás a index.html y ya tenés "la liga danesa". */
  function _pintarLigaNueva(cont){
    var wrap=el("div","dev-liga-nueva");
    wrap.appendChild(el("h3","dev-h3","➕ Liga nueva — generar .js"));
    wrap.appendChild(el("p","mini","Copia el formato de una liga existente. Llenás nombre, clave de época y los clubes; el motor deriva fuerza→indicadores, caja, estatuto y poder. Un club por línea: <code>ID | Nombre | Ciudad | fuerza(30-90) | aforo | Estadio</code>."));
    var grid=el("div","pegar-grid");
    function campo(lbl,ph,val,span){
      var lab=el("label"); if(span) lab.className="span2"; lab.textContent=lbl;
      var i=el("input","dev-in"); i.placeholder=ph||""; if(val!=null) i.value=val;
      lab.appendChild(i); grid.appendChild(lab); return i;
    }
    var iNom=campo("Nombre de la liga","Superliga Danesa");
    var iEra=campo("Clave de época (única)","din2026");
    /* base de época: reusar una existente para heredar reglas */
    var labB=el("label"); labB.textContent="Época base (hereda reglas)";
    var selB=el("select","dev-select");
    ["2026","2026b","2026c","1991","2006","arg2026"].forEach(function(k){
      var o=document.createElement("option"); o.value=k; o.textContent=k; selB.appendChild(o);
    });
    labB.appendChild(selB); grid.appendChild(labB);
    var iPais=campo("País (federación: chile, argentina…)","dinamarca");
    var iPts=campo("Puntos por victoria","3"); iPts.type="number"; iPts.value="3";
    wrap.appendChild(grid);

    var labC=el("label","span2"); labC.textContent="Clubes (uno por línea)";
    var taC=el("textarea","dev-ta"); taC.rows=6;
    taC.placeholder="FCK | FC København | Copenhague | 78 | 38000 | Parken\nBIF | Brøndby IF | Brøndby | 72 | 28000 | Brøndby Stadion";
    labC.appendChild(taC); wrap.appendChild(labC);

    /* clonar a rigor Colo-Colo: llena todo lo estructural y deja los datos duros
       como "por documentar" (justificados). La liga queda al 100% en el auditor. */
    var labR=el("label","mini"); labR.style.display="flex"; labR.style.gap="6px"; labR.style.alignItems="center"; labR.style.margin="4px 0";
    var chkR=el("input"); chkR.type="checkbox"; chkR.checked=true;
    labR.appendChild(chkR); labR.appendChild(document.createTextNode(" Clonar a rigor Colo-Colo (cada club al 100%, aplicado en vivo)"));
    wrap.appendChild(labR);

    var acc=el("div","dev-acc");
    var bGen=el("button","btn-aqua chico verde","⚙ Generar .js");
    var bCop=el("button","btn-aqua chico","📋 Copiar"); bCop.disabled=true;
    var bDes=el("button","btn-aqua chico","⬇ Descargar .js"); bDes.disabled=true;
    acc.appendChild(bGen); acc.appendChild(bCop); acc.appendChild(bDes);
    wrap.appendChild(acc);
    var msg=el("p","mini dev-msg","");
    var salida=el("textarea","dev-ta"); salida.rows=12; salida.readOnly=true; salida.style.display="none";
    wrap.appendChild(msg); wrap.appendChild(salida);
    cont.appendChild(wrap);

    bGen.onclick=function(){
      var meta={
        nombre:_lp(iNom.value,60), eraKey:_claveEra(iEra.value),
        baseEra:selB.value, pais:_lp(iPais.value,24).toLowerCase().replace(/[^a-z]/g,""),
        pts:Math.max(1,Math.min(3,parseInt(iPts.value,10)||3))
      };
      if(!meta.eraKey){ msg.textContent="❌ Falta la clave de época (solo letras/números, ej: din2026)."; msg.className="mini dev-msg mal"; return; }
      var clubs=_parseClubesLiga(taC.value);
      if(!clubs.length){ msg.textContent="❌ No leí ningún club válido. Formato: ID | Nombre | Ciudad | fuerza | aforo | Estadio."; msg.className="mini dev-msg mal"; return; }
      var txt=_scaffoldLiga(meta,clubs);
      var extra="";
      if(chkR.checked && typeof devClonarLigaRigor==="function"){
        var r=devClonarLigaRigor(clubs,meta);
        if(r&&r.ok){
          /* con rigor completo, el .js descargable ES el persistente (todo el rigor) */
          if(typeof devExportarLigaRigor==="function"){ var full=devExportarLigaRigor(clubs,meta); if(full) txt=full; }
          extra=" · 🟢 Clonada a rigor Colo-Colo: liga al "+(r.pct!=null?r.pct+"%":"100%")+". El .js de abajo YA trae todo el rigor (persistente). Datos duros marcados 'por documentar'.";
          CLUB_SEL=clubs[0].id;
        }
      }
      salida.value=txt; salida.style.display="block";
      bCop.disabled=false; bDes.disabled=false;
      msg.textContent="✅ Liga "+meta.eraKey+" con "+clubs.length+" club(es). Guarda el .js en js/, agrégalo a index.html DESPUÉS de liga-registrar.js."+extra;
      msg.className="mini dev-msg bien";
    };
    bCop.onclick=function(){ try{ salida.select(); document.execCommand("copy"); if(typeof aviso==="function") aviso("Copiado"); }catch(e){ if(typeof aviso==="function") aviso("Cópialo a mano (Ctrl+C)"); } };
    bDes.onclick=function(){
      try{
        var blob=new Blob([salida.value],{type:"text/javascript"});
        var a=document.createElement("a"); a.href=URL.createObjectURL(blob);
        a.download="data-liga-"+(_claveEra(iEra.value)||"nueva")+".js";
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
      }catch(e){ if(typeof aviso==="function") aviso("No se pudo descargar; copia el texto"); }
    };
  }
  /* helpers del generador de liga */
  function _lp(s,max){ return (typeof textoLimpio==="function")?textoLimpio(s,max):String(s==null?"":s).replace(/<[^>]*>/g,"").trim().slice(0,max||80); }
  function _claveEra(s){ return String(s||"").toLowerCase().replace(/[^a-z0-9]/g,"").slice(0,16); }
  function _parseClubesLiga(txt){
    var out=[];
    String(txt||"").split(/\n+/).forEach(function(ln){
      ln=ln.trim(); if(!ln) return;
      var p=ln.split("|").map(function(x){ return x.trim(); });
      var id=String(p[0]||"").toUpperCase().replace(/[^A-Z0-9]/g,"").slice(0,6);
      var nom=_lp(p[1],48);
      if(!id||!nom) return;
      var fuerza=Math.max(30,Math.min(90,parseInt(p[3],10)||55));
      var aforo=Math.max(0,parseInt((p[4]||"").replace(/[^0-9]/g,""),10)||0);
      out.push({ id:id, n:nom, c:_lp(p[2],32)||nom, fuerza:fuerza, aforo:aforo,
                 est:_lp(p[5],48)||("Estadio de "+(_lp(p[2],32)||nom)), ciudad:_lp(p[2],32)||"" });
    });
    return out;
  }
  function _jsStr(s){ return '"'+String(s==null?"":s).replace(/\\/g,"\\\\").replace(/"/g,'\\"')+'"'; }
  function _scaffoldLiga(meta,clubs){
    var fecha=new Date().toISOString().slice(0,10);
    var varName="LIGA_"+meta.eraKey.toUpperCase().replace(/[^A-Z0-9]/g,"_");
    var lineas=clubs.map(function(c){
      return "  { id:"+_jsStr(c.id)+", n:"+_jsStr(c.n)+", c:"+_jsStr(c.c)+", fuerza:"+c.fuerza+
             ", aforo:"+c.aforo+", est:"+_jsStr(c.est)+", ciudad:"+_jsStr(c.ciudad)+", z:\"—\" }";
    }).join(",\n");
    return '"use strict";\n'+
      '/* ============================================================\n'+
      '   FUTBOLINI · data-liga-'+meta.eraKey+'.js\n'+
      '   Liga generada por el Editor de contenido el '+fecha+'.\n'+
      '   Cargar en index.html DESPUÉS de liga-registrar.js.\n'+
      '   El motor deriva indicadores, caja, estatuto y poder de la fuerza (0-90).\n'+
      '   INTEGRIDAD: pon nombres/estadios REALES y documentados; nada inventado como real.\n'+
      '   ============================================================ */\n'+
      'var '+varName+'=[\n'+lineas+'\n];\n'+
      'if(typeof registrarLiga==="function"){\n'+
      '  registrarLiga({\n'+
      '    eraKey:'+_jsStr(meta.eraKey)+',\n'+
      '    clubs:'+varName+',\n'+
      '    baseEra:'+_jsStr(meta.baseEra)+',\n'+
      '    nombre:'+_jsStr(meta.nombre||("Liga "+meta.eraKey))+',\n'+
      '    era:{ n:'+_jsStr(meta.nombre||meta.eraKey)+(meta.pais?', pais:'+_jsStr(meta.pais):'')+', puntosVictoria:'+meta.pts+' }\n'+
      '  });\n'+
      '}\n';
  }

  /* ---------- pestaña EXPORTAR ---------- */
  function pintarExportar(cont,repintar){
    var p=parcheLeer(), n=parcheCuenta();
    cont.appendChild(el("p","mini",
      "Lo editado vive en tu navegador. Para hacerlo <b>permanente</b>: copia este archivo, guárdalo como "+
      "<code>js/data-parche-dev.js</code> y agrégalo al final de <code>index.html</code>. Ahí queda en git."));
    if(!n){ cont.appendChild(el("div","resul mitad","Todavía no editaste nada.")); return; }
    cont.appendChild(el("p","mini","<b>"+n+"</b> campo(s) en "+Object.keys(p).length+" club(es).")); 
    var txt=_generarArchivo(p);
    var ta=el("textarea","dev-ta"); ta.rows=14; ta.value=txt; ta.readOnly=true;
    cont.appendChild(ta);
    var acc=el("div","dev-acc");
    var bc=el("button","btn-aqua chico verde","📋 Copiar");
    bc.onclick=function(){
      try{ ta.select(); document.execCommand("copy"); aviso("Copiado"); }
      catch(e){ aviso("Cópialo a mano (Ctrl+C)"); }
    };
    var bd=el("button","btn-aqua chico","⬇ Descargar .js");
    bd.onclick=function(){
      try{
        var blob=new Blob([txt],{type:"text/javascript"});
        var a=document.createElement("a");
        a.href=URL.createObjectURL(blob); a.download="data-parche-dev.js";
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
      }catch(e){ aviso("No se pudo descargar; copia el texto"); }
    };
    var bx=el("button","btn-aqua chico rojo","🗑 Borrar parche");
    bx.onclick=function(){
      if(!confirm("¿Borrar TODO lo editado? (se recarga para volver a los datos originales)")) return;
      parcheBorrar(); aviso("Parche borrado"); try{ location.reload(); }catch(e){ repintar(); }
    };
    acc.appendChild(bc); acc.appendChild(bd); acc.appendChild(bx);
    cont.appendChild(acc);
  }

  function _generarArchivo(p){
    var fecha=new Date().toISOString().slice(0,10);
    return '"use strict";\n'+
      '/* ============================================================\n'+
      '   FUTBOLINI · data-parche-dev.js\n'+
      '   Generado por el Editor de contenido el '+fecha+'.\n'+
      '   Cargar DESPUÉS de dev-esquema.js (que trae aplicarParcheClubes).\n'+
      '   Cada clave es un club; cada campo, uno del ESQUEMA_CLUB.\n'+
      '   ============================================================ */\n'+
      'var DEV_PARCHE_GUARDADO='+JSON.stringify(p,null,2)+';\n'+
      '(function(){\n'+
      '  if(typeof aplicarParcheClubes==="function") aplicarParcheClubes(DEV_PARCHE_GUARDADO);\n'+
      '})();\n';
  }

  /* expuesto */
  window.abrirEditorContenido=abrirEditorContenido;
})();

;
/* ==== js/dev-clonar.js ==== */
"use strict";
/* ============================================================
   FUTBOLINI · dev-clonar.js  (motor de edición · clonar liga a RIGOR COLO-COLO)
   "Copio X liga y queda con rigor de Primera chilena: cada equipo a 100%,
   nivel Colo-Colo." Eso hace devClonarLigaRigor.

   CÓMO llega al 100% SIN romper la integridad:
   - Lo ESTRUCTURAL y derivable se LLENA de verdad: indicadores (de la fuerza),
     caja, estatuto, mapa de poder, estadio (sectores/precios), escudo, clásico
     (rival en la misma liga), situación, descripción y una decisión propia.
   - Los DATOS DUROS que NO se pueden inventar (DT real, año de fundación,
     línea de historia, época dorada) se marcan como AUSENCIA JUSTIFICADA
     (DEV_SIN_DATO) — "por documentar". El auditor NO los penaliza y quedan
     listos para que vos o Grok los completen con fuente. Nada se presenta
     como real siendo inventado (regla inviolable).

   Resultado: auditarClub(id)===100 y auditarLiga(era)===100, honesto.
   Depende de: liga-registrar.js, dev-esquema.js (ESQUEMA_CLUB/DEV_SIN_DATO),
   DECISIONES. Cargar DESPUÉS de todos ellos.
   ============================================================ */
(function(){

  /* set de un campo del esquema por su clave (usa el set() del propio ESQUEMA_CLUB) */
  function _setRigor(k,id,v){
    if(typeof ESQUEMA_CLUB==="undefined") return;
    for(var i=0;i<ESQUEMA_CLUB.length;i++){
      if(ESQUEMA_CLUB[i].k===k && typeof ESQUEMA_CLUB[i].set==="function"){ ESQUEMA_CLUB[i].set(id,v); return; }
    }
  }
  /* marca un campo como ausencia justificada (no se inventa, no penaliza) */
  function _justif(id,k,motivo){
    if(typeof DEV_SIN_DATO==="object" && DEV_SIN_DATO) DEV_SIN_DATO[id+"."+k]=motivo;
  }
  /* perfil según la fuerza: da vida a desc/situación sin inventar hechos */
  function _perfilFuerza(f){
    f=f||55;
    if(f>=78) return { desc:"uno de los pesos pesados", meta:"Te contratan para ganar el título y competir en el continente." };
    if(f>=70) return { desc:"un club consolidado", meta:"El objetivo es meterse arriba y pelear un cupo internacional." };
    if(f>=60) return { desc:"un club de mitad de tabla", meta:"Estabilizar el club y soñar con dar el salto es el mandato." };
    return { desc:"un club chico", meta:"Sobrevivir en la categoría y crecer de a poco es la misión." };
  }
  /* color determinístico y estable a partir del ID (cosmético, no es un "dato") */
  function _hash(s){ var h=0,i; s=String(s||""); for(i=0;i<s.length;i++){ h=(h*31+s.charCodeAt(i))>>>0; } return h; }
  function _colorDe(id,off){ var h=(_hash(id)+(off||0)*97)%360; return "hsl("+h+",55%,45%)"; }
  function _coloresDe(club){
    if(club && club.colores && club.colores.length>=2) return club.colores.slice(0,2);
    return [_colorDe(club&&club.id,0), _colorDe(club&&club.id,1)];
  }
  /* sectores de estadio derivados del aforo (cuotas suman 1) */
  function _sectoresDe(aforo,fuerza){
    var base=Math.max(1000,aforo||12000);
    /* 7.9025 · antes 6000+(f-30)*260: un club fuerza 90 quedaba con palco a 112.320, y el
       palco más caro documentado de Chile (Rapa Nui, Colo-Colo) es 45.000. Misma banda que
       el resto del juego: popular 5.000–9.200, palco hasta ~48 mil. */
    var p=Math.round((5000+(Math.max(30,Math.min(90,fuerza||55))-30)*70)/100)*100;   /* precio popular según fuerza */
    return [
      { n:"Galería (popular)", tipo:"popular", cuota:0.40, precio:p },
      { n:"Tribuna lateral",   tipo:"tribuna", cuota:0.34, precio:Math.round(p*2.1) },
      { n:"Tribuna central",   tipo:"tribuna", cuota:0.18, precio:Math.round(p*3.0) },
      { n:"Palco",             tipo:"premium", cuota:0.08, precio:Math.round(p*5.2) }
    ];
  }
  /* decisión propia mínima, bien formada y neutra (placeholder para editar) */
  function _decisionGenerica(id,nombre,anio){
    return {
      id:"clon_"+id, club:id, anio:anio||2026, buzon:"institucional", peso:"bajo", mes:6,
      t:nombre+": primera reunión de directorio",
      d:"Asumes en "+nombre+". El directorio quiere conocer tu norte. (Carta base del clonador — editala en el editor para darle alma propia al club.)",
      posturas:{directorio:0,hinchada:0,prensa:0},
      op:[
        {t:"Proyecto a largo plazo", d:"Paciencia y proceso.", dif:40, grupos:{directorio:3,hinchada:-1},
         bien:{txt:"El directorio te da tiempo.",ef:{}}, mitad:{txt:"Te miran de reojo.",ef:{}}, mal:{txt:"Dudan de tu plan.",ef:{}}},
        {t:"Prometer resultados ya", d:"Ilusión inmediata, presión inmediata.", dif:52, grupos:{hinchada:4,directorio:-2},
         bien:{txt:"La gente se ilusiona.",ef:{}}, mitad:{txt:"Aplauso tibio.",ef:{}}, mal:{txt:"Te queda grande el traje.",ef:{}}}
      ]
    };
  }

  /* ---------- el clonador ---------- */
  /* clubs: [{id,n,c,fuerza,aforo,est,ciudad,fund?,colores?}]  (formato de registrarLiga)
     meta:  {eraKey, baseEra, nombre, pais?, pts?}
     Devuelve {ok, era, clubes, pct} */
  function devClonarLigaRigor(clubs, meta){
    if(!clubs||!clubs.length||!meta||!meta.eraKey) return {ok:false, msg:"faltan clubes o clave de época"};
    var anio=parseInt(meta.baseEra,10)||2026;

    /* 1 · registrar la liga: el motor deriva ind/caja/estatuto/poder de la fuerza */
    if(typeof registrarLiga==="function"){
      registrarLiga({
        eraKey:meta.eraKey, clubs:clubs, baseEra:meta.baseEra||2026,
        nombre:meta.nombre||("Liga "+meta.eraKey),
        era:{ n:meta.nombre||meta.eraKey, pais:(meta.pais||undefined), puntosVictoria:meta.pts||3 }
      });
    }

    /* 2 · por club, completar TODO lo que el auditor exige */
    clubs.forEach(function(c,i){
      var id=c.id; if(!id) return;
      var col=_coloresDe(c);
      var tier=_perfilFuerza(c.fuerza), ciu=(c.ciudad||c.c||"la región");
      /* identidad — descripción derivada del tier (más viva que un placeholder pelado) */
      _setRigor("desc", id, (c.n||id)+", "+tier.desc+" de "+ciu+". (Ficha base del clonador — completar con fuente.)");
      if(c.ciudad) _setRigor("ciudad", id, c.ciudad); else _justif(id,"ciudad","Ciudad por documentar (no se inventa).");
      if(typeof c.fund==="number" && c.fund>1800) _setRigor("fund", id, c.fund); else _justif(id,"fund","Año de fundación por documentar (no se inventa).");
      _setRigor("colores", id, col);
      /* alma — la situación arranca del objetivo que impone el tamaño del club */
      _setRigor("situacion", id, "Diriges a "+(c.n||id)+". "+tier.meta+" Historia, clásico y DT se completan en el editor.");
      _justif(id,"dt","DT por documentar (no se inventa un nombre real).");
      _justif(id,"historia","Línea de historia por documentar con fuente.");
      _justif(id,"gloria","Época dorada por documentar.");
      /* cancha */
      _setRigor("estadio", id, { nombre:(c.est||("Estadio de "+(c.ciudad||c.n||id))), aforo:(c.aforo||12000), sectores:_sectoresDe(c.aforo,c.fuerza) });
      _setRigor("escudo", id, { c1:col[0], c2:col[1]||"#ffffff" });
      /* decisión propia (la "vara" de Grok): una carta que solo existe en este club */
      try{
        if(typeof DECISIONES!=="undefined" && !DECISIONES.some(function(d){return d&&d.club===id;}))
          DECISIONES.push(_decisionGenerica(id, c.n||id, anio));
      }catch(e){}
    });

    /* clásicos: anillo circular en UNA pasada. OJO: un par [A,B] sirve a los DOS,
       y devPonerRivales borra los pares de un id — por eso NO se setea por club en
       cadena (se pisan). Acá se empujan los pares directo, sin borrar. */
    try{
      if(typeof RIVALIDADES_2026!=="undefined" && clubs.length>=2){
        for(var k=0;k<clubs.length;k++){
          var a=clubs[k].id, b=clubs[(k+1)%clubs.length].id;
          if(a&&b&&a!==b && !RIVALIDADES_2026.some(function(p){ return (p[0]===a&&p[1]===b)||(p[0]===b&&p[1]===a); }))
            RIVALIDADES_2026.push([a,b]);
        }
      } else if(clubs.length===1){ _justif(clubs[0].id,"clasico","Liga de un club: sin rival."); }
    }catch(e){}

    var pct=null;
    try{ if(typeof auditarLiga==="function") pct=auditarLiga(meta.eraKey).pct; }catch(e){}
    return { ok:true, era:meta.eraKey, clubes:clubs.length, pct:pct };
  }

  /* ---------- EXPORTAR el clon a un .js PERSISTENTE ----------
     Lee el estado EN VIVO (después de devClonarLigaRigor) y serializa TODO el
     rigor de esos clubes a un data file autocontenido. Cargándolo en index.html
     la liga vuelve a quedar al 100% sin re-clonar. */
  function _mapa(nombre){ return (typeof _devMapa==="function")?_devMapa(nombre):null; }
  function _slice(nombre,ids){ var m=_mapa(nombre)||{}, o={}; ids.forEach(function(id){ if(m[id]!=null) o[id]=m[id]; }); return o; }
  function _jstr(s){ return '"'+String(s==null?"":s).replace(/\\/g,"\\\\").replace(/"/g,'\\"')+'"'; }
  function devExportarLigaRigor(clubs, meta){
    if(!clubs||!clubs.length||!meta||!meta.eraKey) return "";
    var ids=clubs.map(function(c){return c.id;});
    var fecha=new Date().toISOString().slice(0,10);
    var varName="LIGA_"+meta.eraKey.toUpperCase().replace(/[^A-Z0-9]/g,"_");
    var J=function(o){ return JSON.stringify(o,null,0); };
    /* club array para registrarLiga (registra LIGAS/ERA; los detalles van aparte) */
    var lineas=clubs.map(function(c){
      return "  {id:"+_jstr(c.id)+",n:"+_jstr(c.n)+",c:"+_jstr(c.c||c.n)+",fuerza:"+(c.fuerza||55)+
             ",aforo:"+(c.aforo||0)+",est:"+_jstr(c.est||"")+",ciudad:"+_jstr(c.ciudad||"")+",z:\"—\"}";
    }).join(",\n");
    /* slices en vivo de cada estructura */
    var infos=_slice("CLUB_INFO_2026",ids), metas=_slice("CLUB_META",ids), inds=_slice("IND_BASE_2026",ids),
        cajas=_slice("CAJA_BASE_2026",ids), estat=_slice("ESTATUTO_INICIAL",ids), poder=_slice("PODER_CLUB",ids),
        sit=_slice("SITUACION_CLUB",ids), estad=_slice("ESTADIOS_DATA",ids), esc=_slice("ESCUDOS_CLUB",ids),
        hist=_slice("HISTORIA_LINEA",ids), epo=_slice("EPOCAS_CLUB",ids);
    var D=_mapa("DECISIONES")||[]; var decs=D.filter(function(d){ return d && ids.indexOf(d.club)>=0; });
    var R=(typeof RIVALIDADES_2026!=="undefined")?RIVALIDADES_2026:[];
    var rivs=R.filter(function(p){ return ids.indexOf(p[0])>=0 || ids.indexOf(p[1])>=0; });
    var sd={}; if(typeof DEV_SIN_DATO==="object") Object.keys(DEV_SIN_DATO).forEach(function(k){ if(ids.indexOf(String(k).split(".")[0])>=0) sd[k]=DEV_SIN_DATO[k]; });

    return '"use strict";\n'+
      '/* ============================================================\n'+
      '   FUTBOLINI · data-liga-'+meta.eraKey+'.js  (LIGA A RIGOR COLO-COLO)\n'+
      '   Generada por el Editor ('+fecha+'). Cada club al 100% de rigor.\n'+
      '   Cargar en index.html DESPUÉS de liga-registrar.js y dev-esquema.js.\n'+
      '   INTEGRIDAD: los datos duros (DT/fundación/historia/gloria) van marcados\n'+
      '   como "por documentar" en DEV_SIN_DATO — reemplazalos con fuente real.\n'+
      '   ============================================================ */\n'+
      'var '+varName+'=[\n'+lineas+'\n];\n'+
      'if(typeof registrarLiga==="function"){ registrarLiga({eraKey:'+_jstr(meta.eraKey)+',clubs:'+varName+
        ',baseEra:'+_jstr(meta.baseEra||"2026")+',nombre:'+_jstr(meta.nombre||meta.eraKey)+
        ',era:{n:'+_jstr(meta.nombre||meta.eraKey)+(meta.pais?',pais:'+_jstr(meta.pais):'')+',puntosVictoria:'+(meta.pts||3)+'}}); }\n'+
      '(function(){\n'+
      '  function fus(mapa,data){ if(typeof mapa!=="object"||!mapa) return; Object.keys(data).forEach(function(id){ mapa[id]=Object.assign(mapa[id]||{},data[id]); }); }\n'+
      '  function put(mapa,data){ if(typeof mapa!=="object"||!mapa) return; Object.keys(data).forEach(function(id){ mapa[id]=data[id]; }); }\n'+
      '  try{ if(typeof CLUB_INFO_2026!=="undefined") fus(CLUB_INFO_2026,'+J(infos)+'); }catch(e){}\n'+
      '  try{ if(typeof CLUB_INFO!=="undefined") Object.keys('+J(infos)+').forEach(function(id){ if(!CLUB_INFO[id]) CLUB_INFO[id]=CLUB_INFO_2026[id]; }); }catch(e){}\n'+
      '  try{ if(typeof CLUB_META!=="undefined") fus(CLUB_META,'+J(metas)+'); }catch(e){}\n'+
      '  try{ if(typeof IND_BASE_2026!=="undefined") put(IND_BASE_2026,'+J(inds)+'); }catch(e){}\n'+
      '  try{ if(typeof CAJA_BASE_2026!=="undefined") put(CAJA_BASE_2026,'+J(cajas)+'); }catch(e){}\n'+
      '  try{ if(typeof ESTATUTO_INICIAL!=="undefined") put(ESTATUTO_INICIAL,'+J(estat)+'); }catch(e){}\n'+
      '  try{ if(typeof PODER_CLUB!=="undefined") put(PODER_CLUB,'+J(poder)+'); }catch(e){}\n'+
      '  try{ if(typeof SITUACION_CLUB!=="undefined") put(SITUACION_CLUB,'+J(sit)+'); }catch(e){}\n'+
      '  try{ if(typeof ESTADIOS_DATA!=="undefined") put(ESTADIOS_DATA,'+J(estad)+'); }catch(e){}\n'+
      '  try{ if(typeof ESCUDOS_CLUB!=="undefined") put(ESCUDOS_CLUB,'+J(esc)+'); }catch(e){}\n'+
      '  try{ if(typeof HISTORIA_LINEA!=="undefined") put(HISTORIA_LINEA,'+J(hist)+'); }catch(e){}\n'+
      '  try{ if(typeof EPOCAS_CLUB!=="undefined") put(EPOCAS_CLUB,'+J(epo)+'); }catch(e){}\n'+
      '  try{ if(typeof DECISIONES!=="undefined"){ '+J(decs)+'.forEach(function(d){ if(!DECISIONES.some(function(x){return x.id===d.id;})) DECISIONES.push(d); }); } }catch(e){}\n'+
      '  try{ if(typeof RIVALIDADES_2026!=="undefined"){ '+J(rivs)+'.forEach(function(p){ if(!RIVALIDADES_2026.some(function(q){return (q[0]===p[0]&&q[1]===p[1])||(q[0]===p[1]&&q[1]===p[0]);})) RIVALIDADES_2026.push(p); }); } }catch(e){}\n'+
      '  try{ if(typeof DEV_SIN_DATO==="object") Object.assign(DEV_SIN_DATO,'+J(sd)+'); }catch(e){}\n'+
      '})();\n';
  }

  window.devClonarLigaRigor=devClonarLigaRigor;
  window.devExportarLigaRigor=devExportarLigaRigor;
})();

;
/* ==== js/dev-cobertura.js ==== */
"use strict";
/* ============================================================
   FUTBOLINI · dev-cobertura.js  (análisis de CONTENIDO por club/época)
   El auditor de rigor (dev-esquema) mide si los CAMPOS están llenos. Esto mide
   otra cosa: ¿cuánta ALMA propia tiene cada club? — decisiones que solo le pasan
   a él, arcos de historia, plantel real. Un club puede estar 100% en rigor de
   ficha y aun así ser "pobre" en contenido vivo (cartas, arcos, tuits).

   Sirve para RESPONDER: "si juego a X en tal año, ¿voy a ver cosas de X y de esa
   época, o puro contenido genérico?". Y para ver DÓNDE hay que trabajar.

   No toca el juego: solo LEE DECISIONES / ARCOS_EQUIPO / PLANTELES_REALES.
   ============================================================ */
(function(){

  /* const globales no cuelgan de window; los tomo por nombre explícito */
  function _DEC(){ return (typeof DECISIONES!=="undefined")?DECISIONES:[]; }
  function _ARC(){ return (typeof ARCOS_EQUIPO!=="undefined")?ARCOS_EQUIPO:{}; }
  function _PLA(){ return (typeof PLANTELES_REALES!=="undefined")?PLANTELES_REALES:{}; }

  /* contenido propio de UN club */
  function auditarContenido(id){
    var dec=_DEC().filter(function(d){ return d && d.club===id; });
    var porAnio={}; dec.forEach(function(d){ var a=d.anio||"s/año"; porAnio[a]=(porAnio[a]||0)+1; });
    var arcos=(_ARC()[id]||[]).length;
    var pr=_PLA()[id];
    var plantelReal=!!(pr && Object.keys(pr).length);
    var total=dec.length+arcos;
    var nivel=total>=6?"rico":(total>=2?"medio":"pobre");
    return { id:id, decisiones:dec.length, porAnio:porAnio, arcos:arcos, plantelReal:plantelReal, total:total, nivel:nivel };
  }

  /* lista de clubes dirigibles (los que ofrece el picker: 1991 + 2026 + B + C + AFA) */
  function _clubesDirigibles(){
    var set={}, push=function(o){ if(o) Object.keys(o).forEach(function(k){ set[k]=1; }); };
    push(typeof CLUB_INFO!=="undefined"?CLUB_INFO:null);
    push(typeof CLUB_INFO_2026!=="undefined"?CLUB_INFO_2026:null);
    var out=Object.keys(set).filter(function(id){ return typeof devEsJugable!=="function" || devEsJugable(id); });
    return out;
  }

  /* informe global: cuántos clubes ricos/medios/pobres, y la lista de los pobres */
  function devInformeCobertura(){
    var ids=_clubesDirigibles(), ricos=[], medios=[], pobres=[];
    ids.forEach(function(id){
      var c=auditarContenido(id);
      (c.nivel==="rico"?ricos:c.nivel==="medio"?medios:pobres).push(c);
    });
    return { total:ids.length, ricos:ricos, medios:medios, pobres:pobres,
             pctRico: ids.length?Math.round(ricos.length/ids.length*100):0 };
  }

  /* ---------- render de la pestaña Cobertura del editor ---------- */
  function devPintarCobertura(cont){
    if(typeof el!=="function") return;
    var inf=devInformeCobertura();
    cont.appendChild(el("p","mini","Mide el <b>alma propia</b> de cada club (decisiones que solo le pasan a él + arcos de historia), no solo si la ficha está llena. Muestra dónde el juego se siente genérico. La vara es <b>Colo-Colo</b>."));
    var res=el("div","dev-liga");
    res.innerHTML="<div class='dev-liga-cab'><b>Cobertura de contenido</b> <span class='mini'>"+inf.total+" clubes dirigibles</span><b class='dev-pct'>"+inf.pctRico+"% ricos</b></div>";
    res.appendChild(el("div","mini",
      "<span style='color:#2fa84f'>● Ricos "+inf.ricos.length+"</span> · <span style='color:#d68a1f'>● Medios "+inf.medios.length+"</span> · <span style='color:#c0392b'>● Pobres "+inf.pobres.length+"</span>"));
    cont.appendChild(res);
    function tabla(titulo,lista,color){
      if(!lista.length) return;
      var d=el("div","dev-liga");
      d.appendChild(el("div","dev-liga-cab","<b style='color:"+color+"'>"+titulo+"</b> <span class='mini'>"+lista.length+"</span>"));
      var grid=el("div","dev-grid");
      lista.sort(function(a,b){ return b.total-a.total; }).forEach(function(c){
        var b=el("button","dev-club"+(c.nivel==="rico"?" ok":c.nivel==="medio"?" medio":" mal"));
        b.innerHTML="<b>"+c.id+"</b><span>"+c.decisiones+"d·"+c.arcos+"a</span>";
        var anios=Object.keys(c.porAnio).filter(function(x){return x!=="s/año";});
        b.title=c.id+": "+c.decisiones+" decisiones ("+ (anios.length?("años "+anios.join(", ")):"sin año") +"), "+c.arcos+" arco(s), plantel real: "+(c.plantelReal?"sí":"no");
        if(typeof CLUB_SEL!=="undefined"){ b.onclick=function(){ CLUB_SEL=c.id; }; }
        grid.appendChild(b);
      });
      d.appendChild(grid);
      cont.appendChild(d);
    }
    tabla("🔴 Pobres — a rellenar primero (0-1 de contenido)", inf.pobres, "#c0392b");
    tabla("🟠 Medios — les falta alma (2-5)", inf.medios, "#d68a1f");
    tabla("🟢 Ricos — la vara", inf.ricos, "#2fa84f");
    cont.appendChild(el("p","mini","Cómo subir a un club: darle <b>decisiones propias</b> (cartas que solo le pasan a él, con <code>club:\"ID\"</code>) y <b>arcos</b> de historia. Colo-Colo tiene 15+ decisiones; ese es el listón del <i>alma</i>. Elige un club arriba y créale una acá abajo:"));
    if(typeof devPintarNuevaDecision==="function") devPintarNuevaDecision(cont);
  }

  window.auditarContenido=auditarContenido;
  window.devInformeCobertura=devInformeCobertura;
  window.devPintarCobertura=devPintarCobertura;
})();

;
/* ==== js/dev-doctor.js ==== */
"use strict";
/* ============================================================
   FUTBOLINI · dev-doctor.js   (7.9021 · el modo dev deja de ser solo trampas)

   El panel dev tenía botones para HACER cosas (dar plata, lesionar, saltar año)
   pero ninguno para COMPROBAR que el juego está sano. Esto es lo segundo:
   corre diagnósticos sobre la partida de verdad y da un veredicto.

   REGLA DEL REPO (CLAUDE.md): cada parche deja el doctor mejor que como estaba.
   Si arreglás un bug, el chequeo que lo habría cazado se agrega ACÁ, no solo en
   los tests: los tests corren en CI, el doctor corre sobre la partida del jugador.

   Cómo se agrega un chequeo nuevo: `devDoctorRegistrar({id, area, n, fn})`.
   `fn()` devuelve {ok:bool, txt:"qué pasó", detalle:[...]} o lanza.
   ============================================================ */

var DOCTOR_CHECKS=[];
/* 7.9078 · dónde vive cada chequeo (archivo:línea), para ir directo a arreglarlo */
function _docDonde(){
  try{
    var st=String(new Error().stack||"").split("\n");
    for(var i=0;i<st.length;i++){
      var m=/\/(js\/[\w.-]+\.js)(?:\?[^:]*)?:(\d+)/.exec(st[i]);
      if(m&&!/_docDonde|devDoctorRegistrar/.test(st[i])) return m[1]+":"+m[2];
    }
  }catch(e){}
  return "";
}
function devDoctorRegistrar(c){
  if(!c||!c.id||typeof c.fn!=="function") return false;
  if(DOCTOR_CHECKS.some(function(x){ return x.id===c.id; })) return false;
  DOCTOR_CHECKS.push({id:c.id, area:c.area||"general", n:c.n||c.id, fn:c.fn, pesado:!!c.pesado, asinc:!!c.asinc, donde:c.donde||_docDonde(), arreglo:c.arreglo||""});
  return true;
}
function _dok(txt,detalle){ return {ok:true, txt:txt||"", detalle:detalle||[]}; }
function _dmal(txt,detalle){ return {ok:false, txt:txt||"", detalle:detalle||[]}; }
/* 7.9076 · el código de una función con todas sus envolturas (cada wrap guarda _orig): así un
   chequeo que busca algo en el fuente no se engaña cuando alguien la envuelve */
function _docFuente(fn){ let s="", f=fn, n=0; while(f&&n<12){ s+=String(f)+"\n"; f=f._orig; n++; } return s; }
function _dnum(v){ return typeof v==="number" && isFinite(v); }

/* ============ ÁREA: MOTOR Y TABLAS ============
   Acá van los invariantes que SIEMPRE tienen que cumplirse. Si uno falla, la
   tabla que ve el jugador está mintiendo. */

/* pj = pg+pe+pp, y pts = pg*puntosVictoria + pe, para todos los clubes */
devDoctorRegistrar({id:"tabla_coherente", area:"motor", n:"La tabla cuadra consigo misma", fn:function(){
  if(!E||!E.tabla) return _dok("sin partida");
  var pv=(typeof puntosVictoria==="function")?puntosVictoria():3, malos=[];
  Object.keys(E.tabla).forEach(function(id){
    var t=E.tabla[id]||{};
    if(!_dnum(t.pj)||!_dnum(t.pts)||!_dnum(t.gf)||!_dnum(t.gc)){ malos.push(id+": números rotos"); return; }
    if((t.pg||0)+(t.pe||0)+(t.pp||0)!==t.pj) malos.push(id+": PJ "+t.pj+" ≠ "+(t.pg||0)+"+"+(t.pe||0)+"+"+(t.pp||0));
    var esp=(t.pg||0)*pv+(t.pe||0);
    if(esp!==t.pts) malos.push(id+": pts "+t.pts+" ≠ "+esp+" (victoria vale "+pv+")");
  });
  return malos.length?_dmal(malos.length+" club(es) con la fila mal",malos):_dok(Object.keys(E.tabla).length+" filas cuadran");
}});

/* los goles a favor de la liga tienen que igualar los goles en contra */
devDoctorRegistrar({id:"goles_cuadran", area:"motor", n:"Los goles de la liga cuadran", fn:function(){
  if(!E||!E.tabla) return _dok("sin partida");
  var pool=(typeof clubesLigaActual==="function")?clubesLigaActual():[];
  var gf=0, gc=0, pj=0;
  (pool||[]).forEach(function(c){ var t=E.tabla[c.id]; if(!t) return; gf+=t.gf||0; gc+=t.gc||0; pj+=t.pj||0; });
  if(gf!==gc) return _dmal("GF "+gf+" ≠ GC "+gc+" (diferencia "+(gf-gc)+"): hay partidos contados a medias");
  if(pj%2!==0) return _dmal("suma de PJ impar ("+pj+"): algún partido quedó contado una sola vez");
  return _dok("GF=GC="+gf+" · PJ total "+pj);
}});

/* nadie puede quedarse sin jugar mientras el resto juega */
devDoctorRegistrar({id:"nadie_sin_jugar", area:"motor", n:"Ningún club queda sin jugar", fn:function(){
  if(!E||!E.tabla) return _dok("sin partida");
  var pool=(typeof clubesLigaActual==="function")?clubesLigaActual():[];
  if(!pool||pool.length<2) return _dok("liga sin pool");
  var pjs=pool.map(function(c){ return (E.tabla[c.id]&&E.tabla[c.id].pj)||0; });
  var max=Math.max.apply(null,pjs), min=Math.min.apply(null,pjs);
  if(max===0) return _dok("todavía no se juega nada");
  var rezagados=pool.filter(function(c){ return ((E.tabla[c.id]&&E.tabla[c.id].pj)||0)<=max-2; })
                    .map(function(c){ return (c.n||c.id)+" ("+((E.tabla[c.id]&&E.tabla[c.id].pj)||0)+" de "+max+")"; });
  return rezagados.length?_dmal(rezagados.length+" club(es) atrasados 2+ fechas",rezagados)
                         :_dok("todos entre "+min+" y "+max+" PJ");
}});

/* el calendario del jugador no puede tener huecos ni rivales fantasma */
devDoctorRegistrar({id:"calendario_sano", area:"motor", n:"El calendario no tiene huecos", fn:function(){
  if(!E||!E.calendario) return _dok("sin partida");
  var malos=[];
  E.calendario.forEach(function(c,i){
    if(!c){ malos.push("fecha "+i+": vacía"); return; }
    if(!c.rivalNombre) malos.push("fecha "+i+": sin rival");
    if(c.jugado && (!_dnum(c.gf)||!_dnum(c.gc))) malos.push("fecha "+i+" ("+c.rivalNombre+"): jugado sin marcador");
    if(c.rivalId && c.rivalId===E.club) malos.push("fecha "+i+": el club juega contra sí mismo");
  });
  return malos.length?_dmal(malos.length+" problema(s) en el calendario",malos.slice(0,12))
                     :_dok(E.calendario.length+" compromisos, "+E.calendario.filter(function(c){return c.jugado;}).length+" jugados");
}});

/* 7.9025 · el cuelgue de la Liguilla de la B: el índice apuntando a un partido ya
   jugado deja al jugador apretando Avanzar para siempre. */
devDoctorRegistrar({id:"idx_no_pegado", area:"motor", n:"El próximo partido no está ya jugado", fn:function(){
  if(!E||!E.calendario) return _dok("sin partida");
  var p=E.calendario[E.idx];
  if(!p) return _dok("temporada terminada");
  if(p.jugado) return _dmal("E.idx="+E.idx+" apunta a un partido YA jugado ("+(p.torneo||p.tipo)+" vs "+p.rivalNombre+"): Avanzar no avanza");
  /* y el orden: ningún partido jugado después de uno sin jugar (salvo el propio idx) */
  var desorden=[];
  for(var i=E.idx+1;i<E.calendario.length;i++){ if(E.calendario[i].jugado) desorden.push(i+": "+(E.calendario[i].torneo||E.calendario[i].tipo)+" vs "+E.calendario[i].rivalNombre); }
  return desorden.length?_dmal(desorden.length+" partido(s) jugados DESPUÉS del próximo (inserción mal fechada)",desorden)
                        :_dok("apunta a "+(p.torneo||p.tipo)+" vs "+p.rivalNombre);
}});
