        const g1=mk("Grupo A"), g2=mk("Grupo A"); E.calendario=[g1,g2]; foto=fotoCopa(g1); g1.jugado=true;
        if(desenlaceCopa(g1,foto,true)) f.push("a mitad de grupo ya anuncia un desenlace");
