      if(!/setTimeout\(function\(\)\{ if\(!box\._cornerFin\)/.test(mc.replace(/\s+/g," ").replace(/\s/g,""))&&!/_cornerFin\)\s*_cornerSalida/.test(mc)) f.push("sin vigilante: si la animación se corta el modal queda abierto");
