        const ch2=ofrecerAliviar3D(h,"prueba",function(){}); if(ch2){ const bs=ch2.querySelectorAll("button"); bs[bs.length-1].click(); }
        if(ofrecerAliviar3D(h,"prueba",function(){})) f.push("después de «Seguir así» vuelve a preguntar");
