      if(s.entradas&&s.barridas/s.entradas>0.55) for(let k=0;k<2;k++){ const t=devBarridas(1080); s.entradas+=t.entradas; s.barridas+=t.barridas; s.lanzas+=t.lanzas; s.min=(s.min||18)+18; }
