  const M=E.copaChile.mod; if(!M[2026]) M[2026]="clasica";
  if(M[anio]) return M[anio];
  let prev=copaChileModeloId(anio-1), desde=anio-1;
  while(desde>2026&&M[desde-1]===prev) desde--;
