          d.querySelectorAll(".hilo-linea").forEach(x=>x.remove());
          [].slice.call(d.querySelectorAll("button")).forEach(b=>{ if(/^(Ver hilo|Cerrar hilo)/.test(b.textContent)) b.remove(); });
