    const img=g.getImageData(0,0,w,h), d=img.data;
    for(let i=0;i<d.length;i+=4){ const n=(Math.random()-0.5)*26; d[i]+=n*0.6; d[i+1]+=n; d[i+2]+=n*0.4; }
