    const tela=new THREE.Mesh(new THREE.PlaneGeometry(0.5,0.34),new THREE.MeshStandardMaterial({color:0xf0c419,side:THREE.DoubleSide})); tela.position.set(0.26*cam.sg,1.32,0); bf.add(tela);
