  if(o.lean) _c3dR(B,0,0,o.lean);   /* 7.9129 · se inclina en la curva (desde los pies, como en la cancha) */
  if(o.roll){ _c3dT(B,0,c.cadera,0); _c3dR(B,0,0,o.roll); _c3dT(B,0,-c.cadera,0); }
