  R.position.set(o.x,roll?lift:Math.max(0,lift),o.z);   /* 7.9132 · con giro (estirada) la cadera baja de verdad */
  K.e.set(0,o.yaw,o.lean||0,"YXZ"); R.quaternion.setFromEuler(K.e);
