  est.P=P; est.st=_cvSt;
  est.gk=[]; let n=0; for(let i=0;i<22;i++){ const p=est.st&&est.st.jug[i]; est.gk[i]=(p&&p.rol==="gk"&&n<2)?n++:-1; }
  _c3dPintar(est);
