  if(est&&est.calidad!==c3dCalidad()){ detenerCancha3D(); est=null; }
  if(est){ C3D.reusos++; clearTimeout(est.liberar); }
  else { est=_c3dConstruir(host,P); if(!est) return null; C3D.est=est; }
  if(est.P!==P||est.st!==_cvSt) _c3dPartido(est,P);
