  /* el reloj del partido espera toda la repetición (se libera al terminar o al saltar) */
  if(est.P){ est.P._celHasta=Math.max(est.P._celHasta||0,Date.now()+total*1000+1500); est.P._repGol=true; }
  _c3dRepHud(est);
