  for(let k=0;k<6;k++){ const q=V[k]; m.p.push(q[0],q[1],q[2]); m.n.push(N[0]/l,N[1]/l,N[2]/l); m.c.push(col[0],col[1],col[2]); if(U) m.t.push(U[k][0],U[k][1]); }
